  /// Timestamp when this refund request record was last modified.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for this refund request.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  orderSeller shopping_mall_order_sellers? @relation(fields: [shopping_mall_order_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_refund_requests_shopping_mall_order_sell_92f0cabf")
  buyer shopping_mall_buyers @relation(fields: [shopping_mall_buyer_id], references: [id], onDelete: Cascade)
