  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  review shopping_mall_reviews @relation(fields: [shopping_mall_review_id], references: [id], onDelete: Cascade, map: "shopping_mall_review_seller_responses_shopping_mall_re_ed848b82")
  // spellchecker: ignore-next-line
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_review_seller_responses_shopping_mall_se_8cfee6fd")

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_review_id], map: "shopping_mall_review_seller_responses_shopping_mall_re_530caaae")

  // spellchecker: ignore-next-line
