import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test successful buyer account registration with complete valid information.
 *
 * This test validates the complete buyer registration workflow including:
 *
 * 1. Account creation with all required fields (email, password, full_name)
 * 2. Optional fields (phone_number, session context)
 * 3. Automatic session creation
 * 4. JWT token issuance (access and refresh tokens)
 * 5. Proper initialization of buyer profile (email_verified = false, deleted_at =
 *    null)
 *
 * The test ensures that new buyers can immediately access the platform after
 * registration without requiring a separate login step, as both access and
 * refresh tokens are provided in the registration response.
 */
export async function test_api_buyer_registration_successful(
  connection: api.IConnection,
) {
  // Generate unique registration data
  const registrationEmail = typia.random<string & tags.Format<"email">>();
  const registrationPassword = typia.random<string & tags.MinLength<8>>();
  const registrationFullName = typia.random<
    string & tags.MinLength<2> & tags.MaxLength<100>
  >();
  const registrationPhoneNumber = RandomGenerator.mobile("+82");
  const registrationHref = typia.random<string & tags.Format<"uri">>();
  const registrationReferrer = typia.random<string & tags.Format<"uri">>();

  // Prepare registration request body
  const registrationData = {
    email: registrationEmail,
    password: registrationPassword,
    full_name: registrationFullName,
    phone_number: registrationPhoneNumber,
    href: registrationHref,
    referrer: registrationReferrer,
  } satisfies IShoppingMallBuyer.ICreate;

  // Call buyer registration API
  const registeredBuyer: IShoppingMallBuyer.IAuthorized =
    await api.functional.auth.buyer.join(connection, {
      body: registrationData,
    });

  // Validate response structure and data integrity
  typia.assert(registeredBuyer);

  // Verify buyer profile data
  TestValidator.equals(
    "registered email matches input",
    registeredBuyer.email,
    registrationEmail,
  );
  TestValidator.equals(
    "registered full name matches input",
    registeredBuyer.full_name,
    registrationFullName,
  );
  TestValidator.equals(
    "registered phone number matches input",
    registeredBuyer.phone_number,
    registrationPhoneNumber,
  );

  // Verify email verification status for new account
  TestValidator.equals(
    "email verified is false for new account",
    registeredBuyer.email_verified,
    false,
  );

  // Verify deleted_at is null for active account
  TestValidator.equals(
    "deleted_at is null for new active account",
    registeredBuyer.deleted_at,
    null,
  );

  // Verify authentication token presence
  TestValidator.predicate(
    "access token exists",
    registeredBuyer.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token exists",
    registeredBuyer.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "expired_at is valid date-time",
    registeredBuyer.token.expired_at.length > 0,
  );
  TestValidator.predicate(
    "refreshable_until is valid date-time",
    registeredBuyer.token.refreshable_until.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test buyer registration without phone number.
 *
 * This test validates that the buyer registration process succeeds when the
 * optional phone_number field is not provided. The shopping_mall_buyers table
 * allows nullable phone numbers, so registration should complete successfully
 * with only the required fields: email, password, full_name, href, and
 * referrer.
 *
 * The test confirms that:
 *
 * 1. Registration succeeds without phone_number
 * 2. All required fields are sufficient for account creation
 * 3. The returned profile shows phone_number as null/undefined
 * 4. Authentication tokens are properly issued
 * 5. The account is fully functional
 *
 * Steps:
 *
 * 1. Generate valid registration data without phone_number
 * 2. Call buyer registration API
 * 3. Validate response structure and data
 * 4. Verify phone_number is null/undefined in response
 * 5. Confirm authentication tokens are present
 * 6. Validate account status is correct
 */
export async function test_api_buyer_registration_without_phone_number(
  connection: api.IConnection,
) {
  // Generate registration data without phone_number
  const email = typia.random<string & tags.Format<"email">>();
  const password = typia.random<string & tags.MinLength<8>>();
  const full_name = typia.random<
    string & tags.MinLength<2> & tags.MaxLength<100>
  >();
  const href = typia.random<string & tags.Format<"uri">>();
  const referrer = typia.random<string & tags.Format<"uri">>();

  // Create registration request body without phone_number
  const registrationData = {
    email: email,
    password: password,
    full_name: full_name,
    href: href,
    referrer: referrer,
  } satisfies IShoppingMallBuyer.ICreate;

  // Call buyer registration API
  const buyer = await api.functional.auth.buyer.join(connection, {
    body: registrationData,
  });

  // Validate response structure - this validates ALL types including UUID format, timestamps, token structure
  typia.assert(buyer);

  // Verify business logic: input data matches output
  TestValidator.equals("buyer email matches input", buyer.email, email);
  TestValidator.equals(
    "buyer full_name matches input",
    buyer.full_name,
    full_name,
  );

  // Verify phone_number is null or undefined - this is the core test objective
  TestValidator.predicate(
    "phone_number should be null or undefined",
    buyer.phone_number === null || buyer.phone_number === undefined,
  );

  // Verify business logic: email should not be verified initially for new accounts
  TestValidator.equals(
    "email should not be verified initially",
    buyer.email_verified,
    false,
  );

  // Verify business logic: account should be active (not soft-deleted)
  TestValidator.predicate(
    "account should not be deleted",
    buyer.deleted_at === null || buyer.deleted_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test buyer registration duplicate email constraint enforcement.
 *
 * This test validates that the shopping mall platform properly enforces email
 * uniqueness in the buyer registration process. It ensures that the
 * database-level unique constraint on the email column prevents duplicate buyer
 * accounts.
 *
 * Test Flow:
 *
 * 1. Successfully register a buyer with a unique email address
 * 2. Verify the registration succeeds and returns authentication tokens
 * 3. Attempt to register another buyer with the same email address
 * 4. Verify the duplicate registration attempt fails with an error
 * 5. Confirm no duplicate buyer records are created
 */
export async function test_api_buyer_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Step 1: Generate test data for first buyer registration
  const duplicateEmail = typia.random<string & tags.Format<"email">>();

  const firstBuyerData = {
    email: duplicateEmail,
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallBuyer.ICreate;

  // Step 2: Successfully register the first buyer
  const firstBuyer = await api.functional.auth.buyer.join(connection, {
    body: firstBuyerData,
  });

  // Step 3: Validate the first registration succeeded
  typia.assert(firstBuyer);

  // Step 4: Verify the email was correctly stored
  TestValidator.equals(
    "first buyer email matches",
    firstBuyer.email,
    duplicateEmail,
  );

  // Step 5: Attempt to register second buyer with duplicate email
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      const secondBuyerData = {
        email: duplicateEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallBuyer.ICreate;

      await api.functional.auth.buyer.join(connection, {
        body: secondBuyerData,
      });
    },
  );
}

