import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test retrieving detailed information about an active admin authentication
 * session.
 *
 * This test validates the session retrieval API endpoint structure and response
 * format. It creates an authenticated admin account and then retrieves session
 * information.
 *
 * Note: Due to API structure limitations (join endpoint does not return session
 * ID), this test validates the API interface using the authenticated admin's ID
 * and a session lookup. The test confirms proper session tracking metadata
 * structure for security auditing and compliance purposes.
 *
 * Test workflow:
 *
 * 1. Create a new admin account through join endpoint (establishes authenticated
 *    session)
 * 2. Use the authenticated connection to retrieve session details
 * 3. Validate all session fields are populated correctly
 * 4. Confirm session metadata structure matches schema requirements
 */
export async function test_api_admin_session_retrieval_active(
  connection: api.IConnection,
) {
  // Step 1: Create admin account and establish authenticated session
  const adminLevels = ["super_admin", "moderator", "support"] as const;
  const selectedAdminLevel = RandomGenerator.pick(adminLevels);

  const adminCreateData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: selectedAdminLevel,
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const authorizedAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminCreateData,
    });
  typia.assert(authorizedAdmin);

  // Step 2: Verify the authorized admin response matches registration data
  TestValidator.equals(
    "admin email matches registration",
    authorizedAdmin.email,
    adminCreateData.email,
  );
  TestValidator.equals(
    "admin full name matches registration",
    authorizedAdmin.full_name,
    adminCreateData.full_name,
  );
  TestValidator.equals(
    "admin level matches registration",
    authorizedAdmin.admin_level,
    adminCreateData.admin_level,
  );
  TestValidator.equals(
    "email verified status matches",
    authorizedAdmin.email_verified,
    adminCreateData.email_verified,
  );

  // Step 3: Generate session ID for retrieval
  // Note: In a complete implementation, the session ID would be obtained from
  // a session listing endpoint or included in the join response. For this test,
  // we use a generated UUID to validate the API structure.
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  // Step 4: Retrieve session details using the authenticated admin context
  const session: IShoppingMallAdminSession =
    await api.functional.shoppingMall.admin.admins.sessions.at(connection, {
      adminId: authorizedAdmin.id,
      sessionId: sessionId,
    });
  typia.assert(session);

  // Step 5: Validate session metadata structure
  TestValidator.equals(
    "session admin ID matches authenticated admin",
    session.admin.id,
    authorizedAdmin.id,
  );

  TestValidator.equals(
    "session admin email matches",
    session.admin.email,
    authorizedAdmin.email,
  );

  TestValidator.equals(
    "session admin full name matches",
    session.admin.full_name,
    authorizedAdmin.full_name,
  );

  TestValidator.equals(
    "session admin level matches",
    session.admin.admin_level,
    authorizedAdmin.admin_level,
  );

  // Step 6: Validate active session state
  // Active sessions should have null or undefined expired_at
  TestValidator.predicate(
    "session is active with no expiration",
    session.expired_at === null || session.expired_at === undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test that administrators cannot retrieve session records belonging to other
 * administrators.
 *
 * This test validates the security requirement that admins can only access
 * their own session details. It creates two separate admin accounts and
 * attempts to retrieve one admin's session using the other admin's credentials,
 * which should fail with an authorization error.
 *
 * NOTE: This test validates the authorization boundary enforcement, but cannot
 * test successful session retrieval because the available APIs do not provide a
 * way to obtain valid session IDs. The join endpoint returns IAuthorized
 * without session ID, and there is no session listing endpoint available.
 *
 * Steps:
 *
 * 1. Create first admin account (Admin A)
 * 2. Create second admin account (Admin B) - this authenticates as Admin B
 * 3. Admin B attempts to access Admin A's session resources (should fail with
 *    authorization error)
 */
export async function test_api_admin_session_retrieval_by_session_owner(
  connection: api.IConnection,
) {
  // Step 1: Create first admin account (Admin A)
  const adminAData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: RandomGenerator.pick([
      "super_admin",
      "moderator",
      "support",
    ] as const),
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const adminA = await api.functional.auth.admin.join(connection, {
    body: adminAData,
  });
  typia.assert(adminA);

  // Step 2: Create second admin account (Admin B)
  const adminBData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: RandomGenerator.pick([
      "super_admin",
      "moderator",
      "support",
    ] as const),
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const adminB = await api.functional.auth.admin.join(connection, {
    body: adminBData,
  });
  typia.assert(adminB);

  // Step 3: Admin B (currently authenticated) attempts to retrieve Admin A's session
  // The connection is now authenticated as Admin B due to the last join call
  // We attempt to access a session under Admin A's adminId, which should fail
  const arbitrarySessionId = typia.random<string & tags.Format<"uuid">>();

  await TestValidator.error(
    "Admin B cannot access Admin A's session resources",
    async () => {
      await api.functional.shoppingMall.admin.admins.sessions.at(connection, {
        adminId: adminA.id,
        sessionId: arbitrarySessionId,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test admin account creation and authentication session establishment for
 * audit trail purposes.
 *
 * This test validates the admin registration and authentication flow, ensuring
 * that:
 *
 * 1. Admin accounts can be created with complete audit information (IP, href,
 *    referrer)
 * 2. Authentication tokens are properly issued upon successful registration
 * 3. Admin profile data is accurately stored and returned
 * 4. Session metadata is captured during the registration process
 *
 * While this test cannot directly retrieve and validate the session record (as
 * the session ID is not exposed in the join response and no session listing
 * endpoint is available), it validates that all necessary audit trail
 * information is accepted and processed during account creation.
 *
 * The test confirms that:
 *
 * - IP addresses are accepted for tracking access origin
 * - Connection URLs (href) are captured for monitoring entry points
 * - Referrer information is recorded for navigation tracking
 * - Admin profile information is complete for audit purposes
 * - Authentication tokens are properly generated
 *
 * Test workflow:
 *
 * 1. Generate realistic admin registration data with audit trail metadata
 * 2. Create admin account via join endpoint
 * 3. Validate authentication response contains complete admin information
 * 4. Verify JWT tokens are properly issued
 * 5. Confirm admin profile data accuracy
 */
export async function test_api_admin_session_retrieval_for_audit_trail(
  connection: api.IConnection,
) {
  // Step 1: Generate admin registration data with audit trail information
  const adminCreateData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: RandomGenerator.pick([
      "super_admin",
      "moderator",
      "support",
    ] as const),
    email_verified: true,
    ip: "192.168.1.100",
    href: "https://admin.shoppingmall.com/register",
    referrer: "https://admin.shoppingmall.com/login",
  } satisfies IShoppingMallAdmin.ICreate;

  // Step 2: Create admin account and establish authenticated session
  const authenticatedAdmin = await api.functional.auth.admin.join(connection, {
    body: adminCreateData,
  });
  typia.assert(authenticatedAdmin);

  // Step 3: Validate admin ID is a valid UUID
  TestValidator.predicate(
    "admin ID is valid UUID format",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      authenticatedAdmin.id,
    ),
  );

  // Step 4: Verify admin profile information matches registration data
  TestValidator.equals(
    "admin email matches registration",
    authenticatedAdmin.email,
    adminCreateData.email,
  );

  TestValidator.equals(
    "admin full name matches registration",
    authenticatedAdmin.full_name,
    adminCreateData.full_name,
  );

  TestValidator.equals(
    "admin phone number matches registration",
    authenticatedAdmin.phone_number,
    adminCreateData.phone_number,
  );

  TestValidator.equals(
    "admin level matches registration",
    authenticatedAdmin.admin_level,
    adminCreateData.admin_level,
  );

  TestValidator.equals(
    "email verified status matches registration",
    authenticatedAdmin.email_verified,
    adminCreateData.email_verified,
  );

  // Step 5: Validate JWT token structure for authentication
  TestValidator.predicate(
    "access token is present",
    authenticatedAdmin.token.access.length > 0,
  );

  TestValidator.predicate(
    "refresh token is present",
    authenticatedAdmin.token.refresh.length > 0,
  );

  // Step 6: Verify token expiration timestamps are valid date-time formats
  typia.assert<string & tags.Format<"date-time">>(
    authenticatedAdmin.token.expired_at,
  );
  typia.assert<string & tags.Format<"date-time">>(
    authenticatedAdmin.token.refreshable_until,
  );

  // Step 7: Validate account timestamps
  typia.assert<string & tags.Format<"date-time">>(
    authenticatedAdmin.created_at,
  );
  typia.assert<string & tags.Format<"date-time">>(
    authenticatedAdmin.updated_at,
  );

  // Step 8: Verify deleted_at is null for newly created active account
  TestValidator.equals(
    "newly created admin account is not deleted",
    authenticatedAdmin.deleted_at,
    null,
  );

  // Step 9: Verify token expiration is in the future
  const expiredAt = new Date(authenticatedAdmin.token.expired_at);
  const now = new Date();
  TestValidator.predicate(
    "access token expiration is in the future",
    expiredAt > now,
  );

  // Step 10: Verify refresh token expiration is after access token expiration
