    await api.functional.shoppingMall.buyer.buyers.me.cart.items.create(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: sku.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  // Step 9: Create order
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.buyer.orders.create(connection, {
      body: {
        cart_item_ids: [cartItem.id],
        buyer_address_id: address.id,
        payment_method_id: paymentMethod.id,
      } satisfies IShoppingMallOrder.ICreate,
    });
  typia.assert(order);

  // Step 10: Buyer submits refund request
  const refundRequest: IShoppingMallRefundRequest =
    await api.functional.shoppingMall.buyer.refundRequests.create(connection, {
      body: {
        shopping_mall_order_id: order.id,
        refund_reason: "defective_product",
        refund_explanation: RandomGenerator.paragraph({ sentences: 20 }),
        requested_amount: order.total_amount,
        return_required: true,
      } satisfies IShoppingMallRefundRequest.ICreate,
    });
  typia.assert(refundRequest);
  TestValidator.equals(
    "refund request has correct order ID",
    refundRequest.shopping_mall_order_id,
    order.id,
  );
  TestValidator.equals(
    "refund request status is requested",
    refundRequest.status,
    "requested",
  );

  // Step 11: Admin authenticates and deletes the refund request
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ILogin,
  });

  const deletedRefundRequest: IShoppingMallRefundRequest =
    await api.functional.shoppingMall.admin.refundRequests.erase(connection, {
      refundRequestId: refundRequest.id,
    });
  typia.assert(deletedRefundRequest);
  TestValidator.equals(
    "deleted refund request ID matches",
    deletedRefundRequest.id,
    refundRequest.id,
  );
  TestValidator.equals(
    "deleted refund request has correct order",
    deletedRefundRequest.shopping_mall_order_id,
    order.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallPaymentMethod";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";

/**
 * Test the buyer's ability to search and retrieve their saved payment methods
 * with filtering and pagination.
 *
 * This test validates comprehensive payment method search functionality
 * including:
 *
 * - Filtering by payment type, card brand, verification status, and default
 *   status
 * - Date range filtering by creation date
 * - Pagination with various page sizes and page numbers
 * - Sorting by different fields in ascending and descending order
 * - Combined filter scenarios
 * - Accurate pagination metadata validation
 *
 * The test creates a buyer account and registers 15+ payment methods with
 * diverse attributes to thoroughly test all filtering and pagination
 * capabilities.
 */
export async function test_api_payment_methods_search_and_filter(
  connection: api.IConnection,
) {
  // Step 1: Create buyer account
  const buyerEmail = typia.random<string & tags.Format<"email">>();
  const buyer = await api.functional.auth.buyer.join(connection, {
    body: {
      email: buyerEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: "https://test.example.com/register",
      referrer: "https://test.example.com/home",
    } satisfies IShoppingMallBuyer.ICreate,
  });
  typia.assert(buyer);

  // Step 2: Create diverse payment methods for testing
  const paymentTypes = [
    "credit_card",
    "debit_card",
    "paypal",
    "apple_pay",
    "google_pay",
  ] as const;
  const cardBrands = ["visa", "mastercard", "amex"] as const;
  const providers = ["Stripe", "PayPal", "Square"] as const;

  const baseTime = new Date().getTime();
  const createdPaymentMethods: IShoppingMallPaymentMethod[] = [];

  // Create 15 payment methods with varied attributes
  for (let i = 0; i < 15; i++) {
    const paymentType = RandomGenerator.pick(paymentTypes);
    const isCard =
      paymentType === "credit_card" || paymentType === "debit_card";

    const paymentMethodData = {
      payment_type: paymentType,
      provider: RandomGenerator.pick(providers),
      provider_token: `tok_${typia.random<string & tags.Format<"uuid">>()}`,
      card_brand: isCard ? RandomGenerator.pick(cardBrands) : undefined,
      last_four_digits: isCard
        ? typia
            .random<
              number &
                tags.Type<"int32"> &
                tags.Minimum<1000> &
                tags.Maximum<9999>
            >()
            .toString()
        : undefined,
      expiry_month: isCard
        ? typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
          >()
        : undefined,
      expiry_year: isCard
        ? typia.random<number & tags.Type<"int32"> & tags.Minimum<2024>>()
        : undefined,
      billing_name: RandomGenerator.name(),
      billing_postal_code: isCard
        ? typia
            .random<
              number &
                tags.Type<"int32"> &
                tags.Minimum<10000> &
                tags.Maximum<99999>
            >()
            .toString()
        : undefined,
      is_default: i === 0,
    } satisfies IShoppingMallPaymentMethod.ICreate;

    const created =
      await api.functional.shoppingMall.buyer.paymentMethods.create(
        connection,
        {
          body: paymentMethodData,
        },
      );
    typia.assert(created);
    createdPaymentMethods.push(created);

    // Add small delay to ensure different creation timestamps
    await new Promise((resolve) => setTimeout(resolve, 10));
  }

  // Step 3: Test filtering by payment_type
  const creditCardFilter =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        payment_type: "credit_card",
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(creditCardFilter);

  // Validate all returned items match the filter criteria
  for (const pm of creditCardFilter.data) {
    TestValidator.equals(
      "payment type is credit_card",
      pm.payment_type,
      "credit_card",
    );
  }

  // Step 4: Test filtering by card_brand
  const visaFilter =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        card_brand: "visa",
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(visaFilter);

  for (const pm of visaFilter.data) {
    TestValidator.equals("card brand is visa", pm.card_brand, "visa");
  }

  // Step 5: Test filtering by is_verified
  const verifiedFilter =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        is_verified: true,
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(verifiedFilter);

  for (const pm of verifiedFilter.data) {
    TestValidator.equals("payment method is verified", pm.is_verified, true);
  }

  // Step 6: Test filtering by is_default
  const defaultFilter =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        is_default: true,
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(defaultFilter);

  TestValidator.predicate(
    "only one default payment method",
    defaultFilter.data.length <= 1,
  );
  if (defaultFilter.data.length === 1) {
    TestValidator.equals(
      "payment method is default",
      defaultFilter.data[0].is_default,
      true,
    );
  }

  // Step 7: Test pagination with different page sizes
  const page1Limit5 =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(page1Limit5);

  TestValidator.predicate(
    "page 1 has at most 5 items",
    page1Limit5.data.length <= 5,
  );
  TestValidator.equals("current page is 1", page1Limit5.pagination.current, 1);
  TestValidator.equals("limit is 5", page1Limit5.pagination.limit, 5);
  TestValidator.predicate(
    "total records matches",
    page1Limit5.pagination.records >= createdPaymentMethods.length,
  );

  const page2Limit5 =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        page: 2,
        limit: 5,
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(page2Limit5);

  TestValidator.equals("current page is 2", page2Limit5.pagination.current, 2);

  // Step 8: Test sorting by created_at ascending
  const sortedAsc =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        sort_by: "created_at",
        order: "asc",
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(sortedAsc);

  for (let i = 1; i < sortedAsc.data.length; i++) {
    const prev = new Date(sortedAsc.data[i - 1].created_at).getTime();
    const curr = new Date(sortedAsc.data[i].created_at).getTime();
    TestValidator.predicate("ascending order maintained", prev <= curr);
  }

  // Step 9: Test sorting by created_at descending
  const sortedDesc =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        sort_by: "created_at",
        order: "desc",
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(sortedDesc);

  for (let i = 1; i < sortedDesc.data.length; i++) {
    const prev = new Date(sortedDesc.data[i - 1].created_at).getTime();
    const curr = new Date(sortedDesc.data[i].created_at).getTime();
    TestValidator.predicate("descending order maintained", prev >= curr);
  }

  // Step 10: Test sorting by billing_name
  const sortedByName =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        sort_by: "billing_name",
        order: "asc",
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(sortedByName);

  for (let i = 1; i < sortedByName.data.length; i++) {
    TestValidator.predicate(
      "billing name alphabetical order",
      sortedByName.data[i - 1].billing_name <=
        sortedByName.data[i].billing_name,
    );
  }

  // Step 11: Test combined filters (payment_type + is_verified)
  const combinedFilter =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {
        payment_type: "credit_card",
        is_verified: true,
      } satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(combinedFilter);

  for (const pm of combinedFilter.data) {
    TestValidator.equals(
      "combined filter payment type",
      pm.payment_type,
      "credit_card",
    );
    TestValidator.equals(
      "combined filter verified status",
      pm.is_verified,
      true,
    );
  }

  // Step 12: Test date range filtering
  if (createdPaymentMethods.length > 0) {
    const firstCreated = createdPaymentMethods[0].created_at;
    const lastCreated =
      createdPaymentMethods[createdPaymentMethods.length - 1].created_at;

    const dateRangeFilter =
      await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
        body: {
          created_at_from: firstCreated,
          created_at_to: lastCreated,
        } satisfies IShoppingMallPaymentMethod.IRequest,
      });
    typia.assert(dateRangeFilter);

    for (const pm of dateRangeFilter.data) {
      const pmDate = new Date(pm.created_at).getTime();
      const fromDate = new Date(firstCreated).getTime();
      const toDate = new Date(lastCreated).getTime();

      TestValidator.predicate(
        "payment method within date range",
        pmDate >= fromDate && pmDate <= toDate,
      );
    }
  }

  // Step 13: Test last_four_digits filtering
  const cardPaymentMethods = createdPaymentMethods.filter(
    (pm) => pm.last_four_digits,
  );
  if (cardPaymentMethods.length > 0) {
    const sampleCard = cardPaymentMethods[0];
    const lastFourDigits = sampleCard.last_four_digits;

    if (lastFourDigits !== null && lastFourDigits !== undefined) {
      const lastFourFilter =
        await api.functional.shoppingMall.buyer.paymentMethods.index(
          connection,
          {
            body: {
              last_four_digits: lastFourDigits,
            } satisfies IShoppingMallPaymentMethod.IRequest,
          },
        );
      typia.assert(lastFourFilter);

      for (const pm of lastFourFilter.data) {
        if (pm.last_four_digits) {
          TestValidator.predicate(
            "last four digits contains search term",
            pm.last_four_digits.includes(lastFourDigits),
          );
        }
      }
    }
  }

  // Step 14: Validate pagination metadata consistency
  const allPaymentMethods =
    await api.functional.shoppingMall.buyer.paymentMethods.index(connection, {
      body: {} satisfies IShoppingMallPaymentMethod.IRequest,
    });
  typia.assert(allPaymentMethods);

  const expectedPages = Math.ceil(
    allPaymentMethods.pagination.records / allPaymentMethods.pagination.limit,
  );
  TestValidator.equals(
    "pagination pages calculation",
    allPaymentMethods.pagination.pages,
    expectedPages,
  );
  TestValidator.predicate(
    "data length within limit",
    allPaymentMethods.data.length <= allPaymentMethods.pagination.limit,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallReviewImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReviewImage";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import type { IShoppingMallBuyerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyerAddress";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallOrderSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderSeller";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallReviewImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReviewImage";
import type { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import type { IShoppingMallSaleSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleSku";
import type { IShoppingMallSaleVariantAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantAttribute";
import type { IShoppingMallSaleVariantValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantValue";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test searching and retrieving review images with pagination and sorting.
 *
 * This test validates the complete workflow of creating a review with multiple
 * images and then searching through those images using various pagination and
 * sorting options. It ensures that the review images search API correctly
 * handles pagination parameters, sorting criteria, and returns complete image
 * data with accurate metadata.
 *
 * Workflow:
 *
 * 1. Create buyer account and authenticate
 * 2. Create admin account for category setup
 * 3. Create product category
 * 4. Create seller account
 * 5. Create product sale listing
 * 6. Create product SKU variant
 * 7. Add SKU to buyer's cart
 * 8. Create delivery address for buyer
 * 9. Register payment method for buyer
 * 10. Create order from cart items
 * 11. Submit product review with multiple images
 * 12. Search review images with default pagination
 * 13. Search with custom page size and sorting by created_at descending
 * 14. Search with sorting by display_order ascending
 * 15. Verify pagination metadata accuracy
 * 16. Verify image URLs are properly returned
 * 17. Verify images are sorted according to requested parameters
 */
export async function test_api_review_images_search_with_pagination(
  connection: api.IConnection,
) {
  // 1. Create buyer account
  const buyerEmail = typia.random<string & tags.Format<"email">>();
  const buyerPassword = typia.random<string & tags.MinLength<8>>();
  const buyer = await api.functional.auth.buyer.join(connection, {
    body: {
      email: buyerEmail,
      password: buyerPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ICreate,
  });
  typia.assert(buyer);

  // 2. Create admin account for category setup
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // 3. Create product category
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // 4. Create seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.name(3),
      business_description: RandomGenerator.paragraph({ sentences: 10 }),
      store_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // 5. Create product sale listing
  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        shopping_mall_category_id: category.id,
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 3 }),
        brand: RandomGenerator.name(1),
        condition: "new",
        return_policy_days: 30,
        warranty_info: RandomGenerator.paragraph({ sentences: 5 }),
      } satisfies IShoppingMallSale.ICreate,
    },
  );
  typia.assert(sale);

  // 6. Create product SKU variant
  const sku = await api.functional.shoppingMall.seller.sales.skus.create(
    connection,
    {
      saleCode: sale.code,
      body: {
        sku_code: RandomGenerator.alphaNumeric(10),
        variant_combination: JSON.stringify({ Color: "Red", Size: "Large" }),
        base_price: 99.99,
        enabled: true,
      } satisfies IShoppingMallSaleSku.ICreate,
    },
  );
  typia.assert(sku);

  // Switch to buyer account
  await api.functional.auth.buyer.login(connection, {
    body: {
      email: buyerEmail,
      password: buyerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ILogin,
  });

  // 7. Add SKU to buyer's cart
  const cartItem =
    await api.functional.shoppingMall.buyer.buyers.me.cart.items.create(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: sku.id,
          quantity: 1,
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  // 8. Create delivery address
  const address =
    await api.functional.shoppingMall.buyer.buyers.me.addresses.create(
      connection,
      {
        body: {
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          street_address_line1: RandomGenerator.paragraph({ sentences: 3 }),
          city: RandomGenerator.name(1),
          state: RandomGenerator.name(1),
          postal_code: typia
            .random<
              number &
                tags.Type<"uint32"> &
                tags.Minimum<10000> &
                tags.Maximum<99999>
            >()
            .toString(),
          country: "USA",
          address_label: "Home",
          address_type: "residential",
          is_default: true,
        } satisfies IShoppingMallBuyerAddress.ICreate,
      },
    );
  typia.assert(address);

  // 9. Register payment method
  const paymentMethod =
    await api.functional.shoppingMall.buyer.paymentMethods.create(connection, {
      body: {
        payment_type: "credit_card",
        provider: "Stripe",
        provider_token: RandomGenerator.alphaNumeric(32),
        card_brand: "visa",
        last_four_digits: typia
          .random<
            number &
              tags.Type<"uint32"> &
              tags.Minimum<1000> &
              tags.Maximum<9999>
          >()
          .toString(),
        expiry_month: 12,
        expiry_year: 2026,
        billing_name: RandomGenerator.name(),
        billing_postal_code: typia
          .random<
            number &
              tags.Type<"uint32"> &
              tags.Minimum<10000> &
              tags.Maximum<99999>
          >()
          .toString(),
        is_default: true,
      } satisfies IShoppingMallPaymentMethod.ICreate,
    });
  typia.assert(paymentMethod);

  // 10. Create order from cart items
  const order = await api.functional.shoppingMall.buyer.orders.create(
    connection,
    {
      body: {
        cart_item_ids: [cartItem.id],
        buyer_address_id: address.id,
        payment_method_id: paymentMethod.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);

  // 11. Submit product review with multiple images (create 5 images for pagination testing)
  const reviewImages = ArrayUtil.repeat(5, (index) => {
    const baseUrl = typia.random<string & tags.Format<"uri">>();
    return {
      image_url: baseUrl,
      thumbnail_url: `${baseUrl}/thumbnail`,
      medium_url: `${baseUrl}/medium`,
      display_order: index,
    } satisfies IShoppingMallReviewImage.ICreate;
  });

  const review = await api.functional.shoppingMall.buyer.reviews.create(
    connection,
    {
      body: {
        shopping_mall_sale_id: sale.id,
        shopping_mall_sale_sku_id: sku.id,
        shopping_mall_order_id: order.id,
        star_rating: 5,
        review_title: RandomGenerator.paragraph({ sentences: 2 }),
        review_body: RandomGenerator.content({ paragraphs: 2 }),
        is_anonymous: false,
        images: reviewImages,
      } satisfies IShoppingMallReview.ICreate,
    },
  );
  typia.assert(review);

  // 12. Search review images with default pagination (should return sorted by display_order)
  const defaultSearch = await api.functional.shoppingMall.reviews.images.index(
    connection,
    {
      reviewId: review.id,
      body: {} satisfies IShoppingMallReviewImage.IRequest,
    },
  );
  typia.assert(defaultSearch);

  // Verify pagination metadata for default search
  TestValidator.predicate(
    "default search returns pagination data",
    defaultSearch.pagination.records === 5,
  );
  TestValidator.predicate(
    "default search has correct page count",
    defaultSearch.pagination.pages >= 1,
  );

  // 13. Search with custom page size and sorting by created_at descending
  const customSearch = await api.functional.shoppingMall.reviews.images.index(
    connection,
    {
      reviewId: review.id,
      body: {
        page: 1,
        limit: 3,
        sort: "-created_at",
      } satisfies IShoppingMallReviewImage.IRequest,
    },
  );
  typia.assert(customSearch);

  // Verify pagination metadata for custom search
  TestValidator.equals(
    "custom search page number",
    customSearch.pagination.current,
    1,
  );
  TestValidator.equals(
    "custom search page limit",
    customSearch.pagination.limit,
    3,
  );
  TestValidator.equals(
    "custom search total records",
    customSearch.pagination.records,
    5,
  );
  TestValidator.predicate(
    "custom search returns at most 3 items",
    customSearch.data.length <= 3,
  );

  // 14. Search with sorting by display_order ascending
  const sortedByOrder = await api.functional.shoppingMall.reviews.images.index(
    connection,
    {
      reviewId: review.id,
      body: {
        page: 1,
        limit: 10,
        sort: "display_order",
      } satisfies IShoppingMallReviewImage.IRequest,
    },
  );
  typia.assert(sortedByOrder);

  // 15. Verify pagination metadata accuracy
  TestValidator.equals(
    "sorted search total records matches created images",
    sortedByOrder.pagination.records,
    5,
  );
  TestValidator.predicate(
    "sorted search returns all images in single page",
    sortedByOrder.data.length === 5,
  );

  // 16. Verify image URLs (original, thumbnail, medium) are properly returned
  TestValidator.predicate(
    "all images have original URL",
    sortedByOrder.data.every(
      (img) => img.image_url !== null && img.image_url !== undefined,
    ),
  );
  TestValidator.predicate(
    "all images have thumbnail URL",
    sortedByOrder.data.every(
      (img) => img.thumbnail_url !== null && img.thumbnail_url !== undefined,
    ),
  );
  TestValidator.predicate(
    "all images have medium URL",
    sortedByOrder.data.every(
      (img) => img.medium_url !== null && img.medium_url !== undefined,
    ),
  );

  // 17. Verify images are sorted by display_order ascending
  TestValidator.predicate(
    "images sorted by display_order ascending",
    sortedByOrder.data.every((img, idx) => {
      if (idx === 0) return true;
      return sortedByOrder.data[idx - 1].display_order <= img.display_order;
    }),
  );

  // Verify all images belong to the correct review
  TestValidator.predicate(
    "all images belong to the review",
    sortedByOrder.data.every(
      (img) => img.shopping_mall_review_id === review.id,
    ),
  );
}

