  typia.assert(seller);

  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        shopping_mall_category_id: category.id,
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        condition: "new",
        return_policy_days: 30,
      } satisfies IShoppingMallSale.ICreate,
    },
  );
  typia.assert(sale);

  const sku = await api.functional.shoppingMall.seller.sales.skus.create(
    connection,
    {
      saleCode: sale.code,
      body: {
        sku_code: RandomGenerator.alphaNumeric(10),
        variant_combination: JSON.stringify({ Color: "Red", Size: "Large" }),
        base_price: typia.random<number & tags.Minimum<0>>(),
        enabled: true,
      } satisfies IShoppingMallSaleSku.ICreate,
    },
  );
  typia.assert(sku);

  // Step 3: Buyer authentication and purchase workflow
  const buyerEmail = typia.random<string & tags.Format<"email">>();
  const buyerPassword = typia.random<string & tags.MinLength<8>>();
  const buyer = await api.functional.auth.buyer.join(connection, {
    body: {
      email: buyerEmail,
      password: buyerPassword,
      full_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ICreate,
  });
  typia.assert(buyer);

  const deliveryAddress =
    await api.functional.shoppingMall.buyer.buyers.me.addresses.create(
      connection,
      {
        body: {
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          street_address_line1: RandomGenerator.paragraph({ sentences: 3 }),
          city: RandomGenerator.name(1),
          state: RandomGenerator.name(1),
          postal_code: RandomGenerator.alphaNumeric(5),
          country: "United States",
          address_label: "Home",
          address_type: "residential",
          is_default: true,
        } satisfies IShoppingMallBuyerAddress.ICreate,
      },
    );
  typia.assert(deliveryAddress);

  const paymentMethod =
    await api.functional.shoppingMall.buyer.paymentMethods.create(connection, {
      body: {
        payment_type: "credit_card",
        provider: "Stripe",
        provider_token: RandomGenerator.alphaNumeric(32),
        card_brand: "visa",
        last_four_digits: RandomGenerator.alphaNumeric(4),
        expiry_month: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
        >(),
        expiry_year: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<2024>
        >(),
        billing_name: RandomGenerator.name(),
        billing_postal_code: RandomGenerator.alphaNumeric(5),
        is_default: true,
      } satisfies IShoppingMallPaymentMethod.ICreate,
    });
  typia.assert(paymentMethod);

  const cartItem =
    await api.functional.shoppingMall.buyer.buyers.me.cart.items.create(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: sku.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  const order = await api.functional.shoppingMall.buyer.orders.create(
    connection,
    {
      body: {
        cart_item_ids: [cartItem.id],
        buyer_address_id: deliveryAddress.id,
        payment_method_id: paymentMethod.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);

  // Step 4: Buyer submits product review
  const review = await api.functional.shoppingMall.buyer.reviews.create(
    connection,
    {
      body: {
        shopping_mall_sale_id: sale.id,
        shopping_mall_sale_sku_id: sku.id,
        shopping_mall_order_id: order.id,
        star_rating: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
        review_title: RandomGenerator.paragraph({ sentences: 2 }),
        review_body: RandomGenerator.content({ paragraphs: 2 }),
        is_anonymous: false,
      } satisfies IShoppingMallReview.ICreate,
    },
  );
  typia.assert(review);

  // Step 5: Seller creates response to the review
  const sellerLoginResponse = await api.functional.auth.seller.login(
    connection,
    {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallSeller.ILogin,
    },
  );
  typia.assert(sellerLoginResponse);

  const sellerResponse =
    await api.functional.shoppingMall.seller.reviews.sellerResponse.create(
      connection,
      {
        reviewId: review.id,
        body: {
          response_body: RandomGenerator.content({
            paragraphs: 1,
            sentenceMin: 10,
            sentenceMax: 15,
          }),
        } satisfies IShoppingMallReviewSellerResponse.ICreate,
      },
    );
  typia.assert(sellerResponse);

  TestValidator.equals(
    "seller response review ID matches",
    sellerResponse.shopping_mall_review_id,
    review.id,
  );

  // Step 6: Seller deletes their response
  const deletedResponse =
    await api.functional.shoppingMall.seller.reviews.sellerResponse.erase(
      connection,
      {
        reviewId: review.id,
      },
    );
  typia.assert(deletedResponse);

  TestValidator.equals(
    "deleted response ID matches created response",
    deletedResponse.id,
    sellerResponse.id,
  );

  TestValidator.equals(
    "deleted response belongs to correct review",
    deletedResponse.shopping_mall_review_id,
    review.id,
  );

  TestValidator.predicate(
    "deleted response has deletion timestamp set",
    deletedResponse.deleted_at !== null &&
      deletedResponse.deleted_at !== undefined,
  );

  TestValidator.equals(
    "deleted response body matches original",
    deletedResponse.response_body,
    sellerResponse.response_body,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallBuyer";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test admin's ability to search and retrieve buyers by email address.
 *
 * This test validates the buyer search functionality with email filtering:
 *
 * 1. Create an admin account for authentication
 * 2. Create multiple buyer accounts with different email domains
 * 3. Search buyers using email filter as admin
 * 4. Validate that only matching buyers are returned
 * 5. Verify pagination metadata and buyer summary structure
 */
export async function test_api_buyer_search_with_email_filter(
  connection: api.IConnection,
) {
  // Step 1: Create admin account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create multiple buyer accounts with different email patterns
  const searchDomain = "testdomain.com";
  const otherDomain = "otherdomain.com";

  const buyersData = [
    {
      emailPrefix: RandomGenerator.alphabets(6),
      domain: searchDomain,
      name: "Alice Smith",
    },
    {
      emailPrefix: RandomGenerator.alphabets(6),
      domain: otherDomain,
      name: "Bob Johnson",
    },
    {
      emailPrefix: RandomGenerator.alphabets(6),
      domain: searchDomain,
      name: "Charlie Brown",
    },
    {
      emailPrefix: RandomGenerator.alphabets(6),
      domain: otherDomain,
      name: "David Wilson",
    },
    {
      emailPrefix: RandomGenerator.alphabets(6),
      domain: searchDomain,
      name: "Eve Davis",
    },
  ];

  const expectedMatchingEmails: string[] = [];

  for (const buyerData of buyersData) {
    const buyerEmail = `${buyerData.emailPrefix}@${buyerData.domain}`;
    const buyerConnection: api.IConnection = { ...connection, headers: {} };

    const buyer: IShoppingMallBuyer.IAuthorized =
      await api.functional.auth.buyer.join(buyerConnection, {
        body: {
          email: buyerEmail,
          password: typia.random<string & tags.MinLength<8>>(),
          full_name: buyerData.name,
          phone_number: RandomGenerator.mobile(),
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IShoppingMallBuyer.ICreate,
      });
    typia.assert(buyer);

    if (buyerEmail.includes(searchDomain)) {
      expectedMatchingEmails.push(buyerEmail);
    }
  }

  // Step 3: Search buyers by email filter (admin is already authenticated)
  const searchTerm = searchDomain;
  const searchResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        search: searchTerm,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(searchResult);

  // Step 4: Validate that all returned buyers match the search criteria
  TestValidator.predicate(
    "search should return at least the buyers we created with matching emails",
    searchResult.data.length >= expectedMatchingEmails.length,
  );

  // Step 5: Verify all returned buyers contain the search term in their email
  for (const buyerSummary of searchResult.data) {
    typia.assert(buyerSummary);

    TestValidator.predicate(
      "returned buyer email should contain search term",
      buyerSummary.email.includes(searchTerm),
    );
  }

  // Step 6: Validate pagination metadata
  typia.assert(searchResult.pagination);

  TestValidator.equals(
    "pagination current page",
    searchResult.pagination.current,
    1,
  );

  TestValidator.equals("pagination limit", searchResult.pagination.limit, 10);

  TestValidator.predicate(
    "pagination records should match or exceed data length",
    searchResult.pagination.records >= searchResult.data.length,
  );

  TestValidator.predicate(
    "pagination pages should be at least 1",
    searchResult.pagination.pages >= 1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallBuyer";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test admin's ability to search buyers by full name with partial matching.
 *
 * This test validates the buyer search functionality available to
 * administrators, focusing on partial name matching with case-insensitive text
 * search. It creates multiple buyer accounts with varied names and executes
 * different search patterns to ensure the search API correctly filters buyers
 * based on name criteria.
 *
 * The test verifies:
 *
 * 1. Admin authentication and authorization for buyer search operations
 * 2. Partial text matching in buyer full names (first name, last name, substrings)
 * 3. Case-insensitive search behavior
 * 4. Pagination functionality with configurable page and limit parameters
 * 5. Sorting capabilities (ascending/descending by full_name, email, created_at)
 * 6. Response structure conformance to IPageIShoppingMallBuyer.ISummary
 */
export async function test_api_buyer_search_with_name_filter(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        ip: "127.0.0.1",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create multiple buyer accounts with varied full names for testing
  const buyerNames = [
    "Alice Anderson",
    "Bob Builder",
    "Alice Brown",
    "Charlie Anderson",
    "David Chen",
    "Emma Wilson",
    "Frank Miller",
  ] as const;

  const buyers: IShoppingMallBuyer.IAuthorized[] = await ArrayUtil.asyncMap(
    buyerNames,
    async (fullName) => {
      const buyer = await api.functional.auth.buyer.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: typia.random<string & tags.MinLength<8>>(),
          full_name: fullName,
          phone_number: RandomGenerator.mobile(),
          ip: "127.0.0.1",
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IShoppingMallBuyer.ICreate,
      });
      typia.assert(buyer);
      return buyer;
    },
  );

  // Step 3: Test partial name search - search for "Alice"
  const aliceSearchResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        search: "Alice",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(aliceSearchResult);

  // Validate search results contain "Alice" in full_name
  TestValidator.predicate(
    "search for 'Alice' should return buyers with Alice in name",
    aliceSearchResult.data.every((buyer) => buyer.full_name.includes("Alice")),
  );

  TestValidator.predicate(
    "search for 'Alice' should return 2 buyers",
    aliceSearchResult.data.length === 2,
  );

  // Step 4: Test partial name search - search for "Anderson"
  const andersonSearchResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        search: "Anderson",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(andersonSearchResult);

  TestValidator.predicate(
    "search for 'Anderson' should return buyers with Anderson in name",
    andersonSearchResult.data.every((buyer) =>
      buyer.full_name.includes("Anderson"),
    ),
  );

  TestValidator.predicate(
    "search for 'Anderson' should return 2 buyers",
    andersonSearchResult.data.length === 2,
  );

  // Step 5: Test case-insensitive search - search for "alice" (lowercase)
  const lowercaseSearchResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        search: "alice",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(lowercaseSearchResult);

  TestValidator.predicate(
    "case-insensitive search for 'alice' should find Alice buyers",
    lowercaseSearchResult.data.length === 2,
  );

  TestValidator.predicate(
    "lowercase search should match uppercase names",
    lowercaseSearchResult.data.every((buyer) =>
      buyer.full_name.toLowerCase().includes("alice"),
    ),
  );

  // Step 6: Test pagination - limit results to 3 per page
  const paginatedResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        page: 1,
        limit: 3,
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(paginatedResult);

  TestValidator.predicate(
    "pagination limit should be respected",
    paginatedResult.data.length <= 3,
  );

  TestValidator.predicate(
    "pagination metadata should indicate current page is 1",
    paginatedResult.pagination.current === 1,
  );

  TestValidator.predicate(
    "pagination limit should match requested limit",
    paginatedResult.pagination.limit === 3,
  );

  // Step 7: Test sorting - ascending by full_name
  const ascendingSortResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        page: 1,
        limit: 10,
        orderBy: "full_name",
        sort: "asc",
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(ascendingSortResult);

  // Verify ascending order
  if (ascendingSortResult.data.length > 1) {
    for (let i = 0; i < ascendingSortResult.data.length - 1; i++) {
      TestValidator.predicate(
        "buyers should be sorted in ascending order by full_name",
        ascendingSortResult.data[i].full_name <=
          ascendingSortResult.data[i + 1].full_name,
      );
    }
  }

  // Step 8: Test sorting - descending by full_name
  const descendingSortResult: IPageIShoppingMallBuyer.ISummary =
    await api.functional.shoppingMall.admin.buyers.index(connection, {
      body: {
        page: 1,
        limit: 10,
        orderBy: "full_name",
        sort: "desc",
      } satisfies IShoppingMallBuyer.IRequest,
    });
  typia.assert(descendingSortResult);

  // Verify descending order
  if (descendingSortResult.data.length > 1) {
    for (let i = 0; i < descendingSortResult.data.length - 1; i++) {
      TestValidator.predicate(
        "buyers should be sorted in descending order by full_name",
        descendingSortResult.data[i].full_name >=
          descendingSortResult.data[i + 1].full_name,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallBuyer";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test pagination controls for buyer listing with comprehensive validation.
 *
 * This test validates that administrators can efficiently navigate through
 * buyer account lists using pagination controls. It creates a sufficient
 * dataset (25 buyers) to span multiple pages and tests various pagination
 * scenarios including different page numbers, custom limit values, and boundary
 * conditions.
 *
 * The test ensures:
 *
 * 1. Admin authentication and authorization for buyer list access
 * 2. Creation of 25 buyer accounts for multi-page testing
 * 3. Pagination metadata accuracy (current, limit, records, pages)
 * 4. Different pages return distinct buyer sets without duplicates
 * 5. Edge cases with minimum and maximum limit values
 * 6. Complete data retrieval across all pages
 */
export async function test_api_buyer_list_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create admin connection and authenticate
  const adminConnection: api.IConnection = { ...connection };
  const adminEmail = typia.random<string & tags.Format<"email">>();

  const admin = await api.functional.auth.admin.join(adminConnection, {
    body: {
      email: adminEmail,
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create 25 buyer accounts using separate connections
  const buyerCount = 25;
  const createdBuyerIds: string[] = [];

  for (let i = 0; i < buyerCount; i++) {
    const buyerConnection: api.IConnection = { ...connection };
    const buyerEmail = typia.random<string & tags.Format<"email">>();

    const buyer = await api.functional.auth.buyer.join(buyerConnection, {
      body: {
        email: buyerEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallBuyer.ICreate,
    });
    typia.assert(buyer);
    createdBuyerIds.push(buyer.id);
  }

  // Step 3: Test Case 1 - Default pagination (first page) using admin connection
  const defaultPage = await api.functional.shoppingMall.admin.buyers.index(
    adminConnection,
    {
      body: {} satisfies IShoppingMallBuyer.IRequest,
    },
  );
  typia.assert(defaultPage);

  TestValidator.predicate(
    "default pagination returns data",
    defaultPage.data.length > 0,
  );
  TestValidator.predicate(
    "pagination metadata exists",
    defaultPage.pagination !== null && defaultPage.pagination !== undefined,
  );

  // Step 4: Test Case 2 - Custom page size with limit=10
  const limit = 10;
  const page1 = await api.functional.shoppingMall.admin.buyers.index(
    adminConnection,
    {
      body: {
        page: 1,
        limit: limit,
      } satisfies IShoppingMallBuyer.IRequest,
    },
  );
  typia.assert(page1);

  TestValidator.equals("page 1 current is 1", page1.pagination.current, 1);
  TestValidator.equals("page 1 limit is 10", page1.pagination.limit, limit);
  TestValidator.predicate(
    "page 1 records count is at least buyer count",
    page1.pagination.records >= buyerCount,
  );
  TestValidator.predicate(
    "page 1 data length does not exceed limit",
    page1.data.length <= limit,
  );

  const expectedPages = Math.ceil(page1.pagination.records / limit);
  TestValidator.equals(
    "page count calculation correct",
    page1.pagination.pages,
    expectedPages,
  );

  // Step 5: Test Case 3 - Navigate to second page
  const page2 = await api.functional.shoppingMall.admin.buyers.index(
    adminConnection,
    {
      body: {
        page: 2,
        limit: limit,
      } satisfies IShoppingMallBuyer.IRequest,
    },
  );
  typia.assert(page2);

  TestValidator.equals("page 2 current is 2", page2.pagination.current, 2);
  TestValidator.equals("page 2 limit is 10", page2.pagination.limit, limit);
  TestValidator.equals(
    "page 2 total records match page 1",
    page2.pagination.records,
    page1.pagination.records,
  );

  // Verify no duplicates between page 1 and page 2
  const page1Ids = page1.data.map((b) => b.id);
  const page2Ids = page2.data.map((b) => b.id);
  const duplicates = page1Ids.filter((id) => page2Ids.includes(id));
  TestValidator.equals(
    "no duplicates between page 1 and page 2",
    duplicates.length,
    0,
  );

  // Step 6: Test Case 4 - Navigate to last page
  const lastPageNumber = page1.pagination.pages;
  if (lastPageNumber > 0) {
    const lastPage = await api.functional.shoppingMall.admin.buyers.index(
      adminConnection,
      {
        body: {
          page: lastPageNumber,
          limit: limit,
        } satisfies IShoppingMallBuyer.IRequest,
      },
    );
    typia.assert(lastPage);

    TestValidator.equals(
      "last page current matches request",
      lastPage.pagination.current,
      lastPageNumber,
    );
    TestValidator.predicate(
      "last page may have fewer items than limit",
      lastPage.data.length <= limit,
    );
  }

  // Step 7: Test Case 5 - Edge cases with boundary limits

  // Test minimum limit (1)
  const minLimitPage = await api.functional.shoppingMall.admin.buyers.index(
    adminConnection,
    {
      body: {
        page: 1,
        limit: 1,
      } satisfies IShoppingMallBuyer.IRequest,
    },
  );
  typia.assert(minLimitPage);
  TestValidator.equals("min limit is 1", minLimitPage.pagination.limit, 1);
  TestValidator.predicate(
    "min limit page returns at most 1 item",
    minLimitPage.data.length <= 1,
  );

  // Test maximum limit (100)
  const maxLimitPage = await api.functional.shoppingMall.admin.buyers.index(
    adminConnection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies IShoppingMallBuyer.IRequest,
    },
  );
  typia.assert(maxLimitPage);
  TestValidator.equals("max limit is 100", maxLimitPage.pagination.limit, 100);
  TestValidator.predicate(
    "max limit page returns at most 100 items",
    maxLimitPage.data.length <= 100,
  );

  // Step 8: Data integrity validation - collect all buyers across pages
  const allBuyerIds: string[] = [];
  const totalPages = Math.ceil(page1.pagination.records / 10);

  for (let pageNum = 1; pageNum <= totalPages; pageNum++) {
    const currentPage = await api.functional.shoppingMall.admin.buyers.index(
      adminConnection,
      {
        body: {
          page: pageNum,
          limit: 10,
        } satisfies IShoppingMallBuyer.IRequest,
      },
    );
    typia.assert(currentPage);

    currentPage.data.forEach((buyer) => {
      allBuyerIds.push(buyer.id);
    });
  }

  // Verify no duplicate IDs across all pages
  const uniqueBuyerIds = [...new Set(allBuyerIds)];
  TestValidator.equals(
    "no duplicate buyers across all pages",
    allBuyerIds.length,
    uniqueBuyerIds.length,
  );

  // Verify all created buyers are retrievable through pagination
  TestValidator.predicate(
    "pagination returns at least all created buyers",
    uniqueBuyerIds.length >= buyerCount,
  );
}

