import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test buyer profile retrieval with optional phone number handling.
 *
 * This test validates that the buyer profile API correctly handles the optional
 * phone_number field in both scenarios: when a phone number is provided during
 * registration and when it is omitted (null). The test ensures that profile
 * retrieval works correctly regardless of phone number presence and that all
 * other profile fields remain consistent.
 *
 * Test Flow:
 *
 * 1. Create first buyer account WITH phone number
 * 2. Authenticate and retrieve profile for buyer with phone
 * 3. Validate phone_number field contains the provided value
 * 4. Create second buyer account WITHOUT phone number (null)
 * 5. Authenticate and retrieve profile for buyer without phone
 * 6. Validate phone_number field is null
 * 7. Verify response structure consistency across both scenarios
 */
export async function test_api_buyer_profile_with_optional_phone(
  connection: api.IConnection,
) {
  // Create first buyer WITH phone number
  const buyerWithPhoneEmail = typia.random<string & tags.Format<"email">>();
  const buyerWithPhoneNumber = RandomGenerator.mobile();
  const buyerWithPhoneData = {
    email: buyerWithPhoneEmail,
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(),
    phone_number: buyerWithPhoneNumber,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallBuyer.ICreate;

  const buyerWithPhone = await api.functional.auth.buyer.join(connection, {
    body: buyerWithPhoneData,
  });
  typia.assert(buyerWithPhone);

  // Retrieve profile for buyer with phone number
  const profileWithPhone = await api.functional.shoppingMall.buyer.buyers.at(
    connection,
    {
      buyerId: buyerWithPhone.id,
    },
  );
  typia.assert(profileWithPhone);

  // Validate buyer with phone number
  TestValidator.equals(
    "buyer with phone - ID matches",
    profileWithPhone.id,
    buyerWithPhone.id,
  );
  TestValidator.equals(
    "buyer with phone - email matches",
    profileWithPhone.email,
    buyerWithPhoneEmail,
  );
  TestValidator.equals(
    "buyer with phone - phone_number matches",
    profileWithPhone.phone_number,
    buyerWithPhoneNumber,
  );
  TestValidator.predicate(
    "buyer with phone - phone_number is not null",
    profileWithPhone.phone_number !== null &&
      profileWithPhone.phone_number !== undefined,
  );

  // Create second buyer WITHOUT phone number (null)
  const buyerWithoutPhoneEmail = typia.random<string & tags.Format<"email">>();
  const buyerWithoutPhoneData = {
    email: buyerWithoutPhoneEmail,
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(),
    phone_number: null,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallBuyer.ICreate;

  const buyerWithoutPhone = await api.functional.auth.buyer.join(connection, {
    body: buyerWithoutPhoneData,
  });
  typia.assert(buyerWithoutPhone);

  // Retrieve profile for buyer without phone number
  const profileWithoutPhone = await api.functional.shoppingMall.buyer.buyers.at(
    connection,
    {
      buyerId: buyerWithoutPhone.id,
    },
  );
  typia.assert(profileWithoutPhone);

  // Validate buyer without phone number
  TestValidator.equals(
    "buyer without phone - ID matches",
    profileWithoutPhone.id,
    buyerWithoutPhone.id,
  );
  TestValidator.equals(
    "buyer without phone - email matches",
    profileWithoutPhone.email,
    buyerWithoutPhoneEmail,
  );
  TestValidator.equals(
    "buyer without phone - phone_number is null",
    profileWithoutPhone.phone_number,
    null,
  );

  // Verify both profiles have consistent structure for other required fields
  TestValidator.predicate(
    "buyer with phone - has full_name",
    profileWithPhone.full_name.length > 0,
  );
  TestValidator.predicate(
    "buyer without phone - has full_name",
    profileWithoutPhone.full_name.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test that buyer profile correctly displays email verification status.
 *
 * Create a new buyer account (which starts with email_verified: false by
 * default). Retrieve the profile immediately after registration to confirm that
 * email_verified is false. Validate that this field is properly exposed in the
 * profile response and reflects the buyer's verification state, which affects
 * their ability to place orders and access certain platform features.
 *
 * Steps:
 *
 * 1. Create a new buyer account with random registration data
 * 2. Verify the registration was successful and returns buyer information
 * 3. Retrieve the buyer profile using the buyer ID
 * 4. Validate that email_verified field is present and set to false
 * 5. Confirm all profile data matches the registration data
 */
export async function test_api_buyer_profile_email_verification_status(
  connection: api.IConnection,
) {
  // Step 1: Create buyer registration data
  const registrationData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(2),
    phone_number: RandomGenerator.mobile(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallBuyer.ICreate;

  // Step 2: Register the new buyer account
  const registeredBuyer: IShoppingMallBuyer.IAuthorized =
    await api.functional.auth.buyer.join(connection, {
      body: registrationData,
    });
  typia.assert(registeredBuyer);

  // Step 3: Validate registration response has expected structure
  TestValidator.equals(
    "registered buyer email matches input",
    registeredBuyer.email,
    registrationData.email,
  );
  TestValidator.equals(
    "registered buyer full_name matches input",
    registeredBuyer.full_name,
    registrationData.full_name,
  );
  TestValidator.equals(
    "registered buyer phone_number matches input",
    registeredBuyer.phone_number,
    registrationData.phone_number,
  );

  // Step 4: Verify initial email_verified status is false
  TestValidator.equals(
    "newly registered buyer email_verified is false",
    registeredBuyer.email_verified,
    false,
  );

  // Step 5: Retrieve the buyer profile using the buyer ID
  const buyerProfile: IShoppingMallBuyer =
    await api.functional.shoppingMall.buyer.buyers.at(connection, {
      buyerId: registeredBuyer.id,
    });
  typia.assert(buyerProfile);

  // Step 6: Validate profile response matches registered buyer data
  TestValidator.equals(
    "profile buyer ID matches registered buyer ID",
    buyerProfile.id,
    registeredBuyer.id,
  );
  TestValidator.equals(
    "profile email matches registered email",
    buyerProfile.email,
    registeredBuyer.email,
  );
  TestValidator.equals(
    "profile full_name matches registered full_name",
    buyerProfile.full_name,
    registeredBuyer.full_name,
  );
  TestValidator.equals(
    "profile phone_number matches registered phone_number",
    buyerProfile.phone_number,
    registeredBuyer.phone_number,
  );

  // Step 7: Critical validation - email_verified field is present and false in profile
  TestValidator.equals(
    "profile email_verified field is false for new account",
    buyerProfile.email_verified,
    false,
  );

  // Step 8: Validate timestamps are present
  typia.assert<string & tags.Format<"date-time">>(buyerProfile.created_at);
  typia.assert<string & tags.Format<"date-time">>(buyerProfile.updated_at);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test that buyer profile timestamps are correctly set and formatted.
 *
 * This test validates the timestamp accuracy and format in buyer profiles by:
 *
 * 1. Creating a new buyer account through registration
 * 2. Immediately retrieving the buyer profile
 * 3. Verifying created_at and updated_at timestamps are in ISO 8601 format
 * 4. Confirming created_at equals updated_at (no modifications yet)
 * 5. Validating deleted_at is null for active accounts
 * 6. Ensuring timestamps are reasonable relative to registration time
 */
export async function test_api_buyer_profile_timestamp_accuracy(
  connection: api.IConnection,
) {
  // Record the current time before registration for validation
  const beforeRegistration = new Date();

  // Create a new buyer account
  const registrationData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: typia.random<string & tags.MinLength<2> & tags.MaxLength<100>>(),
    phone_number: typia.random<string>(),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallBuyer.ICreate;

  const authorizedBuyer = await api.functional.auth.buyer.join(connection, {
    body: registrationData,
  });
  typia.assert(authorizedBuyer);

  // Record time after registration
  const afterRegistration = new Date();

  // Validate the authorized buyer response has proper timestamps
  TestValidator.predicate(
    "created_at should be present",
    authorizedBuyer.created_at !== null &&
      authorizedBuyer.created_at !== undefined,
  );

  TestValidator.predicate(
    "updated_at should be present",
    authorizedBuyer.updated_at !== null &&
      authorizedBuyer.updated_at !== undefined,
  );

  // Parse timestamps to validate ISO 8601 format
  const createdAtDate = new Date(authorizedBuyer.created_at);
  const updatedAtDate = new Date(authorizedBuyer.updated_at);

  // Validate timestamps are valid dates
  TestValidator.predicate(
    "created_at should be valid ISO 8601 date-time",
    !isNaN(createdAtDate.getTime()),
  );

  TestValidator.predicate(
    "updated_at should be valid ISO 8601 date-time",
    !isNaN(updatedAtDate.getTime()),
  );

  // Validate timestamps are within reasonable time range
  TestValidator.predicate(
    "created_at should be after or equal to registration start time",
    createdAtDate.getTime() >= beforeRegistration.getTime() - 1000,
  );

  TestValidator.predicate(
    "created_at should be before or equal to registration end time",
    createdAtDate.getTime() <= afterRegistration.getTime() + 1000,
  );

  // Validate created_at equals updated_at (no updates occurred)
  TestValidator.equals(
    "created_at should equal updated_at initially",
    authorizedBuyer.created_at,
    authorizedBuyer.updated_at,
  );

  // Validate deleted_at is null for active account
  TestValidator.equals(
    "deleted_at should be null for active account",
    authorizedBuyer.deleted_at,
    null,
  );

  // Retrieve the buyer profile to verify consistency
  const buyerProfile = await api.functional.shoppingMall.buyer.buyers.at(
    connection,
    {
      buyerId: authorizedBuyer.id,
    },
  );
  typia.assert(buyerProfile);

  // Validate retrieved profile timestamps match registration response
  TestValidator.equals(
    "profile created_at should match registration response",
    buyerProfile.created_at,
    authorizedBuyer.created_at,
  );

  TestValidator.equals(
    "profile updated_at should match registration response",
    buyerProfile.updated_at,
    authorizedBuyer.updated_at,
  );

  TestValidator.equals(
    "profile deleted_at should remain null",
    buyerProfile.deleted_at,
    null,
  );

  // Validate profile timestamps are still equal
  TestValidator.equals(
    "profile created_at should equal updated_at",
    buyerProfile.created_at,
    buyerProfile.updated_at,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
