        body: {
          refresh:
            "eyJhbGciOiJub25lIn0.eyJzdWIiOiIxMjM0NTY3ODkwIiwibmFtZSI6IkpvaG4gRG9lIiwiaWF0IjoxNTE2MjM5MDIyfQ.",
        } satisfies IShoppingMallBuyer.IRefresh,
      });
    },
  );
}

