    connection,
    {
      body: {
        cart_item_ids: [cartItem1.id, cartItem2.id],
        buyer_address_id: deliveryAddress.id,
        payment_method_id: paymentMethod.id,
        notes: "Please deliver during business hours",
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);

  // 16. Validate order contains seller segments
  TestValidator.predicate(
    "order contains seller segments",
    order.sellers.length === 2,
  );

  // 17. Retrieve all seller segments without filters
  const allSegments =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {} satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(allSegments);

  // 18. Validate pagination metadata
  TestValidator.equals(
    "total seller segments count",
    allSegments.pagination.records,
    2,
  );
  TestValidator.predicate(
    "segments data matches count",
    allSegments.data.length === 2,
  );

  // 19. Validate seller segments contain both sellers
  const seller1Segment = allSegments.data.find(
    (seg) => seg.seller.id === seller1.id,
  );
  const seller2Segment = allSegments.data.find(
    (seg) => seg.seller.id === seller2.id,
  );

  typia.assertGuard(seller1Segment!);
  typia.assertGuard(seller2Segment!);

  TestValidator.equals(
    "seller1 segment seller matches",
    seller1Segment.seller.id,
    seller1.id,
  );
  TestValidator.equals(
    "seller2 segment seller matches",
    seller2Segment.seller.id,
    seller2.id,
  );

  // 20. Validate financial breakdowns
  TestValidator.predicate(
    "seller1 segment has positive subtotal",
    seller1Segment.subtotal > 0,
  );
  TestValidator.predicate(
    "seller2 segment has positive subtotal",
    seller2Segment.subtotal > 0,
  );

  // 21. Test filtering by specific seller_id
  const seller1Filter =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {
        seller_id: seller1.id,
      } satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(seller1Filter);

  TestValidator.equals(
    "seller filter returns only one segment",
    seller1Filter.data.length,
    1,
  );
  TestValidator.equals(
    "filtered segment is seller1",
    seller1Filter.data[0].seller.id,
    seller1.id,
  );

  // 22. Test status filtering
  const statusFilter =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {
        status: "pending",
      } satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(statusFilter);

  TestValidator.predicate(
    "all filtered segments have pending status",
    statusFilter.data.every((seg) => seg.status === "pending"),
  );

  // 23. Test pagination with limit
  const paginatedResult =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {
        page: 1,
        limit: 1,
      } satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(paginatedResult);

  TestValidator.equals(
    "pagination limit respected",
    paginatedResult.data.length,
    1,
  );
  TestValidator.equals(
    "pagination shows correct total",
    paginatedResult.pagination.records,
    2,
  );
  TestValidator.equals(
    "pagination calculates pages correctly",
    paginatedResult.pagination.pages,
    2,
  );

  // 24. Test sorting by subtotal ascending
  const sortedBySubtotal =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {
        sort_by: "subtotal",
        sort_order: "asc",
      } satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(sortedBySubtotal);

  if (sortedBySubtotal.data.length >= 2) {
    TestValidator.predicate(
      "segments sorted by subtotal ascending",
      sortedBySubtotal.data[0].subtotal <= sortedBySubtotal.data[1].subtotal,
    );
  }

  // 25. Test search functionality
  const searchResult =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {
        search: seller1Segment.seller.store_name,
      } satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(searchResult);

  TestValidator.predicate(
    "search finds matching seller",
    searchResult.data.some((seg) => seg.seller.id === seller1.id),
  );

  // 26. Test min_subtotal filter
  const minSubtotalValue = Math.min(
    seller1Segment.subtotal,
    seller2Segment.subtotal,
  );
  const minSubtotalFilter =
    await api.functional.shoppingMall.buyer.orders.sellers.index(connection, {
      orderId: order.id,
      body: {
        min_subtotal: minSubtotalValue,
      } satisfies IShoppingMallOrderSeller.IRequest,
    });
  typia.assert(minSubtotalFilter);

  TestValidator.predicate(
    "all segments meet min_subtotal",
    minSubtotalFilter.data.every((seg) => seg.subtotal >= minSubtotalValue),
  );

  // 27. Validate sub_order_number uniqueness
  const subOrderNumbers = allSegments.data.map((seg) => seg.sub_order_number);
  const uniqueSubOrderNumbers = new Set(subOrderNumbers);
  TestValidator.equals(
    "all sub_order_numbers are unique",
    uniqueSubOrderNumbers.size,
    subOrderNumbers.length,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import type { IShoppingMallSaleQuestion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleQuestion";
import type { IShoppingMallSaleQuestionAnswer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleQuestionAnswer";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test complete workflow of buyer deleting their own product question.
 *
 * This test validates that buyers can successfully delete questions they have
 * posted about products before receiving an answer. The workflow includes:
 *
 * 1. Admin creates product category infrastructure
 * 2. Seller registers and creates a product sale listing
 * 3. Buyer registers and posts a question about the product
 * 4. Buyer deletes their own question
 * 5. Validation that deletion was successful
 *
 * This ensures the Q&A system allows buyers to remove their questions for
 * correcting mistakes or removing irrelevant inquiries.
 */
export async function test_api_product_question_deletion_by_author(
  connection: api.IConnection,
) {
  // Step 1: Admin Setup - Create and authenticate admin account
  const adminData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: RandomGenerator.pick([
      "super_admin",
      "moderator",
      "support",
    ] as const),
    email_verified: true,
    ip: undefined,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const admin = await api.functional.auth.admin.join(connection, {
    body: adminData,
  });
  typia.assert(admin);

  // Step 2: Category Creation - Admin creates product category
  const categoryData = {
    parent_id: undefined,
    name: RandomGenerator.name(2),
    slug: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    image_url: typia.random<string & tags.Format<"uri">>(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    status: RandomGenerator.pick(["active", "inactive"] as const),
  } satisfies IShoppingMallCategory.ICreate;

  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: categoryData,
    },
  );
  typia.assert(category);

  // Step 3: Seller Setup - Register seller account
  const sellerData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    business_name: RandomGenerator.name(3),
    business_description: RandomGenerator.paragraph({ sentences: 10 }),
    store_name: RandomGenerator.name(2),
    ip: undefined,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallSeller.ICreate;

  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerData,
  });
  typia.assert(seller);

  // Step 4: Product Listing - Seller creates product sale
  const saleData = {
    code: RandomGenerator.alphaNumeric(12),
    shopping_mall_category_id: category.id,
    title: RandomGenerator.paragraph({ sentences: 3 }),
    description: RandomGenerator.content({ paragraphs: 3 }),
    brand: RandomGenerator.name(1),
    condition: RandomGenerator.pick(["new", "refurbished", "used"] as const),
    short_description: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 10,
      wordMax: 15,
    }),
    meta_keywords: RandomGenerator.paragraph({ sentences: 5 }),
    weight: typia.random<number>(),
    dimension_length: typia.random<number>(),
    dimension_width: typia.random<number>(),
    dimension_height: typia.random<number>(),
    manufacturer: RandomGenerator.name(2),
    return_policy_days: RandomGenerator.pick([0, 7, 14, 30, 60] as const),
    warranty_info: RandomGenerator.paragraph({ sentences: 8 }),
    status: "published",
  } satisfies IShoppingMallSale.ICreate;

  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: saleData,
    },
  );
  typia.assert(sale);

  // Step 5: Buyer Setup - Register buyer account
  const buyerData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    ip: undefined,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallBuyer.ICreate;

  const buyer = await api.functional.auth.buyer.join(connection, {
    body: buyerData,
  });
  typia.assert(buyer);

  // Step 6: Question Submission - Buyer posts question about product
  const questionData = {
    title: RandomGenerator.paragraph({ sentences: 2, wordMin: 5, wordMax: 10 }),
    body: RandomGenerator.paragraph({ sentences: 8, wordMin: 5, wordMax: 12 }),
  } satisfies IShoppingMallSaleQuestion.ICreate;

  const question =
    await api.functional.shoppingMall.buyer.sales.questions.postBySalecode(
      connection,
      {
        saleCode: sale.code,
        body: questionData,
      },
    );
  typia.assert(question);

  // Step 7: Question Deletion - Buyer deletes their own question
  const deletedQuestion =
    await api.functional.shoppingMall.buyer.sales.questions.erase(connection, {
      saleCode: sale.code,
      questionId: question.id,
    });
  typia.assert(deletedQuestion);

  // Step 8: Deletion Validation - Verify deletion was successful
  TestValidator.equals(
    "deleted question ID matches original question",
    deletedQuestion.id,
    question.id,
  );
  TestValidator.equals(
    "deleted question title matches original",
    deletedQuestion.title,
    question.title,
  );
  TestValidator.equals(
    "deleted question body matches original",
    deletedQuestion.body,
    question.body,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import type { IShoppingMallSaleVariantAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantAttribute";
import type { IShoppingMallSaleVariantValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantValue";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test creating multiple variant attribute values with different display orders
 * to validate proper sequencing in buyer selection interfaces.
 *
 * This test creates several variant values (e.g., 'Small', 'Medium', 'Large',
 * 'XL') for a Size attribute with explicit display_order values to ensure they
 * appear in the intended sequence. The test validates that lower display_order
 * numbers appear first, allowing sellers to create logical ordering such as
 * sizes from smallest to largest or colors in a specific brand sequence.
 *
 * Workflow:
 *
 * 1. Authenticate as seller to manage variant value ordering
 * 2. Create admin account and authenticate for category management
 * 3. Create category for product taxonomy
 * 4. Create product sale for variant configuration
 * 5. Create variant attribute (Size) to demonstrate ordered value creation
 * 6. Create multiple variant values with different display_order values (Small=0,
 *    Medium=1, Large=2, XL=3)
 * 7. Validate each value maintains its assigned display order
 * 8. Verify values can be retrieved in the correct sequence for presentation to
 *    buyers
 */
export async function test_api_variant_value_creation_multiple_values_ordering(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = typia.random<string & tags.MinLength<8>>();

  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.name(2),
      business_description: RandomGenerator.paragraph({ sentences: 5 }),
      store_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 2: Create admin account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 3: Create category for product taxonomy
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        display_order: 0,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 4: Switch back to seller and create product sale
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ILogin,
  });

  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        shopping_mall_category_id: category.id,
        title: RandomGenerator.name(3),
        description: RandomGenerator.content({ paragraphs: 3 }),
        condition: "new",
        return_policy_days: 30,
      } satisfies IShoppingMallSale.ICreate,
    },
  );
  typia.assert(sale);

  // Step 5: Create variant attribute (Size)
  const variantAttribute =
    await api.functional.shoppingMall.seller.sales.variantAttributes.create(
      connection,
      {
        saleCode: sale.code,
        body: {
          name: "Size",
          display_order: 0,
        } satisfies IShoppingMallSaleVariantAttribute.ICreate,
      },
    );
  typia.assert(variantAttribute);

  // Step 6: Create multiple variant values with different display_order values
  const sizeValues = [
    { value: "Small", display_order: 0 },
    { value: "Medium", display_order: 1 },
    { value: "Large", display_order: 2 },
    { value: "XL", display_order: 3 },
  ];

  const createdValues: IShoppingMallSaleVariantValue[] = [];

  for (const sizeData of sizeValues) {
    const variantValue =
      await api.functional.shoppingMall.seller.sales.variantAttributes.values.create(
        connection,
        {
          saleCode: sale.code,
          variantAttributeId: variantAttribute.id,
          body: {
            value: sizeData.value,
            display_order: sizeData.display_order,
          } satisfies IShoppingMallSaleVariantValue.ICreate,
        },
      );
    typia.assert(variantValue);
    createdValues.push(variantValue);
  }

  // Step 7: Validate each value maintains its assigned display order
  TestValidator.equals(
    "all variant values created successfully",
    createdValues.length,
    sizeValues.length,
  );

  for (let i = 0; i < createdValues.length; i++) {
    TestValidator.equals(
      `variant value '${sizeValues[i].value}' has correct display_order`,
      createdValues[i].display_order,
      sizeValues[i].display_order,
    );

    TestValidator.equals(
      `variant value '${sizeValues[i].value}' has correct value`,
      createdValues[i].value,
      sizeValues[i].value,
    );
  }

  // Step 8: Verify values are in correct sequence (ascending display_order)
  const sortedByDisplayOrder = [...createdValues].sort(
    (a, b) => a.display_order - b.display_order,
  );

  for (let i = 0; i < sortedByDisplayOrder.length; i++) {
    TestValidator.equals(
      `value at position ${i} matches expected order`,
      sortedByDisplayOrder[i].value,
      sizeValues[i].value,
    );

    TestValidator.predicate(
      `display_order is sequential at position ${i}`,
      sortedByDisplayOrder[i].display_order === i,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
