  const addressTypes = [
    "residential",
    "commercial",
    "residential",
    "residential",
  ] as const;
  const createdAddresses: IShoppingMallBuyerAddress[] = [];

  for (let i = 0; i < addressLabels.length; i++) {
    const address: IShoppingMallBuyerAddress =
      await api.functional.shoppingMall.buyer.buyers.me.addresses.create(
        connection,
