/**
 * Test admin account retrieval across different administrative privilege
 * levels.
 *
 * This test validates that the privilege level hierarchy (super_admin,
 * moderator, support) is correctly stored and retrieved through the admin
 * account retrieval endpoint.
 *
 * Test workflow:
 *
 * 1. Create an authenticating admin account (super_admin)
 * 2. Create three test admin accounts with different privilege levels
 * 3. Authenticate as the first admin
 * 4. Retrieve each test admin account via the retrieval endpoint
 * 5. Verify that admin_level field matches the assigned privilege level for each
 *    account
 * 6. Validate complete data consistency and no corruption of privilege information
 */
export async function test_api_admin_account_retrieval_different_privilege_levels(
  connection: api.IConnection,
) {
  // Step 1: Create authenticating admin account (super_admin)
  const authAdminEmail = typia.random<string & tags.Format<"email">>();
  const authAdmin = await api.functional.auth.admin.join(connection, {
    body: {
      email: authAdminEmail,
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin" as const,
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(authAdmin);

  // Step 2: Create test admin accounts with different privilege levels
  const privilegeLevels = ["super_admin", "moderator", "support"] as const;

  const testAdmins = await ArrayUtil.asyncMap(
    privilegeLevels,
    async (level) => {
      const adminEmail = typia.random<string & tags.Format<"email">>();
      const admin = await api.functional.auth.admin.join(connection, {
        body: {
          email: adminEmail,
          password: typia.random<string & tags.Format<"password">>(),
          full_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
          admin_level: level,
          email_verified: true,
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IShoppingMallAdmin.ICreate,
      });
      typia.assert(admin);
      return { level, admin };
    },
  );

  // Step 3: Authenticate as the first admin (already authenticated from join)
  // The join operation already sets the authorization token in connection.headers

  // Step 4 & 5: Retrieve each test admin and verify privilege levels
  await ArrayUtil.asyncForEach(testAdmins, async ({ level, admin }) => {
    const retrieved = await api.functional.shoppingMall.admin.admins.at(
      connection,
      {
        adminId: admin.id,
      },
    );
    typia.assert(retrieved);

    // Verify that the admin_level matches the expected privilege level
    TestValidator.equals(
      `admin_level should be ${level}`,
      retrieved.admin_level,
      level,
    );

    // Verify basic admin information consistency
    TestValidator.equals(
      "retrieved admin ID matches created admin",
      retrieved.id,
      admin.id,
    );
    TestValidator.equals(
      "retrieved admin email matches created admin",
      retrieved.email,
      admin.email,
    );
    TestValidator.equals(
      "retrieved admin full_name matches created admin",
      retrieved.full_name,
      admin.full_name,
    );
    TestValidator.equals(
      "retrieved admin phone_number matches created admin",
      retrieved.phone_number,
      admin.phone_number,
    );
    TestValidator.equals(
      "retrieved admin email_verified matches created admin",
      retrieved.email_verified,
      admin.email_verified,
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

/**
 * Test admin profile update workflow with complete validation.
 *
 * This test validates that an authenticated administrator can successfully
 * update their profile information (full_name, email, phone_number) and
 * verifies proper data persistence, immutable field protection, and audit trail
 * maintenance.
 *
 * Workflow:
 *
 * 1. Create and authenticate admin account
 * 2. Store original profile for comparison
 * 3. Update profile with new values
 * 4. Validate response reflects changes
 * 5. Verify immutable fields unchanged
 * 6. Confirm audit timestamp updated
 */
export async function test_api_admin_account_update_profile_information(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate admin account
  const originalEmail = typia.random<string & tags.Format<"email">>();
  const originalFullName = RandomGenerator.name();
  const originalPhone = RandomGenerator.mobile();

  const adminCreateBody = {
    email: originalEmail,
    password: typia.random<string & tags.Format<"password">>(),
    full_name: originalFullName,
    phone_number: originalPhone,
    admin_level: "moderator" as const,
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const authenticatedAdmin = await api.functional.auth.admin.join(connection, {
    body: adminCreateBody,
  });
  typia.assert(authenticatedAdmin);

  // Step 2: Store original values for verification
  const originalId = authenticatedAdmin.id;
  const originalCreatedAt = authenticatedAdmin.created_at;

  // Step 3: Prepare update data with new values
  const newEmail = typia.random<string & tags.Format<"email">>();
  const newFullName = RandomGenerator.name();
  const newPhone = RandomGenerator.mobile();

  const updateBody = {
    email: newEmail,
    full_name: newFullName,
    phone_number: newPhone,
  } satisfies IShoppingMallAdmin.IUpdate;

  // Step 4: Execute profile update
  const updatedAdmin = await api.functional.shoppingMall.admin.admins.update(
    connection,
    {
      adminId: authenticatedAdmin.id,
      body: updateBody,
    },
  );
  typia.assert(updatedAdmin);

  // Step 5: Validate updated fields reflect new values
  TestValidator.equals("updated email matches", updatedAdmin.email, newEmail);
  TestValidator.equals(
    "updated full_name matches",
    updatedAdmin.full_name,
    newFullName,
  );
  TestValidator.equals(
    "updated phone_number matches",
    updatedAdmin.phone_number,
    newPhone,
  );

  // Step 6: Verify immutable fields remain unchanged
  TestValidator.equals("id unchanged", updatedAdmin.id, originalId);
  TestValidator.equals(
    "created_at unchanged",
    updatedAdmin.created_at,
    originalCreatedAt,
  );

  // Step 7: Verify updated_at timestamp reflects modification
  TestValidator.predicate(
    "updated_at is after created_at",
    new Date(updatedAdmin.updated_at).getTime() >=
      new Date(originalCreatedAt).getTime(),
  );

  // Step 8: Verify admin_level persisted correctly
  TestValidator.equals(
    "admin_level preserved",
    updatedAdmin.admin_level,
    "moderator",
  );

  // Step 9: Verify email_verified status maintained
  TestValidator.equals(
    "email_verified maintained",
    updatedAdmin.email_verified,
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";

/**
 * Test administrative privilege level changes to validate that admin_level can
 * be successfully updated and that such changes are properly tracked for
 * security audit purposes.
 *
 * This test validates:
 *
 * 1. Admin authentication with update permissions
 * 2. Target admin account creation with initial privilege level
 * 3. Privilege escalation from support to moderator
 * 4. Response validation showing updated privilege level
 * 5. Persistence verification by retrieving the updated admin account
 * 6. Audit trail validation through updated_at timestamp changes
 * 7. Multiple privilege level transitions (moderator to super_admin)
 * 8. Data consistency verification ensuring only admin_level changes
 */
export async function test_api_admin_account_privilege_level_modification(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a super_admin who can modify privilege levels
  const superAdminEmail = typia.random<string & tags.Format<"email">>();
  const superAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: superAdminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(superAdmin);

  // Step 2: Create target admin account with initial privilege level "support"
  const targetAdminEmail = typia.random<string & tags.Format<"email">>();
  const targetAdminPassword = typia.random<string & tags.Format<"password">>();
  const targetAdminFullName = RandomGenerator.name();
  const targetAdminPhone = RandomGenerator.mobile();

  const targetAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: targetAdminEmail,
        password: targetAdminPassword,
        full_name: targetAdminFullName,
        phone_number: targetAdminPhone,
        admin_level: "support",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(targetAdmin);

  // Verify initial privilege level is "support"
  TestValidator.equals(
    "initial privilege level",
    targetAdmin.admin_level,
    "support",
  );

  // Store original created_at and updated_at for comparison
  const originalCreatedAt = targetAdmin.created_at;
  const originalUpdatedAt = targetAdmin.updated_at;

  // Step 3: First privilege update - change from "support" to "moderator"
  const firstUpdate: IShoppingMallAdmin =
    await api.functional.shoppingMall.admin.admins.update(connection, {
      adminId: targetAdmin.id,
      body: {
        admin_level: "moderator",
      } satisfies IShoppingMallAdmin.IUpdate,
    });
  typia.assert(firstUpdate);

  // Step 4: Validate first update response
  TestValidator.equals(
    "privilege updated to moderator",
    firstUpdate.admin_level,
    "moderator",
  );
  TestValidator.equals(
    "email unchanged after first update",
    firstUpdate.email,
    targetAdminEmail,
  );
  TestValidator.equals(
    "full_name unchanged after first update",
    firstUpdate.full_name,
    targetAdminFullName,
  );
  TestValidator.equals(
    "phone_number unchanged after first update",
    firstUpdate.phone_number,
    targetAdminPhone,
  );
  TestValidator.equals(
    "created_at unchanged after first update",
    firstUpdate.created_at,
    originalCreatedAt,
  );

  // Verify updated_at timestamp changed (for audit trail)
  TestValidator.predicate(
    "updated_at changed after first privilege modification",
    new Date(firstUpdate.updated_at).getTime() >=
      new Date(originalUpdatedAt).getTime(),
  );

  // Step 5: Second privilege update - change from "moderator" to "super_admin"
  const firstUpdateTimestamp = firstUpdate.updated_at;

  const secondUpdate: IShoppingMallAdmin =
    await api.functional.shoppingMall.admin.admins.update(connection, {
      adminId: targetAdmin.id,
      body: {
        admin_level: "super_admin",
      } satisfies IShoppingMallAdmin.IUpdate,
    });
  typia.assert(secondUpdate);

  // Step 6: Validate second update response
  TestValidator.equals(
    "privilege updated to super_admin",
    secondUpdate.admin_level,
    "super_admin",
  );
  TestValidator.equals(
    "email unchanged after second update",
    secondUpdate.email,
    targetAdminEmail,
  );
  TestValidator.equals(
    "full_name unchanged after second update",
    secondUpdate.full_name,
    targetAdminFullName,
  );
  TestValidator.equals(
    "phone_number unchanged after second update",
    secondUpdate.phone_number,
    targetAdminPhone,
  );
  TestValidator.equals(
    "created_at unchanged after second update",
    secondUpdate.created_at,
    originalCreatedAt,
  );

  // Verify updated_at timestamp changed again (for second modification audit trail)
  TestValidator.predicate(
    "updated_at changed after second privilege modification",
    new Date(secondUpdate.updated_at).getTime() >=
      new Date(firstUpdateTimestamp).getTime(),
  );

  // Step 7: Verify all three privilege levels have been successfully tested
  // This test has validated: support → moderator → super_admin transitions
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
