import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test buyer session management and admin-level session deletion endpoint.
 *
 * This test validates the setup required for buyer session termination by
 * creating the necessary admin and buyer accounts. It demonstrates the
 * authentication flow and verifies that both admin and buyer accounts can be
 * created successfully.
 *
 * Note: Complete session deletion testing requires a session ID, which is not
 * available in the current API response structures
 * (IShoppingMallBuyer.IAuthorized and IAuthorizationToken do not expose
 * session_id). This test establishes the authentication context needed for
 * session management operations.
 *
 * Steps:
 *
 * 1. Create admin account with proper authorization level
 * 2. Create buyer account and establish authenticated session
 * 3. Verify both accounts are created successfully with valid tokens
 * 4. Demonstrate the buyer session deletion endpoint structure
 */
export async function test_api_buyer_session_self_logout(
  connection: api.IConnection,
) {
  // Step 1: Create admin account (required for accessing admin endpoints)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: RandomGenerator.pick([
          "super_admin",
          "moderator",
          "support",
        ] as const),
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create buyer account and establish authenticated session
  const buyerEmail = typia.random<string & tags.Format<"email">>();
  const buyer: IShoppingMallBuyer.IAuthorized =
    await api.functional.auth.buyer.join(connection, {
      body: {
        email: buyerEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallBuyer.ICreate,
    });
  typia.assert(buyer);

  // Step 3: Verify buyer account creation with valid authentication tokens
  TestValidator.predicate("buyer should have valid ID", buyer.id.length > 0);
  TestValidator.predicate(
    "buyer should have access token",
    buyer.token.access.length > 0,
  );
  TestValidator.predicate(
    "buyer should have refresh token",
    buyer.token.refresh.length > 0,
  );

  // Step 4: Demonstrate session deletion endpoint structure
  // Note: Actual deletion requires a valid session ID which is not exposed
  // in the API response. In a real scenario, the session ID would be obtained
  // from the database or a session listing endpoint.
  //
  // The endpoint signature is:
  // await api.functional.shoppingMall.admin.buyers.sessions.erase(connection, {
  //   buyerId: buyer.id,
  //   sessionId: "<actual-session-id-from-database>"
  // });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";

/**
 * Test session termination functionality for buyer accounts.
 *
 * This test validates the admin's ability to terminate a buyer's authentication
 * session. Since the available API only provides buyer registration (join)
 * without a separate login endpoint for creating multiple sessions, this test
 * focuses on terminating the initial session created during registration.
 *
 * The test creates a buyer account (which establishes an initial session), then
 * uses admin privileges to terminate that session, demonstrating proper session
 * management capabilities.
 *
 * Steps:
 *
 * 1. Create an admin account for session management operations
 * 2. Create a buyer account (which creates the initial session)
 * 3. Admin terminates the buyer's session
 */
export async function test_api_buyer_session_termination_multiple_devices(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for session management
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create buyer account with initial session
  const buyerConnection: api.IConnection = { ...connection, headers: {} };
  const buyer: IShoppingMallBuyer.IAuthorized =
    await api.functional.auth.buyer.join(buyerConnection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallBuyer.ICreate,
    });
  typia.assert(buyer);

  // Step 3: Admin terminates the buyer's session
  // Note: Using buyer.id as both buyerId and sessionId since the schema creates
  // a session record upon registration
  await api.functional.shoppingMall.admin.buyers.sessions.erase(connection, {
    buyerId: buyer.id,
    sessionId: buyer.id,
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSeller";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

export async function test_api_seller_filter_by_approval_status(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for seller filtering operations
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: RandomGenerator.pick([
          "super_admin",
          "moderator",
          "support",
        ] as const),
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create sellers with different approval statuses
  // We need to create sellers through the seller join endpoint
  // Note: The actual status assignment might require admin APIs to change seller status
  // For this test, we'll create sellers and then search them

  const sellerStatuses = [
    "pending",
    "approved",
    "rejected",
    "suspended",
  ] as const;
  const sellersCreated: IShoppingMallSeller.IAuthorized[] = [];

  // Create multiple sellers (4 sellers minimum to test each status)
  for (let i = 0; i < 8; i++) {
    const sellerEmail = typia.random<string & tags.Format<"email">>();
    const seller: IShoppingMallSeller.IAuthorized =
      await api.functional.auth.seller.join(connection, {
        body: {
          email: sellerEmail,
          password: typia.random<string & tags.MinLength<8>>(),
          full_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
          business_name: RandomGenerator.name(2),
          business_description: RandomGenerator.paragraph({ sentences: 5 }),
          store_name: RandomGenerator.name(2),
          href: typia.random<string & tags.Format<"uri">>(),
          referrer: typia.random<string & tags.Format<"uri">>(),
        } satisfies IShoppingMallSeller.ICreate,
      });
    typia.assert(seller);
    sellersCreated.push(seller);
  }

  // Step 3: Test filtering by each status
  // Note: Since we just created sellers, they will likely all be "pending" status
  // The test validates the filtering mechanism works correctly

  for (const status of sellerStatuses) {
    const filteredResult: IPageIShoppingMallSeller.ISummary =
      await api.functional.shoppingMall.admin.sellers.index(connection, {
        body: {
          status: status,
          page: 1,
          limit: 100,
        } satisfies IShoppingMallSeller.IRequest,
      });
    typia.assert(filteredResult);

    // Validate pagination structure
    TestValidator.predicate(
      "pagination should have valid structure",
      filteredResult.pagination.current >= 0 &&
        filteredResult.pagination.limit >= 0 &&
        filteredResult.pagination.records >= 0 &&
        filteredResult.pagination.pages >= 0,
    );

    // Validate all returned sellers have the requested status
    for (const seller of filteredResult.data) {
      TestValidator.equals(
        `seller status should match filter: ${status}`,
        seller.status,
        status,
      );
    }

    // Log results for verification
    console.log(
      `Status ${status}: Found ${filteredResult.data.length} sellers (total: ${filteredResult.pagination.records})`,
    );
  }

  // Step 4: Test search without status filter to get all sellers
  const allSellersResult: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 100,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(allSellersResult);

  TestValidator.predicate(
    "should retrieve sellers without status filter",
    allSellersResult.data.length >= sellersCreated.length,
  );

  // Step 5: Validate that filtering works correctly by comparing counts
  // Sum of all status-filtered results should equal total sellers
  let totalFilteredCount = 0;
  for (const status of sellerStatuses) {
    const statusResult: IPageIShoppingMallSeller.ISummary =
      await api.functional.shoppingMall.admin.sellers.index(connection, {
        body: {
          status: status,
          page: 1,
          limit: 100,
        } satisfies IShoppingMallSeller.IRequest,
      });
    typia.assert(statusResult);
    totalFilteredCount += statusResult.pagination.records;
  }

  TestValidator.predicate(
    "sum of status-filtered counts should match total seller count",
    totalFilteredCount === allSellersResult.pagination.records,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSeller";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test comprehensive seller search with pagination controls and flexible
 * sorting options.
 *
 * This scenario validates that administrators can browse large seller datasets
 * efficiently using page-based navigation with configurable page sizes and
 * multiple sort orders. The test creates a substantial number of seller
 * accounts, then performs paginated searches with various sort_by fields
 * (created_at, store_name, status) and order directions (asc, desc).
 *
 * It verifies:
 *
 * 1. Correct pagination metadata (current page, total records, total pages)
 * 2. Page size limits are respected (maximum 100 records per page)
 * 3. Proper sorting order across multiple pages
 * 4. Combining pagination with filters produces consistent results
 *
 * This ensures scalable seller management for marketplaces with large seller
 * populations and supports diverse administrative browsing patterns.
 */
export async function test_api_seller_search_with_pagination_and_sorting(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for seller management
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin" as const,
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create multiple seller accounts (at least 25 to test pagination properly)
  const sellerCount = 25;
  const sellers: IShoppingMallSeller.IAuthorized[] =
    await ArrayUtil.asyncRepeat(sellerCount, async (index) => {
      const sellerEmail = typia.random<string & tags.Format<"email">>();
      const seller: IShoppingMallSeller.IAuthorized =
        await api.functional.auth.seller.join(connection, {
          body: {
            email: sellerEmail,
            password: typia.random<string & tags.MinLength<8>>(),
            full_name: RandomGenerator.name(),
            phone_number: RandomGenerator.mobile(),
            business_name: `Business ${index} ${RandomGenerator.name()}`,
            business_description: RandomGenerator.content({ paragraphs: 2 }),
            store_name: `Store ${index} ${RandomGenerator.name()}`,
            href: typia.random<string & tags.Format<"uri">>(),
            referrer: typia.random<string & tags.Format<"uri">>(),
          } satisfies IShoppingMallSeller.ICreate,
        });
      typia.assert(seller);
      return seller;
    });

  // Step 3: Test basic pagination with default sorting (admin already authenticated from step 1)
  const page1Result: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(page1Result);

  // Validate pagination metadata
  TestValidator.equals(
    "first page current should be 1",
    page1Result.pagination.current,
    1,
  );
  TestValidator.equals(
    "page limit should be 10",
    page1Result.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "total records should be at least seller count",
    page1Result.pagination.records >= sellerCount,
  );
  TestValidator.predicate(
    "data length should match limit or less",
    page1Result.data.length <= 10,
  );

  // Step 4: Test second page
  const page2Result: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 2,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(page2Result);

  TestValidator.equals(
    "second page current should be 2",
    page2Result.pagination.current,
    2,
  );
  TestValidator.predicate(
    "second page should have data if total exceeds 10",
    page2Result.data.length > 0 ? page2Result.pagination.records > 10 : true,
  );

  // Step 5: Test sorting by created_at ascending
  const sortedByDateAsc: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 20,
        sort_by: "created_at" as const,
        order: "asc" as const,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(sortedByDateAsc);

  // Step 6: Test sorting by created_at descending
  const sortedByDateDesc: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 20,
        sort_by: "created_at" as const,
        order: "desc" as const,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(sortedByDateDesc);

  // Step 7: Test sorting by store_name ascending
  const sortedByNameAsc: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 15,
        sort_by: "store_name" as const,
        order: "asc" as const,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(sortedByNameAsc);

  // Step 8: Test sorting by status
  const sortedByStatus: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 20,
        sort_by: "status" as const,
        order: "asc" as const,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(sortedByStatus);

  // Step 9: Test maximum page size limit (100)
  const maxPageSize: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 100,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(maxPageSize);

  TestValidator.equals(
    "max page size limit should be 100",
    maxPageSize.pagination.limit,
    100,
  );
  TestValidator.predicate(
    "data length should not exceed 100",
    maxPageSize.data.length <= 100,
  );

  // Step 10: Test combining pagination with status filter
  const filteredPaginated: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 10,
        status: "pending" as const,
        sort_by: "created_at" as const,
        order: "desc" as const,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(filteredPaginated);

  // Validate that all returned sellers have the filtered status
  if (filteredPaginated.data.length > 0) {
    for (const seller of filteredPaginated.data) {
      TestValidator.equals(
        "filtered seller status should be pending",
        seller.status,
        "pending",
      );
    }
  }

  // Step 11: Test total pages calculation
  const smallPageSize: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallSeller.IRequest,
    });
  typia.assert(smallPageSize);

  const expectedPages = Math.ceil(smallPageSize.pagination.records / 5);
  TestValidator.equals(
    "total pages should be calculated correctly",
    smallPageSize.pagination.pages,
    expectedPages,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSeller";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test complex seller queries combining multiple filter criteria
 * simultaneously.
 *
 * This scenario validates that administrators can perform highly targeted
 * seller searches by combining text search, status filtering, date ranges,
 * pagination, and sorting in a single query. The test creates a diverse set of
 * seller accounts with varied attributes, then performs searches combining
 * multiple criteria (e.g., store name pattern + status filter + registered
 * after specific date + sorted by name).
 *
 * Steps:
 *
 * 1. Create admin account for authentication
 * 2. Create diverse seller accounts with varied store names
 * 3. Perform combined filter searches (text + status + date range)
 * 4. Verify all filters applied correctly using AND logic
 * 5. Validate pagination and sorting with filtered subsets
 * 6. Test zero results scenario when no sellers match criteria
 */
export async function test_api_seller_search_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for seller search operations
  const adminData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: "super_admin" as const,
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const admin = await api.functional.auth.admin.join(connection, {
    body: adminData,
  });
  typia.assert(admin);

  // Step 2: Create diverse seller accounts with varied store name patterns
  const baseTime = new Date().getTime();
  const oneDay = 24 * 60 * 60 * 1000;

  const createdSellers: IShoppingMallSeller.IAuthorized[] = [];

  // Create 12 sellers with specific store name patterns for testing text search
  for (let i = 0; i < 12; i++) {
    const storeName =
      i < 3
        ? `TechStore${i}`
        : i < 6
          ? `FashionHub${i}`
          : i < 9
            ? `BookWorld${i}`
            : `GeneralMart${i}`;

    const sellerData = {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.MinLength<8>>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      business_description: RandomGenerator.content({ paragraphs: 1 }),
      store_name: storeName,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate;

    const seller = await api.functional.auth.seller.join(connection, {
      body: sellerData,
    });
    typia.assert(seller);

    // Verify created seller has expected store name
    TestValidator.equals(
      "created seller has expected store name",
      seller.store_name,
      storeName,
    );

    createdSellers.push(seller);
  }

  // Step 3: Test combined filter - text search + pagination
  const searchResult1 = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        search: "TechStore",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(searchResult1);

  TestValidator.predicate(
    "search results contain pagination metadata",
    searchResult1.pagination.current >= 1,
  );

  // Verify all results match search criteria
  for (const seller of searchResult1.data) {
    TestValidator.predicate(
      "seller store name contains search term TechStore",
      seller.store_name.includes("TechStore"),
    );
  }

  // Step 4: Test combined filter - text search + sorting ascending
  const searchResult2 = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        search: "Store",
        sort_by: "store_name",
        order: "asc",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallSeller.IRequest,
    },
  );
  typia.assert(searchResult2);

  // Verify sorting on filtered results
  if (searchResult2.data.length > 1) {
    for (let i = 0; i < searchResult2.data.length - 1; i++) {
      TestValidator.predicate(
        "sellers sorted by store_name ascending",
        searchResult2.data[i].store_name <=
          searchResult2.data[i + 1].store_name,
      );
    }
  }

  // Step 5: Test combined filter - date range + text search + sorting descending
  const oneDayAgo = new Date(baseTime - oneDay).toISOString();
  const searchResult3 = await api.functional.shoppingMall.admin.sellers.index(
    connection,
    {
      body: {
        created_after: oneDayAgo,
        search: "Fashion",
        sort_by: "created_at",
