  // Step 8: Test pagination with combined filters across multiple pages
  const searchResult6Page1 =
    await api.functional.shoppingMall.admin.sellers.index(connection, {
      body: {
        page: 1,
        limit: 3,
        sort_by: "store_name",
        order: "asc",
      } satisfies IShoppingMallSeller.IRequest,
