    updatedSku.sku_code,
    createdSku.sku_code,
  );
  TestValidator.equals(
    "variant_combination should remain unchanged",
    updatedSku.variant_combination,
    createdSku.variant_combination,
  );
  TestValidator.equals(
    "base_price should remain unchanged",
    updatedSku.base_price,
    createdSku.base_price,
  );
