        "total_amount descending order validation",
        current >= next,
      );
    }
  }

  // Step 6: Test sorting by status in ascending order
  const sortByStatusAsc = {
    page: 1,
    limit: 20,
    sort_by: "status" as const,
    sort_order: "asc" as const,
  } satisfies IShoppingMallOrder.IRequest;

  const resultStatusAsc: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: sortByStatusAsc,
    });
  typia.assert(resultStatusAsc);

  // Validate ascending order by status
  if (resultStatusAsc.data.length > 1) {
    for (let i = 0; i < resultStatusAsc.data.length - 1; i++) {
      const current = resultStatusAsc.data[i].status;
      const next = resultStatusAsc.data[i + 1].status;
      TestValidator.predicate(
        "status ascending order validation",
        current <= next,
      );
    }
  }

  // Step 7: Test sorting by status in descending order
  const sortByStatusDesc = {
    page: 1,
    limit: 20,
    sort_by: "status" as const,
    sort_order: "desc" as const,
  } satisfies IShoppingMallOrder.IRequest;

  const resultStatusDesc: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: sortByStatusDesc,
    });
  typia.assert(resultStatusDesc);

  // Validate descending order by status
  if (resultStatusDesc.data.length > 1) {
    for (let i = 0; i < resultStatusDesc.data.length - 1; i++) {
      const current = resultStatusDesc.data[i].status;
      const next = resultStatusDesc.data[i + 1].status;
      TestValidator.predicate(
        "status descending order validation",
        current >= next,
      );
    }
  }

  // Validate pagination metadata
  TestValidator.predicate(
    "pagination metadata exists",
    resultCreatedAtAsc.pagination !== null &&
      resultCreatedAtAsc.pagination !== undefined,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrder";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test that sellers can perform text searches to quickly find specific orders.
 *
 * This test validates the search parameter functionality for sellers looking up
 * orders by order number or buyer information. It verifies that:
 *
 * 1. Text search works across relevant fields (order_number, buyer info)
 * 2. Search supports partial matching
 * 3. Search is case-insensitive
 * 4. Results include only orders containing the seller's items that match the
 *    search term
 *
 * Test Process:
 *
 * 1. Create and authenticate a new seller account
 * 2. Retrieve initial order list to get searchable data
 * 3. Perform text searches using order numbers
 * 4. Validate search results contain the search term
 * 5. Test case-insensitive matching
 * 6. Test partial text matching
 */
export async function test_api_seller_orders_search_with_text_search(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate a new seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile("+82"),
      business_name: RandomGenerator.name(2),
      business_description: RandomGenerator.paragraph({ sentences: 5 }),
      store_name: RandomGenerator.name(1),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 2: Retrieve initial order list to get available orders
  const allOrders = await api.functional.shoppingMall.seller.orders.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(allOrders);

  // If no orders exist, we can only test that empty search works
  if (allOrders.data.length === 0) {
    const emptySearchResult =
      await api.functional.shoppingMall.seller.orders.index(connection, {
        body: {
          search: "nonexistent",
        } satisfies IShoppingMallOrder.IRequest,
      });
    typia.assert(emptySearchResult);
    TestValidator.equals(
      "empty search returns no results",
      emptySearchResult.data.length,
      0,
    );
    return;
  }

  // Step 3: Test search with full order number
  const sampleOrder = allOrders.data[0];
  const fullOrderNumber = sampleOrder.order_number;

  const fullSearchResult =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        search: fullOrderNumber,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(fullSearchResult);

  TestValidator.predicate(
    "full order number search returns at least one result",
    fullSearchResult.data.length > 0,
  );

  TestValidator.predicate(
    "search result contains the searched order number",
    fullSearchResult.data.some(
      (order) => order.order_number === fullOrderNumber,
    ),
  );

  // Step 4: Test partial matching - use substring of order number
  if (fullOrderNumber.length > 5) {
    const partialSearch = fullOrderNumber.substring(0, 5);

    const partialSearchResult =
      await api.functional.shoppingMall.seller.orders.index(connection, {
        body: {
          search: partialSearch,
        } satisfies IShoppingMallOrder.IRequest,
      });
    typia.assert(partialSearchResult);

    TestValidator.predicate(
      "partial text search returns results",
      partialSearchResult.data.length >= 0,
    );

    // If results exist, verify they contain the search term
    if (partialSearchResult.data.length > 0) {
      TestValidator.predicate(
        "partial search results contain the search term",
        partialSearchResult.data.every((order) =>
          order.order_number.includes(partialSearch),
        ),
      );
    }
  }

  // Step 5: Test case-insensitive search
  const lowercaseSearch = fullOrderNumber.toLowerCase();
  const uppercaseSearch = fullOrderNumber.toUpperCase();

  const lowercaseResult = await api.functional.shoppingMall.seller.orders.index(
    connection,
    {
      body: {
        search: lowercaseSearch,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(lowercaseResult);

  const uppercaseResult = await api.functional.shoppingMall.seller.orders.index(
    connection,
    {
      body: {
        search: uppercaseSearch,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(uppercaseResult);

  TestValidator.predicate(
    "case-insensitive search - lowercase returns results",
    lowercaseResult.data.length > 0,
  );

  TestValidator.predicate(
    "case-insensitive search - uppercase returns results",
    uppercaseResult.data.length > 0,
  );

  // Step 6: Test that search with non-existent term returns no results
  const nonExistentSearch =
    "NONEXISTENT_ORDER_" + RandomGenerator.alphaNumeric(16);

  const noResultSearch = await api.functional.shoppingMall.seller.orders.index(
    connection,
    {
      body: {
        search: nonExistentSearch,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(noResultSearch);

  TestValidator.equals(
    "search with non-existent term returns no results",
    noResultSearch.data.length,
    0,
  );

  // Step 7: Test search combined with pagination
  const paginatedSearch = await api.functional.shoppingMall.seller.orders.index(
    connection,
    {
      body: {
        search: fullOrderNumber,
        page: 1,
        limit: 5,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(paginatedSearch);

  TestValidator.predicate(
    "search with pagination returns valid results",
    paginatedSearch.data.length >= 0,
  );

  TestValidator.predicate(
    "pagination limit is respected in search results",
    paginatedSearch.data.length <= 5,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrder";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test that sellers can combine multiple filters in complex search scenarios.
 *
 * Validates real-world seller workflows such as finding recent high-value
 * orders in processing status. Tests combinations of status, date range, amount
 * range, and sorting parameters to ensure all filters apply correctly together
 * and results satisfy all criteria while containing only the seller's items.
 *
 * The test follows this workflow:
 *
 * 1. Create and authenticate a seller account
 * 2. Execute baseline search queries to verify basic functionality
 * 3. Test complex multi-filter combinations:
 *
 *    - Status filtering (specific order statuses)
 *    - Date range filtering (orders within time periods)
 *    - Amount range filtering (orders within price ranges)
 *    - Combined filters (status + date + amount + sorting)
 * 4. Verify all results match ALL applied filter criteria
 * 5. Validate pagination and sorting work correctly with filters
 */
export async function test_api_seller_orders_search_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile("+1"),
        business_name: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 7,
        }),
        business_description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 10,
        }),
        store_name: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 5,
        }),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // Step 2: Test baseline search - simple query without filters
  const baselineSearch: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 20,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(baselineSearch);

  // Validate pagination structure
  TestValidator.predicate(
    "baseline search returns valid pagination",
    baselineSearch.pagination.current === 1 &&
      baselineSearch.pagination.limit === 20,
  );

  // Step 3: Test status filter
  const processingStatusSearch: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 10,
        status: "processing",
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(processingStatusSearch);

  // Validate status filter works correctly
  if (processingStatusSearch.data.length > 0) {
    for (const order of processingStatusSearch.data) {
      TestValidator.equals(
        "status filter returns only processing orders",
        order.status,
        "processing",
      );
    }
  }

  // Step 4: Test date range filter
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  const dateRangeSearch: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 10,
        from_date: thirtyDaysAgo.toISOString(),
        to_date: now.toISOString(),
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(dateRangeSearch);

  // Validate date range filter
  if (dateRangeSearch.data.length > 0) {
    for (const order of dateRangeSearch.data) {
      const orderDate = new Date(order.created_at);
      TestValidator.predicate(
        "order is within date range",
        orderDate >= thirtyDaysAgo && orderDate <= now,
      );
    }
  }

  // Step 5: Test amount range filter
  const amountRangeSearch: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 10,
        min_amount: 100,
        max_amount: 1000,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(amountRangeSearch);

  // Validate amount range filter
  if (amountRangeSearch.data.length > 0) {
    for (const order of amountRangeSearch.data) {
      TestValidator.predicate(
        "order total is within amount range",
        order.total_amount >= 100 && order.total_amount <= 1000,
      );
    }
  }

  // Step 6: Test combined filters - status + date range + amount range
  const combinedFiltersSearch: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 15,
        status: "payment_confirmed",
        from_date: thirtyDaysAgo.toISOString(),
        to_date: now.toISOString(),
        min_amount: 50,
        max_amount: 5000,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(combinedFiltersSearch);

  // Validate combined filters work together
  if (combinedFiltersSearch.data.length > 0) {
    for (const order of combinedFiltersSearch.data) {
      TestValidator.equals(
        "combined filter status matches",
        order.status,
        "payment_confirmed",
      );

      const orderDate = new Date(order.created_at);
      TestValidator.predicate(
        "combined filter date range matches",
        orderDate >= thirtyDaysAgo && orderDate <= now,
      );

      TestValidator.predicate(
        "combined filter amount range matches",
        order.total_amount >= 50 && order.total_amount <= 5000,
      );
    }
  }

  // Step 7: Test sorting with filters - sort by total_amount descending
  const sortedByAmountDesc: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 10,
        status: "processing",
        sort_by: "total_amount",
        sort_order: "desc",
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(sortedByAmountDesc);

  // Validate sorting order
  if (sortedByAmountDesc.data.length > 1) {
    for (let i = 0; i < sortedByAmountDesc.data.length - 1; i++) {
      TestValidator.predicate(
        "orders sorted by amount descending",
        sortedByAmountDesc.data[i].total_amount >=
          sortedByAmountDesc.data[i + 1].total_amount,
      );
    }
  }

  // Step 8: Test sorting by created_at ascending with date filter
  const sortedByDateAsc: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 10,
        from_date: thirtyDaysAgo.toISOString(),
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(sortedByDateAsc);

  // Validate ascending date sort
  if (sortedByDateAsc.data.length > 1) {
    for (let i = 0; i < sortedByDateAsc.data.length - 1; i++) {
      const date1 = new Date(sortedByDateAsc.data[i].created_at);
      const date2 = new Date(sortedByDateAsc.data[i + 1].created_at);
      TestValidator.predicate(
        "orders sorted by date ascending",
        date1 <= date2,
      );
    }
  }

  // Step 9: Test complex realistic scenario - find recent high-value processing orders
  const realisticScenario: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 20,
        status: "processing",
        from_date: new Date(
          now.getTime() - 7 * 24 * 60 * 60 * 1000,
        ).toISOString(),
        to_date: now.toISOString(),
        min_amount: 500,
        sort_by: "total_amount",
        sort_order: "desc",
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(realisticScenario);

  // Step 10: Test pagination with filters - page 2
  const secondPage: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 2,
        limit: 10,
        status: "shipped",
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(secondPage);

  TestValidator.predicate(
    "second page pagination is correct",
    secondPage.pagination.current === 2 && secondPage.pagination.limit === 10,
  );

  // Step 11: Test search parameter combined with other filters
  const searchWithFilters: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.seller.orders.index(connection, {
      body: {
        page: 1,
        limit: 10,
        search: RandomGenerator.alphaNumeric(5),
        status: "delivered",
        min_amount: 100,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(searchWithFilters);
}

