import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdminSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test filtering admin sessions by IP address for security investigation
 * workflows.
 *
 * This test validates the IP address filtering capability essential for
 * security monitoring and incident response. Administrators need to quickly
 * identify all sessions originating from specific IP addresses to detect
 * suspicious access patterns or unauthorized login attempts.
 *
 * Test workflow:
 *
 * 1. Create an admin account (establishes first session with IP tracking)
 * 2. Capture the IP address used during account creation
 * 3. Retrieve sessions filtered by that specific IP address
 * 4. Validate that all returned sessions match the specified IP filter
 * 5. Verify pagination structure and session data integrity
 */
export async function test_api_admin_session_filtering_by_ip_address(
  connection: api.IConnection,
) {
  // Step 1: Create admin account with session tracking
  const testIpAddress = "192.168.1.100";
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePass123!";

  const createBody = {
    email: adminEmail,
    password: adminPassword,
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: RandomGenerator.pick([
      "super_admin",
      "moderator",
      "support",
    ] as const),
    email_verified: true,
    ip: testIpAddress,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const createdAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: createBody });
  typia.assert(createdAdmin);

  // Step 2: Retrieve sessions filtered by the IP address
  const sessionRequest = {
    ip: testIpAddress,
    page: 1,
    limit: 10,
  } satisfies IShoppingMallAdminSession.IRequest;

  const sessionResult: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: createdAdmin.id,
      body: sessionRequest,
    });
  typia.assert(sessionResult);

  // Step 3: Validate pagination structure
  TestValidator.predicate(
    "pagination should have valid structure",
    sessionResult.pagination.current >= 1,
  );
  TestValidator.predicate(
    "total records should be at least 1",
    sessionResult.pagination.records >= 1,
  );

  // Step 4: Validate that all returned sessions match the IP filter
  TestValidator.predicate(
    "should have at least one session",
    sessionResult.data.length > 0,
  );

  for (const session of sessionResult.data) {
    TestValidator.equals(
      "session IP should match filter",
      session.ip,
      testIpAddress,
    );
    TestValidator.equals(
      "session should belong to the created admin",
      session.admin.id,
      createdAdmin.id,
    );
  }

  // Step 5: Verify session data integrity
  const firstSession = sessionResult.data[0];
  typia.assert(firstSession);
  TestValidator.predicate(
    "session should have valid created_at timestamp",
    firstSession.created_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdminSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test sorting admin sessions by creation timestamp in ascending and descending
 * order.
 *
 * This test validates that administrators can retrieve their session history
 * sorted by creation timestamp in both ascending (oldest first) and descending
 * (newest first) order. This is essential for security monitoring and audit
 * analysis workflows.
 *
 * Note: Due to API endpoint limitations (no login endpoint available), this
 * test works with existing sessions in the system rather than creating multiple
 * new sessions.
 *
 * Test workflow:
 *
 * 1. Create an admin account through authentication join (creates first session)
 * 2. Retrieve sessions sorted by created_at in descending order (newest first)
 * 3. Validate the descending sort order on returned sessions
 * 4. Retrieve sessions sorted by created_at in ascending order (oldest first)
 * 5. Validate the ascending sort order on returned sessions
 * 6. Verify both queries return consistent results
 */
export async function test_api_admin_session_sorting_and_ordering(
  connection: api.IConnection,
) {
  // Step 1: Create admin account (this creates the initial session)
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "SecurePassword123!";

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "moderator",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Retrieve sessions sorted by created_at descending (newest first)
  const descendingResult: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        sort_by: "created_at",
        sort_order: "desc",
        page: 1,
        limit: 20,
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(descendingResult);

  // Step 3: Validate descending order (newest first)
  TestValidator.predicate(
    "descending sort should return at least one session",
    descendingResult.data.length >= 1,
  );

  // Validate sort order if multiple sessions exist
  if (descendingResult.data.length > 1) {
    for (let i = 0; i < descendingResult.data.length - 1; i++) {
      const current = new Date(descendingResult.data[i].created_at);
      const next = new Date(descendingResult.data[i + 1].created_at);

      TestValidator.predicate(
        `descending order: session ${i} created_at should be >= session ${i + 1} created_at`,
        current >= next,
      );
    }
  }

  // Step 4: Retrieve sessions sorted by created_at ascending (oldest first)
  const ascendingResult: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        sort_by: "created_at",
        sort_order: "asc",
        page: 1,
        limit: 20,
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(ascendingResult);

  // Step 5: Validate ascending order (oldest first)
  TestValidator.predicate(
    "ascending sort should return at least one session",
    ascendingResult.data.length >= 1,
  );

  // Validate sort order if multiple sessions exist
  if (ascendingResult.data.length > 1) {
    for (let i = 0; i < ascendingResult.data.length - 1; i++) {
      const current = new Date(ascendingResult.data[i].created_at);
      const next = new Date(ascendingResult.data[i + 1].created_at);

      TestValidator.predicate(
        `ascending order: session ${i} created_at should be <= session ${i + 1} created_at`,
        current <= next,
      );
    }
  }

  // Step 6: Verify both queries return consistent session counts
  TestValidator.equals(
    "both sort orders should return same number of sessions",
    descendingResult.data.length,
    ascendingResult.data.length,
  );

  // Step 7: Verify the admin ID matches in all returned sessions
  for (const session of descendingResult.data) {
    TestValidator.equals(
      "all sessions should belong to the created admin",
      session.admin.id,
      admin.id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdminSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test the general search capability across session metadata fields for quick
 * investigation.
 *
 * This scenario validates that the search parameter provides partial matching
 * across session metadata fields, particularly IP addresses and other available
 * session data. The test creates admin accounts with distinct IP addresses,
 * then uses the search parameter to quickly locate sessions with specific IP
 * patterns.
 *
 * Test Flow:
 *
 * 1. Create multiple admin accounts with different IP addresses
 * 2. Retrieve sessions to establish baseline
 * 3. Perform general search queries by IP address patterns
 * 4. Verify search returns relevant sessions matching the search term
 * 5. Validate search functionality with non-matching terms
 * 6. Test pagination structure
 */
export async function test_api_admin_session_general_search(
  connection: api.IConnection,
) {
  // Step 1: Create first admin account with distinctive IP pattern
  const adminEmail1 = typia.random<string & tags.Format<"email">>();
  const adminPassword1 = typia.random<string & tags.Format<"password">>();

  const admin1: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail1,
        password: adminPassword1,
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        ip: "192.168.1.100",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin1);

  // Step 2: Create second admin account with different IP pattern
  const adminEmail2 = typia.random<string & tags.Format<"email">>();
  const adminPassword2 = typia.random<string & tags.Format<"password">>();

  const admin2: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail2,
        password: adminPassword2,
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "moderator",
        email_verified: true,
        ip: "10.0.0.50",
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin2);

  // Step 3: Retrieve all sessions for first admin
  const allSessions: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin1.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(allSessions);

  TestValidator.predicate(
    "should have at least one session from registration",
    allSessions.data.length >= 1,
  );

  // Step 4: Test general search by IP address pattern for first admin
  const ipSearchTerm1 = "192.168";
  const ipSearchResults1: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin1.id,
      body: {
        page: 1,
        limit: 10,
        search: ipSearchTerm1,
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(ipSearchResults1);

  TestValidator.predicate(
    "IP search for 192.168 pattern should return sessions",
    ipSearchResults1.data.length > 0,
  );

  const hasMatchingIp1 = ipSearchResults1.data.some((session) =>
    session.ip.includes(ipSearchTerm1),
  );
  TestValidator.predicate(
    "search results should contain sessions with 192.168 IP pattern",
    hasMatchingIp1,
  );

  // Step 5: Test general search by different IP pattern for second admin
  const ipSearchTerm2 = "10.0.0";
  const ipSearchResults2: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin2.id,
      body: {
        page: 1,
        limit: 10,
        search: ipSearchTerm2,
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(ipSearchResults2);

  TestValidator.predicate(
    "IP search for 10.0.0 pattern should return sessions",
    ipSearchResults2.data.length > 0,
  );

  const hasMatchingIp2 = ipSearchResults2.data.some((session) =>
    session.ip.includes(ipSearchTerm2),
  );
  TestValidator.predicate(
    "search results should contain sessions with 10.0.0 IP pattern",
    hasMatchingIp2,
  );

  // Step 6: Test search with non-matching term
  const nonMatchingSearch: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin1.id,
      body: {
        page: 1,
        limit: 10,
        search: "999.999.999.999",
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(nonMatchingSearch);

  TestValidator.equals(
    "search with non-matching IP pattern should return empty results",
    nonMatchingSearch.data.length,
    0,
  );

  // Step 7: Test partial IP search
  const partialIpSearch: IPageIShoppingMallAdminSession.ISummary =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin1.id,
      body: {
        page: 1,
        limit: 10,
        search: "168.1",
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(partialIpSearch);

  TestValidator.predicate(
    "partial IP search should support substring matching",
    partialIpSearch.data.length > 0,
  );

  // Step 8: Validate pagination structure
  TestValidator.predicate(
    "pagination should have valid current page",
    allSessions.pagination.current >= 1,
  );

  TestValidator.predicate(
    "pagination should have valid limit",
    allSessions.pagination.limit > 0,
  );

  TestValidator.predicate(
    "pagination records should match or exceed data length",
    allSessions.pagination.records >= allSessions.data.length,
  );

  TestValidator.predicate(
    "pagination pages should be calculated correctly",
    allSessions.pagination.pages >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAdminSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallAdminSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdminSession";

/**
 * Test combining multiple filter parameters for precise session queries in
 * security investigations.
 *
 * This test validates that filter parameters can be used together to create
 * sophisticated queries for security monitoring. It ensures that combining
 * status, IP address, date range, and search filters returns only sessions
 * matching ALL criteria simultaneously.
 *
 * Process:
 *
 * 1. Create test admin account
 * 2. Establish initial authenticated session
 * 3. Retrieve sessions using combined filters (status + date range)
 * 4. Validate that all filters are applied correctly with AND logic
 * 5. Verify pagination reflects filtered results
 */
export async function test_api_admin_session_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for session tracking
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: RandomGenerator.pick([
        "super_admin",
        "moderator",
        "support",
      ] as const),
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Retrieve sessions using combined filters
  const now = new Date();
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

  const filteredSessions =
    await api.functional.shoppingMall.admin.admins.sessions.index(connection, {
      adminId: admin.id,
      body: {
        page: 1,
        limit: 10,
        status: "active",
        created_after: oneDayAgo.toISOString(),
        created_before: now.toISOString(),
        sort_by: "created_at",
        sort_order: "desc",
      } satisfies IShoppingMallAdminSession.IRequest,
    });
  typia.assert(filteredSessions);

  // Step 3: Validate filtered results
  TestValidator.predicate(
    "pagination data exists",
    filteredSessions.pagination !== null &&
      filteredSessions.pagination !== undefined,
  );

  TestValidator.predicate(
    "sessions array exists",
    Array.isArray(filteredSessions.data),
  );

  // Step 4: Verify all returned sessions match the combined filter criteria
  for (const session of filteredSessions.data) {
    typia.assert(session);

    // Verify session belongs to the correct admin
    TestValidator.equals(
      "session belongs to test admin",
      session.admin.id,
      admin.id,
    );

    // Verify session status matches filter (active sessions have null expired_at)
    TestValidator.equals("session status is active", session.expired_at, null);

    // Verify session created_at is within date range
    const sessionDate = new Date(session.created_at);
    TestValidator.predicate(
      "session created after start date",
      sessionDate >= oneDayAgo,
    );
    TestValidator.predicate(
      "session created before end date",
      sessionDate <= now,
    );
  }

  // Step 5: Test pagination metadata
  TestValidator.predicate(
    "current page is 1",
    filteredSessions.pagination.current === 1,
  );

  TestValidator.predicate(
    "limit matches request",
    filteredSessions.pagination.limit === 10,
  );

  TestValidator.predicate(
    "total records is non-negative",
    filteredSessions.pagination.records >= 0,
  );

  TestValidator.predicate(
    "total pages is non-negative",
    filteredSessions.pagination.pages >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
