import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";

/**
 * Test pagination functionality when searching seller authentication sessions
 * as admin.
 *
 * This test validates that the seller session search API correctly implements
 * pagination by creating multiple authentication sessions and testing various
 * page retrieval scenarios. It verifies that pagination metadata is accurate,
 * pages contain the correct number of records, and sort order is maintained
 * consistently across pages.
 *
 * Test workflow:
 *
 * 1. Create admin account for authentication
 * 2. Create seller account to generate initial session
 * 3. Generate 17 additional sessions by calling join endpoint with different
 *    IPs/URLs
 * 4. Test first page with limit 5 (should have 5 records)
 * 5. Test middle page (page 2) with limit 5 (should have 5 records)
 * 6. Test last page (page 4) with limit 5 (should have 3 records)
 * 7. Validate pagination metadata accuracy across all requests
 * 8. Verify consistent sort order using '-created_at'
 * 9. Test with different limit value (limit 10)
 */
export async function test_api_seller_session_search_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create admin account
  const adminData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: "super_admin" as const,
    email_verified: true,
    ip: "127.0.0.1",
    href: "https://admin.example.com/register",
    referrer: "https://admin.example.com/home",
  } satisfies IShoppingMallAdmin.ICreate;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminData,
    });
  typia.assert(admin);

  // Step 2: Create seller account (creates first session)
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "seller123";
  const sellerData = {
    email: sellerEmail,
    password: sellerPassword,
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    business_name: RandomGenerator.name(2),
    business_description: RandomGenerator.paragraph({ sentences: 5 }),
    store_name: RandomGenerator.name(2),
    ip: "192.168.1.1",
    href: "https://seller.example.com/register",
    referrer: "https://seller.example.com/info",
  } satisfies IShoppingMallSeller.ICreate;

  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: sellerData,
    });
  typia.assert(seller);

  // Step 3: Generate 17 additional sessions (total 18 sessions)
  // Note: Using join endpoint as workaround since no login endpoint is available
  const sessionCount = 18;

  for (let i = 0; i < sessionCount - 1; i++) {
    const sessionData = {
      email: sellerEmail,
      password: sellerPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.name(2),
      business_description: RandomGenerator.paragraph({ sentences: 5 }),
      store_name: RandomGenerator.name(2),
      ip: `192.168.1.${i + 2}`,
      href: `https://seller.example.com/session/${i}`,
      referrer: `https://seller.example.com/page/${i}`,
    } satisfies IShoppingMallSeller.ICreate;

    await api.functional.auth.seller.join(connection, {
      body: sessionData,
    });
  }

  // Step 4: Test first page (page 1, limit 5)
  const firstPageRequest = {
    page: 1,
    limit: 5,
    sort: ["-created_at"],
    shopping_mall_seller_id: seller.id,
  } satisfies IShoppingMallSellerSession.IRequest;

  const firstPage: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller.id,
      body: firstPageRequest,
    });
  typia.assert(firstPage);

  TestValidator.equals("first page current", firstPage.pagination.current, 1);
  TestValidator.equals("first page limit", firstPage.pagination.limit, 5);
  TestValidator.equals(
    "first page records",
    firstPage.pagination.records,
    sessionCount,
  );
  TestValidator.equals("first page pages", firstPage.pagination.pages, 4);
  TestValidator.equals("first page data count", firstPage.data.length, 5);

  // Step 5: Test middle page (page 2, limit 5)
  const middlePageRequest = {
    page: 2,
    limit: 5,
    sort: ["-created_at"],
    shopping_mall_seller_id: seller.id,
  } satisfies IShoppingMallSellerSession.IRequest;

  const middlePage: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller.id,
      body: middlePageRequest,
    });
  typia.assert(middlePage);

  TestValidator.equals("middle page current", middlePage.pagination.current, 2);
  TestValidator.equals("middle page limit", middlePage.pagination.limit, 5);
  TestValidator.equals(
    "middle page records",
    middlePage.pagination.records,
    sessionCount,
  );
  TestValidator.equals("middle page pages", middlePage.pagination.pages, 4);
  TestValidator.equals("middle page data count", middlePage.data.length, 5);

  // Step 6: Test last page (page 4, limit 5) - should have 3 records
  const lastPageRequest = {
    page: 4,
    limit: 5,
    sort: ["-created_at"],
    shopping_mall_seller_id: seller.id,
  } satisfies IShoppingMallSellerSession.IRequest;

  const lastPage: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller.id,
      body: lastPageRequest,
    });
  typia.assert(lastPage);

  TestValidator.equals("last page current", lastPage.pagination.current, 4);
  TestValidator.equals("last page limit", lastPage.pagination.limit, 5);
  TestValidator.equals(
    "last page records",
    lastPage.pagination.records,
    sessionCount,
  );
  TestValidator.equals("last page pages", lastPage.pagination.pages, 4);
  TestValidator.equals("last page data count", lastPage.data.length, 3);

  // Step 7: Verify sort order consistency (newest first with -created_at)
  for (let i = 0; i < firstPage.data.length - 1; i++) {
    const current = new Date(firstPage.data[i].created_at).getTime();
    const next = new Date(firstPage.data[i + 1].created_at).getTime();
    TestValidator.predicate("first page sort order", current >= next);
  }

  // Step 8: Test with different limit value (limit 10)
  const largeLimitRequest = {
    page: 1,
    limit: 10,
    sort: ["-created_at"],
    shopping_mall_seller_id: seller.id,
  } satisfies IShoppingMallSellerSession.IRequest;

  const largeLimitPage: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller.id,
      body: largeLimitRequest,
    });
  typia.assert(largeLimitPage);

  TestValidator.equals(
    "large limit page current",
    largeLimitPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "large limit page limit",
    largeLimitPage.pagination.limit,
    10,
  );
  TestValidator.equals(
    "large limit page records",
    largeLimitPage.pagination.records,
    sessionCount,
  );
  TestValidator.equals(
    "large limit page pages",
    largeLimitPage.pagination.pages,
    2,
  );
  TestValidator.equals(
    "large limit page data count",
    largeLimitPage.data.length,
    10,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";

/**
 * Test filtering seller sessions by IP address as admin.
 *
 * This test validates the IP address filtering functionality for seller
 * authentication sessions. It creates multiple seller accounts with different
 * IP addresses and tests that admin users can search for sessions filtering by
 * specific IP addresses. Only sessions with exact IP matches should be
 * returned.
 *
 * Test workflow:
 *
 * 1. Create first seller account with specific IP address (192.168.1.100)
 * 2. Create second seller account with different IP address (10.0.0.50)
 * 3. Create third seller account with another IP address (172.16.0.25)
 * 4. Authenticate as admin user to access session search functionality
 * 5. Search all sellers' sessions filtering by first IP address
 * 6. Validate that only sessions with exact IP match are returned
 * 7. Search filtering by second IP address and validate results
 * 8. Search filtering by non-existent IP address (should return empty)
 * 9. Verify that partial IP matching is NOT performed (exact match only)
 * 10. Confirm session summaries include accurate IP address information
 */
export async function test_api_seller_session_search_by_ip_address(
  connection: api.IConnection,
) {
  // Generate test IP addresses for different sessions
  const ipAddress1 = "192.168.1.100";
  const ipAddress2 = "10.0.0.50";
  const ipAddress3 = "172.16.0.25";
  const nonExistentIp = "203.0.113.99";

  // Step 1: Create first seller account with IP address 192.168.1.100
  const seller1Email = typia.random<string & tags.Format<"email">>();
  const seller1: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: seller1Email,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        business_name: RandomGenerator.name(2),
        business_description: RandomGenerator.paragraph({ sentences: 5 }),
        store_name: RandomGenerator.name(2),
        ip: ipAddress1,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller1);

  // Step 2: Create second seller account with IP address 10.0.0.50
  const seller2Email = typia.random<string & tags.Format<"email">>();
  const seller2: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: seller2Email,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        business_name: RandomGenerator.name(2),
        business_description: RandomGenerator.paragraph({ sentences: 5 }),
        store_name: RandomGenerator.name(2),
        ip: ipAddress2,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller2);

  // Step 3: Create third seller account with IP address 172.16.0.25
  const seller3Email = typia.random<string & tags.Format<"email">>();
  const seller3: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: seller3Email,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        business_name: RandomGenerator.name(2),
        business_description: RandomGenerator.paragraph({ sentences: 5 }),
        store_name: RandomGenerator.name(2),
        ip: ipAddress3,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller3);

  // Step 4: Authenticate as admin user
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        ip: typia.random<string & tags.Format<"ipv4">>(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 5: Search seller1's sessions filtering by ipAddress1 (exact match)
  const seller1SessionsWithIp1: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller1.id,
      body: {
        ip: ipAddress1,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(seller1SessionsWithIp1);

  // Step 6: Validate that seller1's sessions with IP1 are found
  TestValidator.predicate(
    "seller1 sessions with IP 192.168.1.100 should be found",
    seller1SessionsWithIp1.data.length > 0,
  );

  // Validate that all returned sessions have the exact IP address
  seller1SessionsWithIp1.data.forEach((session) => {
    TestValidator.equals(
      "session IP should exactly match ipAddress1",
      session.ip,
      ipAddress1,
    );
  });

  // Step 7: Search seller2's sessions filtering by ipAddress2
  const seller2SessionsWithIp2: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller2.id,
      body: {
        ip: ipAddress2,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(seller2SessionsWithIp2);

  TestValidator.predicate(
    "seller2 sessions with IP 10.0.0.50 should be found",
    seller2SessionsWithIp2.data.length > 0,
  );

  seller2SessionsWithIp2.data.forEach((session) => {
    TestValidator.equals(
      "session IP should exactly match ipAddress2",
      session.ip,
      ipAddress2,
    );
  });

  // Step 8: Verify that searching seller1 with seller2's IP returns no results
  const seller1SessionsWithIp2: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller1.id,
      body: {
        ip: ipAddress2,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(seller1SessionsWithIp2);

  TestValidator.equals(
    "seller1 should have no sessions with seller2's IP",
    seller1SessionsWithIp2.data.length,
    0,
  );

  // Step 9: Search sessions filtering by non-existent IP address
  const sessionsWithNonExistentIp: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller1.id,
      body: {
        ip: nonExistentIp,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(sessionsWithNonExistentIp);

  TestValidator.equals(
    "no sessions should be found for non-existent IP",
    sessionsWithNonExistentIp.data.length,
    0,
  );

  // Step 10: Verify that partial IP matching does NOT work (exact match only)
  const partialIpSearch: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller1.id,
      body: {
        ip: "192.168",
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(partialIpSearch);

  TestValidator.equals(
    "partial IP matching should not return results",
    partialIpSearch.data.length,
    0,
  );

  // Step 11: Retrieve all sessions for seller1 without IP filter
  const allSeller1Sessions: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: seller1.id,
      body: {} satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(allSeller1Sessions);

  // Verify that session summaries include accurate IP information
  allSeller1Sessions.data.forEach((session) => {
    TestValidator.predicate(
      "session should have valid IP address",
      session.ip !== null && session.ip !== undefined && session.ip.length > 0,
    );
  });

  // Verify that at least one session has ipAddress1
  const hasIpAddress1 = allSeller1Sessions.data.some(
    (session) => session.ip === ipAddress1,
  );
  TestValidator.predicate(
    "seller1 sessions should contain at least one with ipAddress1",
    hasIpAddress1,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerSession";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";

/**
 * Test date range filtering for seller session searches as admin.
 *
 * This test validates the date range filtering functionality for seller
 * authentication sessions. It creates a seller account which generates an
 * initial session, then authenticates as an admin and tests various date range
 * filtering scenarios:
 *
 * 1. Filter sessions created after a specific date (created_at_after only)
 * 2. Filter sessions created before a specific date (created_at_before only)
 * 3. Filter sessions within a specific time window (both created_at_after and
 *    created_at_before)
 * 4. Filter sessions by expiration date ranges (expired_at_after,
 *    expired_at_before) if applicable
 *
 * Each test verifies that only sessions matching the date range criteria are
 * returned while sessions outside the range are properly excluded. The test
 * also confirms ISO 8601 date-time format handling.
 */
export async function test_api_seller_session_search_by_date_range(
  connection: api.IConnection,
) {
  // Create a seller account to generate initial session
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        business_name: RandomGenerator.name(2),
        business_description: RandomGenerator.paragraph({ sentences: 5 }),
        store_name: RandomGenerator.name(2),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  const sellerId = seller.id;

  // Create and authenticate as admin to search seller sessions
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: RandomGenerator.pick([
          "super_admin",
          "moderator",
          "support",
        ] as const),
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Get all sessions to understand the available data
  const allSessionsResult: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: sellerId,
      body: {} satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(allSessionsResult);

  TestValidator.predicate(
    "should have at least one session created",
    allSessionsResult.data.length > 0,
  );

  // Test 1: Filter sessions created after a specific date (created_at_after only)
  const firstSession = allSessionsResult.data[0];
  const pastDate = new Date(
    new Date(firstSession.created_at).getTime() - 1000 * 60 * 60,
  ).toISOString();

  const afterFilterResult: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: sellerId,
      body: {
        created_at_after: pastDate,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(afterFilterResult);

  TestValidator.predicate(
    "sessions filtered by created_at_after should only include sessions created after the specified date",
    afterFilterResult.data.every((session) => session.created_at >= pastDate),
  );

  // Test 2: Filter sessions created before a specific date (created_at_before only)
  const futureDate = new Date(
    new Date(firstSession.created_at).getTime() + 1000 * 60 * 60 * 24,
  ).toISOString();

  const beforeFilterResult: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: sellerId,
      body: {
        created_at_before: futureDate,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(beforeFilterResult);

  TestValidator.predicate(
    "sessions filtered by created_at_before should only include sessions created before the specified date",
    beforeFilterResult.data.every(
      (session) => session.created_at <= futureDate,
    ),
  );

  // Test 3: Filter sessions within a specific time window (both parameters)
  const windowStart = new Date(
    new Date(firstSession.created_at).getTime() - 1000 * 60 * 60,
  ).toISOString();
  const windowEnd = new Date(
    new Date(firstSession.created_at).getTime() + 1000 * 60 * 60 * 24,
  ).toISOString();

  const windowFilterResult: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: sellerId,
      body: {
        created_at_after: windowStart,
        created_at_before: windowEnd,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(windowFilterResult);

  TestValidator.predicate(
    "sessions filtered by time window should only include sessions within the date range",
    windowFilterResult.data.every(
      (session) =>
        session.created_at >= windowStart && session.created_at <= windowEnd,
    ),
  );

  TestValidator.predicate(
    "time window filter should return the session",
    windowFilterResult.data.length > 0,
  );

  // Test 4: Test expired_at filters if there are any expired sessions
  const expiredSessions = allSessionsResult.data.filter(
    (s) => s.expired_at !== null,
  );

  if (expiredSessions.length > 0) {
    const expiredSession = expiredSessions[0];
    typia.assertGuard(expiredSession.expired_at!);

    const expiredAfterResult: IPageIShoppingMallSellerSession.ISummary =
      await api.functional.shoppingMall.admin.sellers.sessions.index(
        connection,
        {
          sellerId: sellerId,
          body: {
            expired_at_after: expiredSession.expired_at,
          } satisfies IShoppingMallSellerSession.IRequest,
        },
      );
    typia.assert(expiredAfterResult);

    TestValidator.predicate(
      "sessions filtered by expired_at_after should only include sessions expired after the specified date",
      expiredAfterResult.data.every(
        (session) =>
          session.expired_at !== null &&
          session.expired_at >= expiredSession.expired_at!,
      ),
    );

    const expiredBeforeDate = new Date(
      new Date(expiredSession.expired_at).getTime() + 1000 * 60 * 60 * 24,
    ).toISOString();

    const expiredBeforeResult: IPageIShoppingMallSellerSession.ISummary =
      await api.functional.shoppingMall.admin.sellers.sessions.index(
        connection,
        {
          sellerId: sellerId,
          body: {
            expired_at_before: expiredBeforeDate,
          } satisfies IShoppingMallSellerSession.IRequest,
        },
      );
    typia.assert(expiredBeforeResult);

    TestValidator.predicate(
      "sessions filtered by expired_at_before should only include sessions expired before the specified date",
      expiredBeforeResult.data.every(
        (session) =>
          session.expired_at !== null &&
          session.expired_at <= expiredBeforeDate,
      ),
    );
  }

  // Test 5: Verify ISO 8601 format handling
  const now = new Date();
  const futureISODate = new Date(
    now.getTime() + 1000 * 60 * 60 * 24 * 365,
  ).toISOString();

  const isoFormatResult: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: sellerId,
      body: {
        created_at_before: futureISODate,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(isoFormatResult);

  TestValidator.predicate(
    "ISO 8601 date-time format should be properly handled",
    isoFormatResult.data.length > 0,
  );

  // Test 6: Verify that date range excludes sessions outside the range
  const veryOldDate = new Date(
    new Date(firstSession.created_at).getTime() - 1000 * 60 * 60 * 24 * 365,
  ).toISOString();
  const veryOldDateEnd = new Date(
    new Date(firstSession.created_at).getTime() - 1000 * 60 * 60 * 24 * 364,
  ).toISOString();

  const emptyRangeResult: IPageIShoppingMallSellerSession.ISummary =
    await api.functional.shoppingMall.admin.sellers.sessions.index(connection, {
      sellerId: sellerId,
      body: {
        created_at_after: veryOldDate,
        created_at_before: veryOldDateEnd,
      } satisfies IShoppingMallSellerSession.IRequest,
    });
  typia.assert(emptyRangeResult);

  TestValidator.predicate(
    "date range that excludes all sessions should return empty results",
    emptyRangeResult.data.length === 0,
  );
}

