  TestValidator.equals("page 1 limit", page1.pagination.limit, 20);
  TestValidator.predicate(
    "page 1 records is non-negative",
    page1.pagination.records >= 0,
  );
  TestValidator.predicate(
    "page 1 pages is non-negative",
    page1.pagination.pages >= 0,
