  // Step 2: Test is_refunded=true filter - should return only refunded commission records
  const refundedOnly =
    await api.functional.shoppingMall.seller.sellers.platformCommissions.index(
      connection,
      {
        sellerId: seller.id,
        body: {
          page: 1,
          limit: 20,
