    await api.functional.shoppingMall.seller.sales.skus.images.erase(
      connection,
      {
        saleCode: sale.code,
        skuCode: sku.sku_code,
        imageId: image.id,
      },
    );
  typia.assert(deletedImage);

  // Step 9: Verify deletion was successful
