import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test that the category search endpoint is publicly accessible without
 * authentication.
 *
 * This test validates that buyers and anonymous users can browse the category
 * hierarchy to discover products without requiring any authorization tokens.
 * The test confirms that category browsing is a fundamental public marketplace
 * feature by executing multiple search operations with various parameters while
 * using an unauthenticated connection.
 *
 * Test Flow:
 *
 * 1. Create unauthenticated connection with empty headers
 * 2. Search categories with default parameters (no filters)
 * 3. Search with pagination parameters
 * 4. Search with status filter
 * 5. Search with parent_id filter for hierarchical navigation
 * 6. Search with sorting options
 * 7. Validate all responses return proper data structures
 */
export async function test_api_category_search_public_access(
  connection: api.IConnection,
) {
  // Create unauthenticated connection with empty headers
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  // Test 1: Basic category search without any parameters
  const basicSearch = await api.functional.shoppingMall.categories.index(
    unauthConn,
    {
      body: {} satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(basicSearch);
  TestValidator.predicate(
    "basic search returns valid pagination",
    basicSearch.pagination.current >= 0 && basicSearch.pagination.pages >= 0,
  );

  // Test 2: Category search with pagination parameters
  const page = typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>();
  const limit = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
  >();

  const paginatedSearch = await api.functional.shoppingMall.categories.index(
    unauthConn,
    {
      body: {
        page: page,
        limit: limit,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(paginatedSearch);
  TestValidator.predicate(
    "paginated search respects limit",
    paginatedSearch.data.length <= limit,
  );

  // Test 3: Category search with status filter
  const statuses = ["active", "inactive"] as const;
  const status = RandomGenerator.pick(statuses);

  const statusSearch = await api.functional.shoppingMall.categories.index(
    unauthConn,
    {
      body: {
        status: status,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(statusSearch);
  TestValidator.predicate(
    "status filter returns categories",
    statusSearch.pagination.records >= 0,
  );

  // Test 4: Search root-level categories (parent_id = null)
  const rootCategoriesSearch =
    await api.functional.shoppingMall.categories.index(unauthConn, {
      body: {
        parent_id: null,
        limit: 20,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(rootCategoriesSearch);
  TestValidator.predicate(
    "root categories search succeeds",
    rootCategoriesSearch.pagination.records >= 0,
  );

  // Test 5: Category search with text search query
  const searchQuery = RandomGenerator.alphabets(5);

  const textSearch = await api.functional.shoppingMall.categories.index(
    unauthConn,
    {
      body: {
        search: searchQuery,
        limit: 15,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(textSearch);
  TestValidator.predicate(
    "text search returns valid results",
    textSearch.pagination.records >= 0,
  );

  // Test 6: Category search with sorting options
  const sortByOptions = ["name", "created_at", "display_order"] as const;
  const sortDirections = ["asc", "desc"] as const;

  const sortBy = RandomGenerator.pick(sortByOptions);
  const sortDirection = RandomGenerator.pick(sortDirections);

  const sortedSearch = await api.functional.shoppingMall.categories.index(
    unauthConn,
    {
      body: {
        sort_by: sortBy,
        sort_direction: sortDirection,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(sortedSearch);
  TestValidator.predicate(
    "sorted search returns valid data",
    sortedSearch.data.length >= 0,
  );

  // Test 7: Complex search with multiple parameters
  const complexSearch = await api.functional.shoppingMall.categories.index(
    unauthConn,
    {
      body: {
        page: 1,
        limit: 25,
        status: "active",
        sort_by: "name",
        sort_direction: "asc",
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(complexSearch);
  TestValidator.predicate(
    "complex search with multiple filters succeeds",
    complexSearch.pagination.current === 1,
  );
  TestValidator.predicate(
    "complex search respects limit",
    complexSearch.data.length <= 25,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test category retrieval with various pagination parameters.
 *
 * This test validates that the category listing API properly handles pagination
 * by testing different page numbers and limits. It ensures that:
 *
 * 1. First page retrieval works correctly
 * 2. Middle pages return the expected number of items
 * 3. Last page handling is correct
 * 4. Pages beyond available data return empty results
 * 5. Pagination metadata (current, limit, records, pages) is accurate
 * 6. Different page sizes (limits) work as expected
 */
export async function test_api_category_search_with_pagination(
  connection: api.IConnection,
) {
  // Test with first page and default limit
  const firstPage = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(firstPage);

  // Validate pagination metadata for first page
  TestValidator.equals(
    "first page current should be 1",
    firstPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "first page limit should be 10",
    firstPage.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "first page should have records",
    firstPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "first page data length should not exceed limit",
    firstPage.data.length <= 10,
  );

  // Test with a different page size
  const smallPage = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(smallPage);

  TestValidator.equals(
    "small page limit should be 5",
    smallPage.pagination.limit,
    5,
  );
  TestValidator.predicate(
    "small page data length should not exceed 5",
    smallPage.data.length <= 5,
  );

  // Test middle page if there are enough records
  if (firstPage.pagination.pages > 2) {
    const middlePage = await api.functional.shoppingMall.categories.index(
      connection,
      {
        body: {
          page: 2,
          limit: 10,
        } satisfies IShoppingMallCategory.IRequest,
      },
    );
    typia.assert(middlePage);

    TestValidator.equals(
      "middle page current should be 2",
      middlePage.pagination.current,
      2,
    );
    TestValidator.equals(
      "middle page should have same total records",
      middlePage.pagination.records,
      firstPage.pagination.records,
    );
    TestValidator.predicate(
      "middle page data length should not exceed limit",
      middlePage.data.length <= 10,
    );
  }

  // Test last page
  if (firstPage.pagination.pages > 0) {
    const lastPage = await api.functional.shoppingMall.categories.index(
      connection,
      {
        body: {
          page: firstPage.pagination.pages,
          limit: 10,
        } satisfies IShoppingMallCategory.IRequest,
      },
    );
    typia.assert(lastPage);

    TestValidator.equals(
      "last page current should match pages count",
      lastPage.pagination.current,
      firstPage.pagination.pages,
    );
    TestValidator.equals(
      "last page should have same total records",
      lastPage.pagination.records,
      firstPage.pagination.records,
    );
  }

  // Test page beyond available data
  const beyondPage = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: firstPage.pagination.pages + 10,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(beyondPage);

  TestValidator.predicate(
    "beyond page should return empty or minimal data",
    beyondPage.data.length === 0 ||
      beyondPage.pagination.current > beyondPage.pagination.pages,
  );

  // Test with maximum allowed limit
  const maxLimitPage = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(maxLimitPage);

  TestValidator.equals(
    "max limit page limit should be 100",
    maxLimitPage.pagination.limit,
    100,
  );
  TestValidator.predicate(
    "max limit page data length should not exceed 100",
    maxLimitPage.data.length <= 100,
  );

  // Verify pagination calculations are consistent
  TestValidator.predicate(
    "total pages calculation should be consistent",
    firstPage.pagination.pages ===
      Math.ceil(firstPage.pagination.records / firstPage.pagination.limit),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test category search functionality using the search query parameter to filter
 * categories by name.
 *
 * This test validates that the category search API correctly filters results
 * based on the search parameter, supporting partial name matching and
 * case-insensitive queries.
 *
 * Test workflow:
 *
 * 1. Search with empty/undefined query to get all categories baseline
 * 2. Search with partial name match to verify substring filtering works
 * 3. Search with different casing to verify case-insensitive behavior
 * 4. Validate that only matching categories are returned in results
 */
export async function test_api_category_search_by_name(
  connection: api.IConnection,
) {
  // Test 1: Search with undefined search parameter (should return all categories)
  const allCategoriesResult =
    await api.functional.shoppingMall.categories.index(connection, {
      body: {
        page: 1,
        limit: 100,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(allCategoriesResult);

  // Verify we have categories to test with
  TestValidator.predicate(
    "should have categories available for testing",
    allCategoriesResult.data.length > 0,
  );

  // Test 2: Pick a random category and search with partial name
  const randomCategory = RandomGenerator.pick(allCategoriesResult.data);
  const searchTerm = randomCategory.name.substring(
    0,
    Math.max(2, Math.floor(randomCategory.name.length / 2)),
  );

  const partialSearchResult =
    await api.functional.shoppingMall.categories.index(connection, {
      body: {
        page: 1,
        limit: 100,
        search: searchTerm,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(partialSearchResult);

  // Validate partial match works
  TestValidator.predicate(
    "partial search should return at least one result",
    partialSearchResult.data.length > 0,
  );

  // Verify all returned categories contain the search term (case-insensitive)
  const allMatchPartialSearch = partialSearchResult.data.every((category) =>
    category.name.toLowerCase().includes(searchTerm.toLowerCase()),
  );
  TestValidator.predicate(
    "all results should contain the search term in their name",
    allMatchPartialSearch,
  );

  // Test 3: Case-insensitive search with uppercase
  const uppercaseSearchResult =
    await api.functional.shoppingMall.categories.index(connection, {
      body: {
        page: 1,
        limit: 100,
        search: searchTerm.toUpperCase(),
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(uppercaseSearchResult);

  // Verify case-insensitive behavior - results should be the same
  TestValidator.equals(
    "case-insensitive search should return same results",
    partialSearchResult.data.map((c) => c.id).sort(),
    uppercaseSearchResult.data.map((c) => c.id).sort(),
  );

  // Test 4: Search with exact full name
  const exactSearchResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
        search: randomCategory.name,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(exactSearchResult);

  // Should find at least the original category
  const foundOriginal = exactSearchResult.data.some(
    (category) => category.id === randomCategory.id,
  );
  TestValidator.predicate(
    "exact name search should find the original category",
    foundOriginal,
  );

  // Test 5: Search with non-existent term
  const nonExistentTerm = RandomGenerator.alphaNumeric(20) + "_nonexistent_xyz";
  const emptySearchResult = await api.functional.shoppingMall.categories.index(
    connection,
    {
      body: {
        page: 1,
        limit: 100,
        search: nonExistentTerm,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(emptySearchResult);

  // Should return no results
  TestValidator.equals(
    "search with non-existent term should return empty results",
    emptySearchResult.data.length,
    0,
  );
}

