/**
 * Test creating hierarchical category structures with parent-child
 * relationships.
 *
 * This test validates the ability to build multi-level category taxonomies by:
 *
 * 1. Creating a parent category at the root level
 * 2. Creating a child category that references the parent
 * 3. Verifying the parent-child relationship is correctly established
 *
 * This ensures the marketplace can organize products into nested hierarchical
 * classifications, which is essential for product discovery and navigation.
 */
export async function test_api_category_creation_with_parent(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin for category management operations
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "AdminPass123!",
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create a parent category at the root level (no parent_id)
  const parentCategoryName = `${RandomGenerator.name()} Category`;
  const parentCategorySlug = parentCategoryName
    .toLowerCase()
    .replace(/\s+/g, "-");

  const parentCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: parentCategoryName,
        slug: parentCategorySlug,
        description: RandomGenerator.paragraph({
          sentences: 3,
          wordMin: 5,
          wordMax: 10,
        }),
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Validate parent category creation
  TestValidator.equals(
    "parent category name matches",
    parentCategory.name,
    parentCategoryName,
  );
  TestValidator.equals(
    "parent category slug matches",
    parentCategory.slug,
    parentCategorySlug,
  );
  TestValidator.equals(
    "parent category has no parent",
    parentCategory.parent_id,
    null,
  );
  TestValidator.equals(
    "parent category status is active",
    parentCategory.status,
    "active",
  );

  // Step 3: Create a child category with parent_id referencing the parent
  const childCategoryName = `${RandomGenerator.name()} Subcategory`;
  const childCategorySlug = childCategoryName
    .toLowerCase()
    .replace(/\s+/g, "-");

  const childCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: childCategoryName,
        slug: childCategorySlug,
        description: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 4,
          wordMax: 8,
        }),
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(childCategory);

  // Step 4: Verify the parent-child relationship is correctly established
  TestValidator.equals(
    "child category name matches",
    childCategory.name,
    childCategoryName,
  );
  TestValidator.equals(
    "child category slug matches",
    childCategory.slug,
    childCategorySlug,
  );
  TestValidator.equals(
    "child category parent_id references parent",
    childCategory.parent_id,
    parentCategory.id,
  );
  TestValidator.equals(
    "child category status is active",
    childCategory.status,
    "active",
  );

  // Validate hierarchical relationship
  TestValidator.predicate(
    "parent-child relationship established correctly",
    childCategory.parent_id === parentCategory.id,
  );
}

