import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test building a deep category hierarchy with multiple nesting levels.
 *
 * This test validates the system's ability to support unlimited category
 * nesting depth by creating a multi-level hierarchical structure. Starting with
 * a root category, the test progressively creates child categories at
 * increasing depths (child, grandchild, great-grandchild) to verify that
 * hierarchical relationships are correctly maintained throughout the tree
 * structure.
 *
 * The test ensures that each category correctly references its parent and that
 * the parent_id foreign key relationships enable proper tree navigation. This
 * validates the system's capability to support complex product taxonomies with
 * sophisticated organization suitable for large-scale e-commerce catalogs.
 *
 * Test Steps:
 *
 * 1. Authenticate as admin to gain category management permissions
 * 2. Create root category (level 0 - no parent)
 * 3. Create child category with root as parent (level 1)
 * 4. Create grandchild category with child as parent (level 2)
 * 5. Create great-grandchild category with grandchild as parent (level 3)
 * 6. Validate parent-child relationships at each level
 * 7. Verify hierarchical integrity across the entire tree
 */
export async function test_api_category_creation_multi_level_hierarchy(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin" as const,
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create root category (level 0 - no parent)
  const rootCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: null,
        name: "Electronics",
        slug: `electronics-${typia.random<number & tags.Type<"uint32">>()}`,
        description: "Root level category for all electronic products",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active" as const,
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(rootCategory);
  TestValidator.equals(
    "root category has no parent",
    rootCategory.parent_id,
    null,
  );

  // Step 3: Create child category (level 1)
  const childCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: rootCategory.id,
        name: "Computers",
        slug: `computers-${typia.random<number & tags.Type<"uint32">>()}`,
        description: "Computer products under Electronics",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active" as const,
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(childCategory);
  TestValidator.equals(
    "child category parent_id matches root",
    childCategory.parent_id,
    rootCategory.id,
  );

  // Step 4: Create grandchild category (level 2)
  const grandchildCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: childCategory.id,
        name: "Laptops",
        slug: `laptops-${typia.random<number & tags.Type<"uint32">>()}`,
        description: "Laptop computers under Computers category",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active" as const,
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(grandchildCategory);
  TestValidator.equals(
    "grandchild category parent_id matches child",
    grandchildCategory.parent_id,
    childCategory.id,
  );

  // Step 5: Create great-grandchild category (level 3)
  const greatGrandchildCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: grandchildCategory.id,
        name: "Gaming Laptops",
        slug: `gaming-laptops-${typia.random<number & tags.Type<"uint32">>()}`,
        description: "High-performance gaming laptops",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active" as const,
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(greatGrandchildCategory);
  TestValidator.equals(
    "great-grandchild category parent_id matches grandchild",
    greatGrandchildCategory.parent_id,
    grandchildCategory.id,
  );

  // Step 6: Verify hierarchical integrity
  TestValidator.predicate(
    "root category is at top level",
    rootCategory.parent_id === null,
  );
  TestValidator.predicate(
    "child references root",
    childCategory.parent_id === rootCategory.id,
  );
  TestValidator.predicate(
    "grandchild references child",
    grandchildCategory.parent_id === childCategory.id,
  );
  TestValidator.predicate(
    "great-grandchild references grandchild",
    greatGrandchildCategory.parent_id === grandchildCategory.id,
  );

  // Validate all categories have proper initialization
  TestValidator.predicate(
    "root category has zero products initially",
    rootCategory.product_count === 0,
  );
  TestValidator.predicate(
    "child category has zero products initially",
    childCategory.product_count === 0,
  );
  TestValidator.predicate(
    "grandchild category has zero products initially",
    grandchildCategory.product_count === 0,
  );
  TestValidator.predicate(
    "great-grandchild category has zero products initially",
    greatGrandchildCategory.product_count === 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallInventoryReservation";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryReservation";

/**
 * Test that administrators can retrieve a paginated list of all active
 * inventory reservations.
 *
 * This test validates the admin's ability to monitor current inventory holds
 * system-wide, which is critical for inventory management and oversight. The
 * test creates an admin account, then queries the inventory reservation
 * endpoint filtering by reservation_status='active' to verify proper pagination
 * and that only active reservations are returned.
 *
 * Workflow:
 *
 * 1. Create and authenticate as admin user with platform-wide access
 * 2. Query the admin endpoint filtering by reservation_status='active' with
 *    pagination
 * 3. Validate pagination metadata (current page, limit, total records, total
 *    pages)
 * 4. Verify all returned reservations have status='active'
 * 5. Validate complete type safety of response using typia.assert()
 */
export async function test_api_inventory_reservation_admin_search_all_active(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate as admin user
  const adminData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.Format<"password">>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: RandomGenerator.pick([
      "super_admin",
      "moderator",
      "support",
    ] as const),
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const admin = await api.functional.auth.admin.join(connection, {
    body: adminData,
  });
  typia.assert(admin);

  // Step 2: Query all active inventory reservations with pagination
  const searchRequest = {
    page: 1,
    limit: 10,
    reservation_status: "active" as const,
  } satisfies IShoppingMallInventoryReservation.IRequest;

  const searchResult =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: searchRequest,
      },
    );
  typia.assert(searchResult);

  // Step 3: Validate pagination metadata
  const pagination = searchResult.pagination;
  typia.assert(pagination);

  TestValidator.equals("current page matches request", pagination.current, 1);

  TestValidator.equals("limit matches request", pagination.limit, 10);

  TestValidator.predicate(
    "records count is non-negative",
    pagination.records >= 0,
  );

  TestValidator.predicate("pages count is non-negative", pagination.pages >= 0);

  // Step 4: Validate that all returned reservations have status='active'
  for (const reservation of searchResult.data) {
    typia.assert(reservation);

    TestValidator.equals(
      "reservation status is active",
      reservation.reservation_status,
      "active",
    );

    TestValidator.predicate(
      "reserved quantity is positive",
      reservation.reserved_quantity >= 1,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallInventoryReservation";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryReservation";

/**
 * Test that administrators can filter inventory reservations by specific buyer
 * ID.
 *
 * This test validates the buyer_id filter parameter functionality in the
 * inventory reservation search API. Since we don't have endpoints to create
 * test buyers or reservations, this test focuses on validating the filter
 * parameter behavior:
 *
 * Test workflow:
 *
 * 1. Authenticate as admin to access reservation filtering API
 * 2. Query all reservations without filter to get existing data
 * 3. If reservations exist, select a buyer_id from the results
 * 4. Query reservations filtered by that specific buyer ID
 * 5. Validate that all returned records match the filter criteria
 * 6. Verify pagination metadata is consistent
 * 7. Test with a random UUID to verify empty results for non-existent buyers
 */
export async function test_api_inventory_reservation_admin_filter_by_buyer(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin to access reservation filtering
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Query all reservations to get existing data
  const allReservations: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(allReservations);

  // Step 3: Validate basic pagination structure
  TestValidator.predicate(
    "unfiltered pagination should be valid",
    allReservations.pagination.current >= 1 &&
      allReservations.pagination.limit >= 1 &&
      allReservations.pagination.records >= 0 &&
      allReservations.pagination.pages >= 0,
  );

  // Step 4: If reservations exist, test filtering by an actual buyer_id
  if (allReservations.data.length > 0) {
    const sampleReservation: IShoppingMallInventoryReservation =
      RandomGenerator.pick(allReservations.data);
    const targetBuyerId: string & tags.Format<"uuid"> =
      sampleReservation.shopping_mall_buyer_id;

    // Step 5: Query reservations filtered by the specific buyer ID
    const filteredResult: IPageIShoppingMallInventoryReservation =
      await api.functional.shoppingMall.admin.inventoryReservations.index(
        connection,
        {
          body: {
            page: 1,
            limit: 100,
            shopping_mall_buyer_id: targetBuyerId,
          } satisfies IShoppingMallInventoryReservation.IRequest,
        },
      );
    typia.assert(filteredResult);

    // Step 6: Validate filtered pagination metadata
    TestValidator.predicate(
      "filtered pagination should be valid",
      filteredResult.pagination.current >= 1 &&
        filteredResult.pagination.limit >= 1 &&
        filteredResult.pagination.records >= 0 &&
        filteredResult.pagination.pages >= 0,
    );

    // Step 7: Verify filtered results are not more than total results
    TestValidator.predicate(
      "filtered results should not exceed total results",
      filteredResult.pagination.records <= allReservations.pagination.records,
    );

    // Step 8: Validate that ALL returned reservations belong to the target buyer
    TestValidator.predicate(
      "at least one reservation should be returned for existing buyer",
      filteredResult.data.length > 0,
    );

    filteredResult.data.forEach(
      (reservation: IShoppingMallInventoryReservation, index: number) => {
        TestValidator.equals(
          `reservation ${index} should belong to target buyer`,
          reservation.shopping_mall_buyer_id,
          targetBuyerId,
        );
      },
    );
  }

  // Step 9: Test filtering by non-existent buyer ID (should return empty results)
  const nonExistentBuyerId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const emptyResult: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          shopping_mall_buyer_id: nonExistentBuyerId,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(emptyResult);

  // Step 10: Validate that filtering by non-existent buyer returns zero results
  TestValidator.equals(
    "non-existent buyer should return zero reservations",
    emptyResult.data.length,
    0,
  );
  TestValidator.equals(
    "non-existent buyer should have zero total records",
    emptyResult.pagination.records,
    0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallInventoryReservation";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryReservation";

/**
 * Test admin filtering of inventory reservations by specific SKU ID.
 *
 * This test validates that administrators can filter inventory reservations by
 * a specific SKU ID to monitor which products have active holds. This enables
 * product-specific inventory tracking and helps admins understand current
 * demand and inventory commitment for specific product variants.
 *
 * Test Flow:
 *
 * 1. Create and authenticate as admin user
 * 2. Query all reservations without filters to establish baseline
 * 3. Query reservations filtered by a specific SKU ID
 * 4. Validate response structure and filtering behavior
 * 5. Test with multiple different SKU ID filters
 * 6. Confirm SKU-level inventory monitoring API works correctly
 */
export async function test_api_inventory_reservation_admin_filter_by_sku(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate as admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Query all reservations without SKU filter to get baseline data
  const allReservations: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          page: 1,
          limit: 100,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(allReservations);

  // Step 3: Validate pagination structure
  TestValidator.predicate(
    "pagination should have valid structure",
    allReservations.pagination.current >= 0 &&
      allReservations.pagination.limit > 0 &&
      allReservations.pagination.records >= 0 &&
      allReservations.pagination.pages >= 0,
  );

  // Step 4: If reservations exist, test SKU filtering with actual SKU IDs
  if (allReservations.data.length > 0) {
    const firstReservation = allReservations.data[0];
    typia.assert(firstReservation);
    const targetSkuId = firstReservation.shopping_mall_sale_sku_id;

    // Query reservations filtered by the specific SKU ID
    const filteredResult: IPageIShoppingMallInventoryReservation =
      await api.functional.shoppingMall.admin.inventoryReservations.index(
        connection,
        {
          body: {
            shopping_mall_sale_sku_id: targetSkuId,
            page: 1,
            limit: 50,
          } satisfies IShoppingMallInventoryReservation.IRequest,
        },
      );
    typia.assert(filteredResult);

    // Validate that all returned reservations match the target SKU
    TestValidator.predicate(
      "filtered result should contain at least the original reservation",
      filteredResult.data.length > 0,
    );

    for (const reservation of filteredResult.data) {
      TestValidator.equals(
        "reservation SKU ID should match filter",
        reservation.shopping_mall_sale_sku_id,
        targetSkuId,
      );
    }

    // Verify filtered count is less than or equal to total count
    TestValidator.predicate(
      "filtered reservations should be subset of all reservations",
      filteredResult.pagination.records <= allReservations.pagination.records,
    );
  }

  // Step 5: Test filtering with a random SKU ID (likely to return empty results)
  const randomSkuId = typia.random<string & tags.Format<"uuid">>();
  const randomSkuResult: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: randomSkuId,
          page: 1,
          limit: 10,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(randomSkuResult);

  // Validate that random SKU filter works even if no results
  for (const reservation of randomSkuResult.data) {
    TestValidator.equals(
      "random SKU filter should only return matching reservations",
      reservation.shopping_mall_sale_sku_id,
      randomSkuId,
    );
  }

  // Step 6: Test filtering with null SKU ID (should return all reservations)
  const nullSkuResult: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: null,
          page: 1,
          limit: 50,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(nullSkuResult);

  TestValidator.predicate(
    "null SKU filter should work without errors",
    nullSkuResult.pagination.records >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallInventoryReservation";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallInventoryReservation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInventoryReservation";

/**
 * Test that administrators can filter inventory reservations by order ID
 * parameter.
 *
 * Validates the shopping_mall_order_id filter parameter functionality by
 * querying reservations with different order ID values and validating response
 * structure. Tests filtering mechanics including null values and status
 * combinations.
 *
 * Workflow:
 *
 * 1. Authenticate as admin
 * 2. Test filtering with specific order ID
 * 3. Test filtering for unconverted reservations (null order ID)
 * 4. Test combined filters (status + order relationship)
 * 5. Validate pagination and response structure
 */
export async function test_api_inventory_reservation_admin_filter_by_order(
  connection: api.IConnection,
) {
  // Step 1: Create admin account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Test filtering by specific order ID
  const targetOrderId = typia.random<string & tags.Format<"uuid">>();
  const filteredByOrder: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          shopping_mall_order_id: targetOrderId,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(filteredByOrder);

  // Step 3: Validate pagination structure
  TestValidator.equals(
    "current page should be 1",
    filteredByOrder.pagination.current,
    1,
  );
  TestValidator.predicate(
    "limit should not exceed 10",
    filteredByOrder.pagination.limit <= 10,
  );
  TestValidator.predicate(
    "data array length should not exceed limit",
    filteredByOrder.data.length <= filteredByOrder.pagination.limit,
  );

  // Step 4: Validate that all returned reservations match the order ID filter (if any results)
  for (const reservation of filteredByOrder.data) {
    typia.assert(reservation);
    if (
      reservation.shopping_mall_order_id !== null &&
      reservation.shopping_mall_order_id !== undefined
    ) {
      TestValidator.equals(
        "reservation order ID should match filter",
        reservation.shopping_mall_order_id,
        targetOrderId,
      );
    }
  }

  // Step 5: Test filtering for unconverted reservations (null order ID)
  const unconvertedReservations: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          shopping_mall_order_id: null,
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
    );
  typia.assert(unconvertedReservations);

  // Step 6: Validate unconverted reservations have null or undefined order_id
  for (const reservation of unconvertedReservations.data) {
    typia.assert(reservation);
    TestValidator.predicate(
      "unconverted reservation should have null/undefined order ID",
      reservation.shopping_mall_order_id === null ||
        reservation.shopping_mall_order_id === undefined,
    );
  }

  // Step 7: Test combined filtering - converted status reservations
  const convertedReservations: IPageIShoppingMallInventoryReservation =
    await api.functional.shoppingMall.admin.inventoryReservations.index(
      connection,
      {
        body: {
          page: 1,
          limit: 15,
          reservation_status: "converted",
        } satisfies IShoppingMallInventoryReservation.IRequest,
      },
