    await api.functional.shoppingMall.seller.sellers.reviews.index(connection, {
      sellerId: seller.id,
      body: {
        page: 1,
        limit: 20,
        sort_by: "created_at",
        sort_order: "asc",
      } satisfies IShoppingMallReview.IRequest,
    });
