  // 11. Test sorting by helpfulness descending
  const sortedHelpfulness =
    await api.functional.shoppingMall.seller.sellers.reviews.index(connection, {
      sellerId: seller.id,
      body: {
        page: 1,
        limit: 20,
        sort_by: "helpfulness",
        sort_order: "desc",
