import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test that child categories can be retrieved publicly without authentication
 * for a given parent category.
 *
 * This test validates the hierarchical category navigation functionality that
 * buyers use to browse the marketplace, ensuring category trees can be explored
 * without requiring authentication.
 *
 * Test workflow:
 *
 * 1. Admin creates a parent category in the shopping mall
 * 2. Admin creates multiple child categories under the parent category
 * 3. A public (unauthenticated) request retrieves the list of child categories
 * 4. Validates that all child categories are returned with proper pagination
 *    metadata
 * 5. Verifies child categories contain essential information (id, name, slug,
 *    status, display_order, timestamps)
 * 6. Confirms categories are properly ordered according to display_order
 */
export async function test_api_category_children_retrieval_public(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin to create test categories
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "AdminPassword123!",
        full_name: "Test Admin",
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: "https://test-admin.example.com/join",
        referrer: "https://test-admin.example.com",
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create parent category
  const parentCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: null,
        name: "Electronics",
        slug: "electronics",
        description: "Electronic devices and accessories",
        image_url: "https://example.com/images/electronics.jpg",
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Step 3: Create multiple child categories under the parent
  const childCategory1: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Smartphones",
        slug: "smartphones",
        description: "Mobile phones and smartphones",
        image_url: "https://example.com/images/smartphones.jpg",
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(childCategory1);

  const childCategory2: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Laptops",
        slug: "laptops",
        description: "Laptop computers and accessories",
        image_url: "https://example.com/images/laptops.jpg",
        display_order: 2,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(childCategory2);

  const childCategory3: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Tablets",
        slug: "tablets",
        description: "Tablet devices and accessories",
        image_url: "https://example.com/images/tablets.jpg",
        display_order: 3,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(childCategory3);

  // Step 4: Create unauthenticated connection for public access
  const unauthConnection: api.IConnection = { ...connection, headers: {} };

  // Step 5: Retrieve child categories publicly without authentication
  const childrenResult: IPageIShoppingMallCategory.ISummary =
    await api.functional.shoppingMall.categories.children.index(
      unauthConnection,
      {
        categoryId: parentCategory.id,
        body: {
          page: 1,
          limit: 10,
          sort_by: "display_order",
          sort_direction: "asc",
        } satisfies IShoppingMallCategory.IRequest,
      },
    );
  typia.assert(childrenResult);

  // Step 6: Validate pagination metadata
  TestValidator.equals(
    "pagination page should be 1",
    childrenResult.pagination.current,
    1,
  );
  TestValidator.equals(
    "pagination limit should be 10",
    childrenResult.pagination.limit,
    10,
  );
  TestValidator.equals(
    "total records should be 3",
    childrenResult.pagination.records,
    3,
  );
  TestValidator.equals(
    "total pages should be 1",
    childrenResult.pagination.pages,
    1,
  );

  // Step 7: Validate that all child categories are returned
  TestValidator.equals(
    "should return 3 child categories",
    childrenResult.data.length,
    3,
  );

  // Step 8: Validate child categories are properly ordered by display_order
  TestValidator.equals(
    "first category should be Smartphones",
    childrenResult.data[0].name,
    "Smartphones",
  );
  TestValidator.equals(
    "second category should be Laptops",
    childrenResult.data[1].name,
    "Laptops",
  );
  TestValidator.equals(
    "third category should be Tablets",
    childrenResult.data[2].name,
    "Tablets",
  );

  // Step 9: Validate parent_id relationship for all child categories
  for (const category of childrenResult.data) {
    TestValidator.equals(
      "category parent_id matches",
      category.parent_id,
      parentCategory.id,
    );
  }

  // Step 10: Validate categories are ordered by display_order ascending
  TestValidator.equals(
    "first category display_order",
    childrenResult.data[0].display_order,
    1,
  );
  TestValidator.equals(
    "second category display_order",
    childrenResult.data[1].display_order,
    2,
  );
  TestValidator.equals(
    "third category display_order",
    childrenResult.data[2].display_order,
    3,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test that child category retrieval supports filtering by category status
 * (active/inactive).
 *
 * This test validates the category status filtering functionality by:
 *
 * 1. Creating an admin account for authorization
 * 2. Creating a parent category to hold child categories
 * 3. Creating multiple child categories with different statuses (some active, some
 *    inactive)
 * 4. Testing status filter with "active" - verifies only active children are
 *    returned
 * 5. Testing status filter with "inactive" - verifies only inactive children are
 *    returned
 * 6. Testing without status filter - verifies all children are returned regardless
 *    of status
 * 7. Validating pagination and sorting work correctly with status filtering
 *    applied
 * 8. Ensuring filtered results accurately reflect the database state
 *
 * This ensures that category browsing interfaces can properly filter categories
 * based on visibility status, allowing admins to view all categories while
 * public interfaces show only active ones.
 */
export async function test_api_category_children_filtering_by_status(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: "AdminPass123!",
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create parent category
  const parentCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: null,
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Step 3: Create multiple child categories with different statuses
  const activeChildren = await ArrayUtil.asyncRepeat(3, async (index) => {
    return await api.functional.shoppingMall.admin.categories.create(
      connection,
      {
        body: {
          parent_id: parentCategory.id,
          name: `Active Child ${index + 1}`,
          slug: `active-child-${RandomGenerator.alphaNumeric(8)}`,
          description: RandomGenerator.paragraph({ sentences: 2 }),
          image_url: typia.random<string & tags.Format<"uri">>(),
          display_order: index + 1,
          status: "active",
        } satisfies IShoppingMallCategory.ICreate,
      },
    );
  });
  activeChildren.forEach((child) => typia.assert(child));

  const inactiveChildren = await ArrayUtil.asyncRepeat(2, async (index) => {
    return await api.functional.shoppingMall.admin.categories.create(
      connection,
      {
        body: {
          parent_id: parentCategory.id,
          name: `Inactive Child ${index + 1}`,
          slug: `inactive-child-${RandomGenerator.alphaNumeric(8)}`,
          description: RandomGenerator.paragraph({ sentences: 2 }),
          image_url: typia.random<string & tags.Format<"uri">>(),
          display_order: index + 10,
          status: "inactive",
        } satisfies IShoppingMallCategory.ICreate,
      },
    );
  });
  inactiveChildren.forEach((child) => typia.assert(child));

  // Step 4: Test filtering with status: "active"
  const activeFilteredResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 1,
        limit: 10,
        status: "active",
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(activeFilteredResult);

  TestValidator.equals(
    "active filter should return correct count",
    activeFilteredResult.data.length,
    3,
  );

  TestValidator.predicate(
    "all returned categories should have active status",
    activeFilteredResult.data.every((cat) => cat.status === "active"),
  );

  // Step 5: Test filtering with status: "inactive"
  const inactiveFilteredResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 1,
        limit: 10,
        status: "inactive",
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(inactiveFilteredResult);

  TestValidator.equals(
    "inactive filter should return correct count",
    inactiveFilteredResult.data.length,
    2,
  );

  TestValidator.predicate(
    "all returned categories should have inactive status",
    inactiveFilteredResult.data.every((cat) => cat.status === "inactive"),
  );

  // Step 6: Test without status filter (should return all children)
  const allChildrenResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(allChildrenResult);

  TestValidator.equals(
    "no filter should return all children",
    allChildrenResult.data.length,
    5,
  );

  // Step 7: Validate pagination works with status filtering
  const paginatedActiveResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 1,
        limit: 2,
        status: "active",
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(paginatedActiveResult);

  TestValidator.equals(
    "paginated active filter should respect limit",
    paginatedActiveResult.data.length,
    2,
  );

  TestValidator.equals(
    "pagination metadata should show correct total records",
    paginatedActiveResult.pagination.records,
    3,
  );

  // Step 8: Verify filtered results match expected data
  const activeIds = activeChildren.map((c) => c.id);
  const returnedActiveIds = activeFilteredResult.data.map((c) => c.id);

  TestValidator.predicate(
    "returned active IDs should match created active categories",
    returnedActiveIds.every((id) => activeIds.includes(id)),
  );

  const inactiveIds = inactiveChildren.map((c) => c.id);
  const returnedInactiveIds = inactiveFilteredResult.data.map((c) => c.id);

  TestValidator.predicate(
    "returned inactive IDs should match created inactive categories",
    returnedInactiveIds.every((id) => inactiveIds.includes(id)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test pagination functionality for retrieving child categories.
 *
 * This test validates that the child category pagination API properly
 * implements configurable page sizes and navigation through large category
 * hierarchies. It creates a parent category with 25 children, then tests
 * pagination with different page requests to ensure proper data segmentation
 * and metadata accuracy.
 *
 * Steps:
 *
 * 1. Admin authentication
 * 2. Create parent category
 * 3. Create 25 child categories
 * 4. Test first page (10 items)
 * 5. Verify pagination metadata
 * 6. Test second page navigation
 * 7. Test final page with remaining items
 * 8. Test edge case (beyond available pages)
 */
export async function test_api_category_children_pagination(
  connection: api.IConnection,
) {
  // Step 1: Admin authentication
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: RandomGenerator.pick([
        "super_admin",
        "moderator",
        "support",
      ] as const),
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create parent category
  const parentCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Step 3: Create 25 child categories
  const childCategories = await ArrayUtil.asyncRepeat(25, async (index) => {
    const child = await api.functional.shoppingMall.admin.categories.create(
      connection,
      {
        body: {
          parent_id: parentCategory.id,
          name: `${RandomGenerator.name(1)}_${index + 1}`,
          slug: `${RandomGenerator.alphaNumeric(6)}_${index + 1}`,
          description: RandomGenerator.paragraph({ sentences: 3 }),
          display_order: index + 1,
          status: "active",
        } satisfies IShoppingMallCategory.ICreate,
      },
    );
    typia.assert(child);
    return child;
  });

  // Step 4: Request first page with limit of 10
  const firstPage = await api.functional.shoppingMall.categories.children.index(
    connection,
    {
      categoryId: parentCategory.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(firstPage);

  // Step 5: Verify first page contains exactly 10 records
  TestValidator.equals("first page data count", firstPage.data.length, 10);

  // Step 6: Verify pagination metadata for first page
  TestValidator.equals("first page current", firstPage.pagination.current, 1);
  TestValidator.equals("first page limit", firstPage.pagination.limit, 10);
  TestValidator.equals(
    "first page total records",
    firstPage.pagination.records,
    25,
  );
  TestValidator.equals("first page total pages", firstPage.pagination.pages, 3);

  // Step 7: Request second page
  const secondPage =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 2,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(secondPage);

  // Step 8: Verify second page contains exactly 10 records
  TestValidator.equals("second page data count", secondPage.data.length, 10);

  // Step 9: Verify pagination metadata for second page
  TestValidator.equals("second page current", secondPage.pagination.current, 2);
  TestValidator.equals("second page limit", secondPage.pagination.limit, 10);
  TestValidator.equals(
    "second page total records",
    secondPage.pagination.records,
    25,
  );
  TestValidator.equals(
    "second page total pages",
    secondPage.pagination.pages,
    3,
  );

  // Step 10: Verify first and second pages return different categories
  const firstPageIds = firstPage.data.map((cat) => cat.id);
  const secondPageIds = secondPage.data.map((cat) => cat.id);
  const hasOverlap = firstPageIds.some((id) => secondPageIds.includes(id));
  TestValidator.predicate(
    "first and second pages have no overlap",
    !hasOverlap,
  );

  // Step 11: Request third/final page
  const thirdPage = await api.functional.shoppingMall.categories.children.index(
    connection,
    {
      categoryId: parentCategory.id,
      body: {
        page: 3,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    },
  );
  typia.assert(thirdPage);

  // Step 12: Verify final page contains remaining records (5 items)
  TestValidator.equals("third page data count", thirdPage.data.length, 5);

  // Step 13: Verify pagination metadata for final page
  TestValidator.equals("third page current", thirdPage.pagination.current, 3);
  TestValidator.equals("third page limit", thirdPage.pagination.limit, 10);
  TestValidator.equals(
    "third page total records",
    thirdPage.pagination.records,
    25,
  );
  TestValidator.equals("third page total pages", thirdPage.pagination.pages, 3);

  // Step 14: Test edge case - request page beyond available pages
  const beyondPage =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 10,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(beyondPage);

  // Step 15: Verify beyond page returns empty data
  TestValidator.equals("beyond page data count", beyondPage.data.length, 0);

  // Step 16: Verify pagination metadata for beyond page
  TestValidator.equals(
    "beyond page current",
    beyondPage.pagination.current,
    10,
  );
  TestValidator.equals(
    "beyond page total records",
    beyondPage.pagination.records,
    25,
  );
  TestValidator.equals(
    "beyond page total pages",
    beyondPage.pagination.pages,
    3,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test comprehensive sorting functionality for child category retrieval.
 *
 * This test validates that the child category retrieval endpoint supports
 * multiple sorting options including by name (alphabetical), creation date
 * (chronological), and display order (custom merchandising sequence). The test
 * ensures that both ascending and descending sort directions work correctly for
 * each field.
 *
 * Test Flow:
 *
 * 1. Admin authentication and setup
 * 2. Create parent category with multiple child categories having varied
 *    attributes
 * 3. Test name sorting (ascending and descending)
 * 4. Test created_at sorting (ascending and descending)
 * 5. Test display_order sorting (ascending and descending)
 * 6. Verify all sorting results match expected ordering
 */
export async function test_api_category_children_sorting(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create parent category
  const parentCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: "Parent Category",
        slug: `parent-${RandomGenerator.alphaNumeric(8)}`,
        description: "Parent category for sorting tests",
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Step 3: Create child categories with intentionally varied attributes
  const childCategories: IShoppingMallCategory[] = [];

  // Create child with name "Delta", display_order 100
  const child1: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Delta",
        slug: `delta-${RandomGenerator.alphaNumeric(8)}`,
        description: "Delta category",
        display_order: 100,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(child1);
  childCategories.push(child1);

  // Create child with name "Alpha", display_order 50
  const child2: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Alpha",
        slug: `alpha-${RandomGenerator.alphaNumeric(8)}`,
        description: "Alpha category",
        display_order: 50,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(child2);
  childCategories.push(child2);

  // Create child with name "Gamma", display_order 200
  const child3: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Gamma",
        slug: `gamma-${RandomGenerator.alphaNumeric(8)}`,
        description: "Gamma category",
        display_order: 200,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(child3);
  childCategories.push(child3);

  // Create child with name "Beta", display_order 25
  const child4: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Beta",
        slug: `beta-${RandomGenerator.alphaNumeric(8)}`,
        description: "Beta category",
        display_order: 25,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(child4);
  childCategories.push(child4);

  // Step 4: Test name sorting - ascending
  const nameSortAsc: IPageIShoppingMallCategory.ISummary =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        sort_by: "name",
        sort_direction: "asc",
        page: 1,
