import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test that retrieving children of a category that has no child categories
 * returns an empty result set with proper structure.
 *
 * This test validates the edge case where a leaf category (category with no
 * children) is queried for its children. It ensures that:
 *
 * 1. Admin creates a leaf category (category with no children)
 * 2. Request the children of this leaf category
 * 3. Verify the response returns an empty data array
 * 4. Verify pagination metadata correctly indicates zero records and zero pages
 * 5. Verify the response structure matches the expected schema even with no data
 * 6. The operation completes successfully without errors despite having no results
 *
 * This ensures proper handling of edge cases where categories exist but have no
 * subcategories, which is common for leaf nodes in the category hierarchy.
 */
export async function test_api_category_children_empty_result(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin to create test category
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: RandomGenerator.pick([
          "super_admin",
          "moderator",
          "support",
        ] as const),
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create a leaf category (category with no children)
  const leafCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        display_order: typia.random<number & tags.Type<"int32">>(),
        status: RandomGenerator.pick(["active", "inactive"] as const),
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(leafCategory);

  // Step 3: Request the children of this leaf category
  const childrenResponse: IPageIShoppingMallCategory.ISummary =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: leafCategory.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(childrenResponse);

  // Step 4: Verify the response returns an empty data array
  TestValidator.equals(
    "children data array should be empty",
    childrenResponse.data,
    [],
  );

  // Step 5: Verify pagination metadata correctly indicates zero records
  TestValidator.equals(
    "pagination records should be 0",
    childrenResponse.pagination.records,
    0,
  );

  // Step 6: Verify pagination metadata correctly indicates zero pages
  TestValidator.equals(
    "pagination pages should be 0",
    childrenResponse.pagination.pages,
    0,
  );

  // Step 7: Verify the current page is valid (should be 0 or 1 for empty results)
  TestValidator.predicate(
    "pagination current should be valid for empty results",
    childrenResponse.pagination.current === 0 ||
      childrenResponse.pagination.current === 1,
  );

  // Step 8: Verify the limit is as requested
  TestValidator.equals(
    "pagination limit should match request",
    childrenResponse.pagination.limit,
    10,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCategory";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test that child category retrieval supports text search filtering by category
 * name.
 *
 * This test validates the name-based search functionality for child categories
 * within a hierarchical category structure. It verifies that the search API
 * correctly filters categories based on name patterns, supports
 * case-insensitive matching, performs partial (substring) matching, and
 * properly handles no-match scenarios.
 *
 * Test Flow:
 *
 * 1. Authenticate as admin to gain category management privileges
 * 2. Create a parent category to establish hierarchical context
 * 3. Create multiple child categories with distinct, searchable names
 * 4. Test exact name match search
 * 5. Test partial name match (substring search)
 * 6. Test case-insensitive search
 * 7. Test no-match scenario (empty results)
 * 8. Validate pagination structure and response integrity
 */
export async function test_api_category_children_search_by_name(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create parent category
  const parentCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Step 3: Create child categories with distinct searchable names
  const electronicsChild =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Electronics Devices",
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(electronicsChild);

  const clothingChild =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Clothing Apparel",
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        display_order: 2,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(clothingChild);

  const electronicsAccessoriesChild =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Electronics Accessories",
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        display_order: 3,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(electronicsAccessoriesChild);

  // Step 4: Test exact name match search
  const exactMatchResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        search: "Electronics Devices",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(exactMatchResult);
  TestValidator.equals(
    "exact match should return exactly one category",
    exactMatchResult.data.length,
    1,
  );
  TestValidator.equals(
    "exact match should return the correct category",
    exactMatchResult.data[0].id,
    electronicsChild.id,
  );

  // Step 5: Test partial match (substring search)
  const partialMatchResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        search: "Electronics",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(partialMatchResult);
  TestValidator.equals(
    "partial match should return two categories containing 'Electronics'",
    partialMatchResult.data.length,
    2,
  );

  const foundElectronicsIds = partialMatchResult.data.map((c) => c.id).sort();
  const expectedElectronicsIds = [
    electronicsChild.id,
    electronicsAccessoriesChild.id,
  ].sort();
  TestValidator.equals(
    "partial match should return both Electronics categories",
    foundElectronicsIds,
    expectedElectronicsIds,
  );

  // Step 6: Test case-insensitive search
  const caseInsensitiveResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        search: "electronics",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(caseInsensitiveResult);
  TestValidator.equals(
    "case-insensitive search should return same results as case-sensitive",
    caseInsensitiveResult.data.length,
    2,
  );

  const foundCaseInsensitiveIds = caseInsensitiveResult.data
    .map((c) => c.id)
    .sort();
  TestValidator.equals(
    "case-insensitive search should return both Electronics categories",
    foundCaseInsensitiveIds,
    expectedElectronicsIds,
  );

  // Step 7: Test no-match scenario
  const noMatchResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        search: "NonExistentCategory",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(noMatchResult);
  TestValidator.equals(
    "search with no matches should return empty array",
    noMatchResult.data.length,
    0,
  );
  TestValidator.equals(
    "no-match search should have zero total records",
    noMatchResult.pagination.records,
    0,
  );

  // Step 8: Validate all children without search filter
  const allChildrenResult =
    await api.functional.shoppingMall.categories.children.index(connection, {
      categoryId: parentCategory.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCategory.IRequest,
    });
  typia.assert(allChildrenResult);
  TestValidator.equals(
    "without search filter should return all three children",
    allChildrenResult.data.length,
    3,
  );
  TestValidator.equals(
    "pagination should show correct total records",
    allChildrenResult.pagination.records,
    3,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test root-level category creation workflow in the shopping mall marketplace.
 *
 * This test validates the complete process of an administrator creating a new
 * root-level category without a parent, which serves as a top-level node in the
 * product taxonomy hierarchy. The test ensures:
 *
 * 1. Admin successfully authenticates and obtains authorization tokens
 * 2. Category is created with all required fields (name, slug, display_order,
 *    status)
 * 3. Optional fields (description, image_url) can be included
 * 4. System generates unique UUID identifier automatically
 * 5. Timestamps (created_at, updated_at) are set by the system
 * 6. Response returns complete category entity with all fields
 * 7. Category is immediately available with product_count initialized to 0
 *
 * This establishes the foundation categories for organizing the marketplace
 * product catalog.
 */
export async function test_api_category_creation_root_level(
  connection: api.IConnection,
) {
  // Step 1: Admin authentication - join the system to get authorization tokens
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = typia.random<string & tags.Format<"password">>();

  const adminData = {
    email: adminEmail,
    password: adminPassword,
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: "super_admin" as const,
    email_verified: true,
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallAdmin.ICreate;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminData,
    });
  typia.assert(admin);

  // Verify admin authentication was successful
  TestValidator.equals("admin email matches", admin.email, adminEmail);
  TestValidator.equals(
    "admin level is super_admin",
    admin.admin_level,
    "super_admin",
  );
  TestValidator.predicate(
    "admin has valid token",
    admin.token.access.length > 0,
  );

  // Step 2: Create a root-level category (no parent_id)
  const categoryName = RandomGenerator.name(2);
  const categorySlug = categoryName.toLowerCase().replace(/\s+/g, "-");

  const categoryData = {
    name: categoryName,
    slug: categorySlug,
    description: RandomGenerator.paragraph({
      sentences: 3,
      wordMin: 5,
      wordMax: 10,
    }),
    image_url: typia.random<string & tags.Format<"uri">>(),
    display_order: typia.random<number & tags.Type<"int32">>(),
    status: "active" as const,
  } satisfies IShoppingMallCategory.ICreate;

  const category: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: categoryData,
    });
  typia.assert(category);

  // Step 3: Validate the created category
  TestValidator.equals("category name matches", category.name, categoryName);
  TestValidator.equals("category slug matches", category.slug, categorySlug);
  TestValidator.equals("category status is active", category.status, "active");
  TestValidator.equals(
    "product count initialized to 0",
    category.product_count,
    0,
  );

  // Verify system-generated fields
  TestValidator.predicate(
    "category has valid UUID format",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      category.id,
    ),
  );
  TestValidator.predicate("created_at is set", category.created_at.length > 0);
  TestValidator.predicate("updated_at is set", category.updated_at.length > 0);

  // Verify root-level category (no parent)
  if (category.parent_id !== null && category.parent_id !== undefined) {
    throw new Error("Root-level category should not have a parent_id");
  }

  // Verify optional fields were saved correctly
  if (category.description !== null && category.description !== undefined) {
    TestValidator.equals(
      "description matches",
      category.description,
      categoryData.description,
    );
  }

  if (category.image_url !== null && category.image_url !== undefined) {
    TestValidator.equals(
      "image_url matches",
      category.image_url,
      categoryData.image_url,
    );
  }

  TestValidator.equals(
    "display_order matches",
    category.display_order,
    categoryData.display_order,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
