  // Step 4: Validate parent-child relationship is established correctly
  TestValidator.equals(
    "child category name matches",
    childCategory.name,
    childCategoryData.name,
  );
  TestValidator.equals(
    "child category slug matches",
    childCategory.slug,
    childCategoryData.slug,
  );
