import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallPlatformCommission } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPlatformCommission";

/**
 * Test combining multiple filter parameters for complex commission searches.
 *
 * This test validates the advanced search capability essential for
 * sophisticated financial analysis and multi-dimensional reporting. It tests
 * the ability to combine multiple filter criteria (seller_id, date range,
 * refund status, sorting) to perform complex administrative queries.
 *
 * Test workflow:
 *
 * 1. Authenticate as admin to access comprehensive commission search
 * 2. Perform basic search to establish baseline data
 * 3. Apply single filter (seller_id) and validate results
 * 4. Combine multiple filters (seller + date range) and validate cumulative effect
 * 5. Add refund status filter to existing filters and validate
 * 6. Test pagination with multiple filters applied
 * 7. Validate sorting maintains correct order within multi-filtered results
 *
 * Validation points:
 *
 * - All filter criteria are applied correctly and cumulatively (logical AND)
 * - Returned records match ALL specified filter conditions simultaneously
 * - Pagination functions correctly with multiple filters applied
 * - Total record counts accurately reflect the complex filtered subset
 * - Sorting maintains correct order within the multi-filtered result set
 */
export async function test_api_platform_commission_combined_filters(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: RandomGenerator.pick([
        "super_admin",
        "moderator",
        "support",
      ] as const),
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Perform basic search to get baseline data
  const baselineSearch =
    await api.functional.shoppingMall.admin.platformCommissions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallPlatformCommission.IRequest,
      },
    );
  typia.assert(baselineSearch);

  // Step 3: Test single filter - filter by seller_id if data exists
  if (baselineSearch.data.length > 0) {
    const targetSellerId = baselineSearch.data[0].shopping_mall_seller_id;

    const sellerFilterSearch =
      await api.functional.shoppingMall.admin.platformCommissions.index(
        connection,
        {
          body: {
            page: 1,
            limit: 20,
            seller_id: targetSellerId,
          } satisfies IShoppingMallPlatformCommission.IRequest,
        },
      );
    typia.assert(sellerFilterSearch);

    // Validate all results match the seller filter
    for (const commission of sellerFilterSearch.data) {
      TestValidator.equals(
        "seller filter - all results match seller_id",
        commission.shopping_mall_seller_id,
        targetSellerId,
      );
    }
  }

  // Step 4: Combine multiple filters - seller + date range
  if (baselineSearch.data.length > 0) {
    const targetSellerId = baselineSearch.data[0].shopping_mall_seller_id;
    const referenceDate = baselineSearch.data[0].created_at;
    const dateBefore = new Date(referenceDate);
    dateBefore.setDate(dateBefore.getDate() + 30);

    const combinedFilterSearch =
      await api.functional.shoppingMall.admin.platformCommissions.index(
        connection,
        {
          body: {
            page: 1,
            limit: 20,
            seller_id: targetSellerId,
            created_after: referenceDate,
            created_before: dateBefore.toISOString(),
          } satisfies IShoppingMallPlatformCommission.IRequest,
        },
      );
    typia.assert(combinedFilterSearch);

    // Validate all results match BOTH seller AND date filters
    for (const commission of combinedFilterSearch.data) {
      TestValidator.equals(
        "combined filter - seller_id matches",
        commission.shopping_mall_seller_id,
        targetSellerId,
      );

      const commissionDate = new Date(commission.created_at);
      const afterDate = new Date(referenceDate);

      TestValidator.predicate(
        "combined filter - created_at is after reference date",
        commissionDate >= afterDate,
      );

      TestValidator.predicate(
        "combined filter - created_at is before end date",
        commissionDate <= dateBefore,
      );
    }
  }

  // Step 5: Add refund status filter to existing filters
  if (baselineSearch.data.length > 0) {
    const refundedCommission = baselineSearch.data.find(
      (c) => c.is_refunded === true,
    );

    if (refundedCommission) {
      const tripleFilterSearch =
        await api.functional.shoppingMall.admin.platformCommissions.index(
          connection,
          {
            body: {
              page: 1,
              limit: 20,
              seller_id: refundedCommission.shopping_mall_seller_id,
              is_refunded: true,
            } satisfies IShoppingMallPlatformCommission.IRequest,
          },
        );
      typia.assert(tripleFilterSearch);

      // Validate all results match ALL three filters
      for (const commission of tripleFilterSearch.data) {
        TestValidator.equals(
          "triple filter - seller_id matches",
          commission.shopping_mall_seller_id,
          refundedCommission.shopping_mall_seller_id,
        );

        TestValidator.equals(
          "triple filter - is_refunded is true",
          commission.is_refunded,
          true,
        );
      }
    }
  }

  // Step 6: Test pagination with multiple filters
  const paginationSearch =
    await api.functional.shoppingMall.admin.platformCommissions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          sort_by: "created_at",
          sort_order: "desc",
        } satisfies IShoppingMallPlatformCommission.IRequest,
      },
    );
  typia.assert(paginationSearch);

  TestValidator.predicate(
    "pagination - limit is respected",
    paginationSearch.data.length <= 10,
  );

  // Step 7: Validate sorting with filters
  const sortedSearch =
    await api.functional.shoppingMall.admin.platformCommissions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 20,
          sort_by: "commission_amount",
          sort_order: "desc",
        } satisfies IShoppingMallPlatformCommission.IRequest,
      },
    );
  typia.assert(sortedSearch);

  // Verify descending order of commission amounts
  for (let i = 0; i < sortedSearch.data.length - 1; i++) {
    const current = sortedSearch.data[i].commission_amount;
    const next = sortedSearch.data[i + 1].commission_amount;

    TestValidator.predicate(
      "sorting - commission amounts in descending order",
      current >= next,
    );
  }

  // Step 8: Test complex multi-criteria query combining many filters
  const complexSearch =
    await api.functional.shoppingMall.admin.platformCommissions.index(
      connection,
      {
        body: {
          page: 1,
          limit: 50,
          is_refunded: false,
          min_commission_amount: 0,
          sort_by: "created_at",
          sort_order: "asc",
        } satisfies IShoppingMallPlatformCommission.IRequest,
      },
    );
  typia.assert(complexSearch);

  // Validate complex filter conditions
  for (const commission of complexSearch.data) {
    TestValidator.equals(
      "complex filter - is_refunded is false",
      commission.is_refunded,
      false,
    );

    TestValidator.predicate(
      "complex filter - commission_amount >= min threshold",
      commission.commission_amount >= 0,
    );
  }

  // Verify ascending order
  for (let i = 0; i < complexSearch.data.length - 1; i++) {
    const currentDate = new Date(complexSearch.data[i].created_at);
    const nextDate = new Date(complexSearch.data[i + 1].created_at);

    TestValidator.predicate(
      "complex filter - dates in ascending order",
      currentDate <= nextDate,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrder";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";

/**
 * Test the admin order search functionality with comprehensive filtering
 * capabilities.
 *
 * This test validates that administrators can successfully search and filter
 * orders using various criteria including order status, date ranges, amount
 * filters, payment status, search terms, and sorting options. The test ensures
 * proper pagination support and validates that filters can be applied
 * individually and in combination.
 *
 * Test Flow:
 *
 * 1. Create an admin account and authenticate
 * 2. Test basic pagination with default settings
 * 3. Test status filtering
 * 4. Test date range filtering
 * 5. Test amount range filtering
 * 6. Test payment status filtering
 * 7. Test search term functionality
 * 8. Test sorting options (ascending and descending)
 * 9. Test combined filters
 * 10. Validate response structure and pagination metadata
 */
export async function test_api_order_admin_search_with_filters(
  connection: api.IConnection,
) {
  // Step 1: Create admin account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "Admin@123!",
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Test basic pagination with empty filters (default behavior)
  const defaultPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {} satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(defaultPage);
  TestValidator.predicate(
    "pagination metadata exists",
    defaultPage.pagination !== null && defaultPage.pagination !== undefined,
  );
  TestValidator.predicate("data array exists", Array.isArray(defaultPage.data));
  TestValidator.predicate(
    "pagination current page is valid",
    defaultPage.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit is positive",
    defaultPage.pagination.limit > 0,
  );
  TestValidator.predicate(
    "pagination records is non-negative",
    defaultPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    defaultPage.pagination.pages >= 0,
  );

  // Step 3: Test status filter - filter by specific order status
  const statusFilterPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        status: "payment_confirmed",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(statusFilterPage);
  if (statusFilterPage.data.length > 0) {
    TestValidator.predicate(
      "all orders have payment_confirmed status",
      statusFilterPage.data.every(
        (order) => order.status === "payment_confirmed",
      ),
    );
  }

  // Step 4: Test date range filtering
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  const dateFilterPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        from_date: thirtyDaysAgo.toISOString(),
        to_date: now.toISOString(),
        page: 1,
        limit: 20,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(dateFilterPage);
  if (dateFilterPage.data.length > 0) {
    TestValidator.predicate(
      "all orders are within date range",
      dateFilterPage.data.every((order) => {
        const createdAt = new Date(order.created_at);
        return createdAt >= thirtyDaysAgo && createdAt <= now;
      }),
    );
  }

  // Step 5: Test amount range filtering
  const amountFilterPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        min_amount: 100,
        max_amount: 5000,
        page: 1,
        limit: 15,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(amountFilterPage);
  if (amountFilterPage.data.length > 0) {
    TestValidator.predicate(
      "all orders are within amount range",
      amountFilterPage.data.every(
        (order) => order.total_amount >= 100 && order.total_amount <= 5000,
      ),
    );
  }

  // Step 6: Test payment status filtering
  const paymentStatusPage =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: {
        payment_status: "completed",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(paymentStatusPage);

  // Step 7: Test search term functionality
  const searchPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        search: "ORD",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(searchPage);

  // Step 8: Test sorting - sort by created_at ascending
  const sortAscPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        sort_by: "created_at",
        sort_order: "asc",
        page: 1,
        limit: 20,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(sortAscPage);
  if (sortAscPage.data.length > 1) {
    TestValidator.predicate(
      "orders are sorted by created_at ascending",
      sortAscPage.data.every((order, index) => {
        if (index === 0) return true;
        return (
          new Date(sortAscPage.data[index - 1].created_at) <=
          new Date(order.created_at)
        );
      }),
    );
  }

  // Step 9: Test sorting - sort by total_amount descending
  const sortDescPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        sort_by: "total_amount",
        sort_order: "desc",
        page: 1,
        limit: 20,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(sortDescPage);
  if (sortDescPage.data.length > 1) {
    TestValidator.predicate(
      "orders are sorted by total_amount descending",
      sortDescPage.data.every((order, index) => {
        if (index === 0) return true;
        return sortDescPage.data[index - 1].total_amount >= order.total_amount;
      }),
    );
  }

  // Step 10: Test combined filters - multiple criteria at once
  const combinedFilterPage =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: {
        status: "delivered",
        min_amount: 50,
        max_amount: 10000,
        from_date: thirtyDaysAgo.toISOString(),
        to_date: now.toISOString(),
        payment_status: "completed",
        sort_by: "created_at",
        sort_order: "desc",
        page: 1,
        limit: 25,
      } satisfies IShoppingMallOrder.IRequest,
    });
  typia.assert(combinedFilterPage);
  if (combinedFilterPage.data.length > 0) {
    TestValidator.predicate(
      "combined filters: all orders match status criteria",
      combinedFilterPage.data.every((order) => order.status === "delivered"),
    );
    TestValidator.predicate(
      "combined filters: all orders match amount range",
      combinedFilterPage.data.every(
        (order) => order.total_amount >= 50 && order.total_amount <= 10000,
      ),
    );
    TestValidator.predicate(
      "combined filters: all orders match date range",
      combinedFilterPage.data.every((order) => {
        const createdAt = new Date(order.created_at);
        return createdAt >= thirtyDaysAgo && createdAt <= now;
      }),
    );
  }

  // Step 11: Validate response structure contains all required order summary fields
  if (defaultPage.data.length > 0) {
    const sampleOrder = defaultPage.data[0];
    TestValidator.predicate(
      "order has id field",
      sampleOrder.id !== null && sampleOrder.id !== undefined,
    );
    TestValidator.predicate(
      "order has order_number field",
      sampleOrder.order_number !== null &&
        sampleOrder.order_number !== undefined,
    );
    TestValidator.predicate(
      "order has status field",
      sampleOrder.status !== null && sampleOrder.status !== undefined,
    );
    TestValidator.predicate(
      "order has subtotal field",
      typeof sampleOrder.subtotal === "number",
    );
    TestValidator.predicate(
      "order has shipping_total field",
      typeof sampleOrder.shipping_total === "number",
    );
    TestValidator.predicate(
      "order has tax_total field",
      typeof sampleOrder.tax_total === "number",
    );
    TestValidator.predicate(
      "order has discount_total field",
      typeof sampleOrder.discount_total === "number",
    );
    TestValidator.predicate(
      "order has total_amount field",
      typeof sampleOrder.total_amount === "number",
    );
    TestValidator.predicate(
      "order has created_at field",
      sampleOrder.created_at !== null && sampleOrder.created_at !== undefined,
    );
    TestValidator.predicate(
      "order has updated_at field",
      sampleOrder.updated_at !== null && sampleOrder.updated_at !== undefined,
    );
  }

  // Step 12: Test pagination - retrieve multiple pages
  const page1 = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals(
    "page 1 current page number",
    page1.pagination.current,
    1,
  );

  if (page1.pagination.pages > 1) {
    const page2 = await api.functional.shoppingMall.admin.orders.index(
      connection,
      {
        body: {
          page: 2,
          limit: 5,
        } satisfies IShoppingMallOrder.IRequest,
      },
    );
    typia.assert(page2);
    TestValidator.equals(
      "page 2 current page number",
      page2.pagination.current,
      2,
    );
    TestValidator.predicate(
      "different pages return different data",
      page1.data.length === 0 ||
        page2.data.length === 0 ||
        page1.data[0].id !== page2.data[0].id,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrder";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import type { IShoppingMallBuyerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyerAddress";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallOrderSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderSeller";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import type { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import type { IShoppingMallSaleSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleSku";
import type { IShoppingMallSaleVariantAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantAttribute";
import type { IShoppingMallSaleVariantValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantValue";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates comprehensive pagination functionality of the admin order search
 * endpoint.
 *
 * This test ensures administrators can efficiently navigate through large order
 * datasets using pagination controls. It validates that pagination metadata is
 * accurate, page navigation works correctly, and edge cases are handled
 * appropriately.
 *
 * Test workflow:
 *
 * 1. Create admin account for authentication
 * 2. Create seller account and product infrastructure (category, sale, SKUs)
 * 3. Create buyer account and complete multiple purchase workflows to generate
 *    test orders
 * 4. Test pagination with various page sizes and page numbers
 * 5. Validate pagination metadata accuracy (current, limit, records, pages)
 * 6. Test edge cases including out-of-range pages and boundary conditions
 */
export async function test_api_order_admin_search_pagination(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for order search access
  const adminPassword = typia.random<string & tags.Format<"password">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: adminPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: "https://admin.test.com/join",
      referrer: "https://admin.test.com/home",
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create seller account for product listings
  const sellerPassword = typia.random<string & tags.MinLength<8>>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: sellerPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.name(2),
      business_description: RandomGenerator.paragraph(),
      store_name: RandomGenerator.name(1),
      href: "https://seller.test.com/join",
      referrer: "https://seller.test.com/home",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 3: Create category for product organization
  await api.functional.auth.admin.login(connection, {
    body: {
      email: admin.email,
      password: adminPassword,
      href: "https://admin.test.com/login",
      referrer: "https://admin.test.com/home",
    } satisfies IShoppingMallAdmin.ILogin,
  });

  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph(),
        display_order: typia.random<number & tags.Type<"int32">>(),
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 4: Switch to seller and create product sale
  await api.functional.auth.seller.login(connection, {
    body: {
      email: seller.email,
      password: sellerPassword,
      href: "https://seller.test.com/login",
      referrer: "https://seller.test.com/home",
    } satisfies IShoppingMallSeller.ILogin,
  });

  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        shopping_mall_category_id: category.id,
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        condition: RandomGenerator.pick([
          "new",
          "refurbished",
          "used",
        ] as const),
        return_policy_days: RandomGenerator.pick([0, 7, 14, 30, 60] as const),
        status: "published",
      } satisfies IShoppingMallSale.ICreate,
    },
  );
  typia.assert(sale);

  // Step 5: Create SKU for the product
  const sku = await api.functional.shoppingMall.seller.sales.skus.create(
    connection,
    {
      saleCode: sale.code,
      body: {
        sku_code: RandomGenerator.alphaNumeric(10),
        variant_combination: JSON.stringify({ Size: "M", Color: "Blue" }),
        base_price: typia.random<number & tags.Minimum<0>>(),
        enabled: true,
      } satisfies IShoppingMallSaleSku.ICreate,
    },
  );
  typia.assert(sku);

  // Step 6: Create multiple buyers and orders for pagination testing
  const orderIds: string[] = [];
  const buyerCount = 25; // Create enough orders for meaningful pagination

  for (let i = 0; i < buyerCount; i++) {
    // Create buyer account
    const buyer = await api.functional.auth.buyer.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.MinLength<8>>(),
        full_name: RandomGenerator.name(),
        href: "https://buyer.test.com/join",
        referrer: "https://buyer.test.com/home",
      } satisfies IShoppingMallBuyer.ICreate,
    });
    typia.assert(buyer);

    // Add product to cart
    const cartItem =
      await api.functional.shoppingMall.buyer.buyers.me.cart.items.create(
        connection,
        {
          body: {
            shopping_mall_sale_sku_id: sku.id,
            quantity: typia.random<
              number & tags.Type<"int32"> & tags.Minimum<1>
            >(),
          } satisfies IShoppingMallCartItem.ICreate,
        },
      );
    typia.assert(cartItem);

    // Create delivery address
    const address =
      await api.functional.shoppingMall.buyer.buyers.me.addresses.create(
        connection,
        {
          body: {
            recipient_name: RandomGenerator.name(),
            phone: RandomGenerator.mobile(),
            street_address_line1: RandomGenerator.paragraph({ sentences: 4 }),
            city: RandomGenerator.name(1),
            postal_code: RandomGenerator.alphaNumeric(5),
            country: "South Korea",
            address_label: RandomGenerator.pick([
              "Home",
              "Office",
              "Other",
            ] as const),
            address_type: RandomGenerator.pick([
              "residential",
              "commercial",
            ] as const),
          } satisfies IShoppingMallBuyerAddress.ICreate,
        },
      );
    typia.assert(address);

    // Create payment method
    const paymentMethod =
      await api.functional.shoppingMall.buyer.paymentMethods.create(
        connection,
        {
          body: {
            payment_type: "credit_card",
            provider: "Stripe",
            provider_token: RandomGenerator.alphaNumeric(32),
            card_brand: RandomGenerator.pick(["visa", "mastercard"] as const),
            last_four_digits: typia
              .random<
                number &
                  tags.Type<"int32"> &
                  tags.Minimum<1000> &
                  tags.Maximum<9999>
              >()
              .toString(),
            expiry_month: typia.random<
              number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
            >(),
            expiry_year: typia.random<
              number & tags.Type<"int32"> & tags.Minimum<2024>
            >(),
            billing_name: RandomGenerator.name(),
            is_default: true,
          } satisfies IShoppingMallPaymentMethod.ICreate,
        },
      );
    typia.assert(paymentMethod);

    // Create order
    const order = await api.functional.shoppingMall.buyer.orders.create(
      connection,
      {
        body: {
          cart_item_ids: [cartItem.id],
          buyer_address_id: address.id,
          payment_method_id: paymentMethod.id,
        } satisfies IShoppingMallOrder.ICreate,
      },
    );
    typia.assert(order);
    orderIds.push(order.id);
  }

  // Step 7: Switch to admin for order search testing
  await api.functional.auth.admin.login(connection, {
    body: {
      email: admin.email,
      password: adminPassword,
      href: "https://admin.test.com/login",
      referrer: "https://admin.test.com/dashboard",
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // Step 8: Test first page with limit of 10
  const firstPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(firstPage);

  TestValidator.equals(
    "first page current should be 1",
    firstPage.pagination.current,
    1,
  );
  TestValidator.equals(
    "first page limit should be 10",
    firstPage.pagination.limit,
    10,
  );
  TestValidator.predicate(
    "first page should have up to 10 records",
    firstPage.data.length <= 10 && firstPage.data.length > 0,
  );
  TestValidator.predicate(
    "total records should be at least buyerCount",
    firstPage.pagination.records >= buyerCount,
  );

  // Step 9: Test second page
  const secondPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: 2,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(secondPage);

  TestValidator.equals(
    "second page current should be 2",
    secondPage.pagination.current,
    2,
  );
  TestValidator.equals(
    "record count should remain consistent",
    secondPage.pagination.records,
    firstPage.pagination.records,
  );

  // Verify no duplicates between pages
  const firstPageIds = firstPage.data.map((order) => order.id);
  const secondPageIds = secondPage.data.map((order) => order.id);
  const hasDuplicates = firstPageIds.some((id) => secondPageIds.includes(id));
  TestValidator.predicate(
    "pages should not have duplicate orders",
    !hasDuplicates,
  );

  // Step 10: Test different page sizes
  const smallPageSize = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(smallPageSize);

  TestValidator.predicate(
    "small page should respect limit of 5",
    smallPageSize.data.length <= 5,
  );
  TestValidator.equals(
    "small page limit metadata should be 5",
    smallPageSize.pagination.limit,
    5,
  );

  // Step 11: Calculate and verify total pages
  const expectedPages = Math.ceil(
    firstPage.pagination.records / firstPage.pagination.limit,
  );
  TestValidator.equals(
    "pages calculation should be correct",
    firstPage.pagination.pages,
    expectedPages,
  );

  // Step 12: Test last page behavior
  const lastPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: firstPage.pagination.pages,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(lastPage);

  TestValidator.predicate(
    "last page may contain fewer records than limit",
    lastPage.data.length <= 10,
  );

  // Step 13: Test beyond last page (should return empty data)
  const beyondLastPage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: firstPage.pagination.pages + 5,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(beyondLastPage);

  TestValidator.equals(
    "beyond last page should return empty data",
    beyondLastPage.data.length,
    0,
  );

  // Step 14: Test large page size
  const largePage = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: 1,
        limit: 50,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(largePage);

  TestValidator.equals(
    "large page limit should be 50",
    largePage.pagination.limit,
    50,
  );
  TestValidator.predicate(
    "large page should contain more records than small pages",
    largePage.data.length >= smallPageSize.data.length,
  );

  // Step 15: Verify pagination consistency across requests
  const consistencyCheck = await api.functional.shoppingMall.admin.orders.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallOrder.IRequest,
    },
  );
  typia.assert(consistencyCheck);

  TestValidator.equals(
    "total records should remain consistent across requests",
    consistencyCheck.pagination.records,
    firstPage.pagination.records,
  );
  TestValidator.equals(
    "total pages should remain consistent",
    consistencyCheck.pagination.pages,
    firstPage.pagination.pages,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrder";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";

/**
 * Test admin order search endpoint role-based access control.
 *
 * This test validates that administrators have unrestricted access to search
 * and retrieve all orders across the platform with complete order information
 * including financial details, payment status, and buyer/seller data.
 *
 * Test Steps:
 *
 * 1. Create and authenticate admin user
 * 2. Search all orders without filters (verify unrestricted access)
 * 3. Validate response structure and pagination
 * 4. Verify complete order summary information is accessible
 * 5. Test filtering by buyer_id and seller_id
 * 6. Confirm all order statuses and financial data are visible
 */
export async function test_api_order_admin_search_role_based_access(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminData = {
    email: adminEmail,
    password: RandomGenerator.alphaNumeric(12),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile(),
    admin_level: "super_admin" as const,
    email_verified: true,
    href: `https://admin.example.com/join`,
    referrer: `https://admin.example.com/login`,
  } satisfies IShoppingMallAdmin.ICreate;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminData,
    });
  typia.assert(admin);

  // Verify admin authentication tokens are issued
  typia.assert(admin.token);
  TestValidator.equals("admin email matches", admin.email, adminEmail);
  TestValidator.equals(
    "admin level is super_admin",
    admin.admin_level,
    "super_admin",
  );

  // Step 2: Search all orders without filters - admin has unrestricted access
  const allOrdersRequest = {
    page: 1,
    limit: 20,
    sort_by: "created_at" as const,
    sort_order: "desc" as const,
  } satisfies IShoppingMallOrder.IRequest;

  const allOrdersResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: allOrdersRequest,
    });
  typia.assert(allOrdersResponse);

  // Step 3: Validate response structure and pagination metadata
  typia.assert(allOrdersResponse.pagination);
  TestValidator.predicate(
    "pagination current page is valid",
    allOrdersResponse.pagination.current >= 1,
  );
  TestValidator.predicate(
    "pagination limit matches request",
    allOrdersResponse.pagination.limit === 20,
  );
  TestValidator.predicate(
    "pagination records count is non-negative",
    allOrdersResponse.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages count is non-negative",
    allOrdersResponse.pagination.pages >= 0,
  );

  // Step 4: Validate order data array structure
  typia.assert(allOrdersResponse.data);
  TestValidator.predicate(
    "order data is an array",
    Array.isArray(allOrdersResponse.data),
  );

  // If there are orders in the system, validate complete order information access
  if (allOrdersResponse.data.length > 0) {
    const firstOrder = allOrdersResponse.data[0];
    typia.assert(firstOrder);

    // Verify financial information is accessible to admin - business logic validation
    TestValidator.predicate(
      "order subtotal is non-negative",
      firstOrder.subtotal >= 0,
    );
    TestValidator.predicate(
      "order total amount is non-negative",
      firstOrder.total_amount >= 0,
    );
  }

  // Step 5: Test filtering by order status
  const statusFilterRequest = {
    page: 1,
    limit: 10,
    status: "pending_payment" as const,
  } satisfies IShoppingMallOrder.IRequest;

  const statusFilteredResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: statusFilterRequest,
    });
  typia.assert(statusFilteredResponse);
  typia.assert(statusFilteredResponse.pagination);
  typia.assert(statusFilteredResponse.data);

  // Step 6: Test buyer_id filtering - critical scenario requirement
  const buyerIdFilterRequest = {
    page: 1,
    limit: 10,
    buyer_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IShoppingMallOrder.IRequest;

  const buyerFilteredResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: buyerIdFilterRequest,
    });
  typia.assert(buyerFilteredResponse);
  typia.assert(buyerFilteredResponse.pagination);
  typia.assert(buyerFilteredResponse.data);

  // Step 7: Test seller_id filtering - critical scenario requirement
  const sellerIdFilterRequest = {
    page: 1,
    limit: 10,
    seller_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IShoppingMallOrder.IRequest;

  const sellerFilteredResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: sellerIdFilterRequest,
    });
  typia.assert(sellerFilteredResponse);
  typia.assert(sellerFilteredResponse.pagination);
  typia.assert(sellerFilteredResponse.data);

  // Step 8: Test date range filtering
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  const dateRangeRequest = {
    page: 1,
    limit: 15,
    from_date: thirtyDaysAgo.toISOString(),
    to_date: now.toISOString(),
  } satisfies IShoppingMallOrder.IRequest;

  const dateFilteredResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: dateRangeRequest,
    });
  typia.assert(dateFilteredResponse);
  typia.assert(dateFilteredResponse.pagination);
  typia.assert(dateFilteredResponse.data);

  // Step 9: Test amount range filtering
  const amountRangeRequest = {
    page: 1,
    limit: 10,
    min_amount: 0,
    max_amount: 1000000,
  } satisfies IShoppingMallOrder.IRequest;

  const amountFilteredResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: amountRangeRequest,
    });
  typia.assert(amountFilteredResponse);
  typia.assert(amountFilteredResponse.pagination);
  typia.assert(amountFilteredResponse.data);

  // Step 10: Test search functionality
  const searchRequest = {
    page: 1,
    limit: 10,
    search: RandomGenerator.alphaNumeric(5),
  } satisfies IShoppingMallOrder.IRequest;

  const searchResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: searchRequest,
    });
  typia.assert(searchResponse);
  typia.assert(searchResponse.pagination);
  typia.assert(searchResponse.data);

  // Step 11: Test payment status filtering
  const paymentStatusRequest = {
    page: 1,
    limit: 10,
    payment_status: "completed" as const,
  } satisfies IShoppingMallOrder.IRequest;

  const paymentStatusResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: paymentStatusRequest,
    });
  typia.assert(paymentStatusResponse);
  typia.assert(paymentStatusResponse.pagination);
  typia.assert(paymentStatusResponse.data);

  // Step 12: Test combined filters including buyer_id and seller_id
  const combinedFilterRequest = {
    page: 1,
    limit: 25,
    sort_by: "total_amount" as const,
    sort_order: "desc" as const,
    status: "payment_confirmed" as const,
    payment_status: "completed" as const,
    min_amount: 100,
    buyer_id: typia.random<string & tags.Format<"uuid">>(),
    seller_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IShoppingMallOrder.IRequest;

  const combinedFilterResponse: IPageIShoppingMallOrder.ISummary =
    await api.functional.shoppingMall.admin.orders.index(connection, {
      body: combinedFilterRequest,
    });
  typia.assert(combinedFilterResponse);
  typia.assert(combinedFilterResponse.pagination);
  typia.assert(combinedFilterResponse.data);

  // Validate that admin successfully accessed order search with all filter types
  TestValidator.predicate(
    "admin successfully searched orders with comprehensive filters",
    allOrdersResponse.pagination.pages >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import type { IShoppingMallBuyerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyerAddress";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallOrderSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderSeller";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import type { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import type { IShoppingMallSaleSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleSku";
import type { IShoppingMallSaleVariantAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantAttribute";
import type { IShoppingMallSaleVariantValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantValue";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test comprehensive buyer order retrieval functionality in a multi-actor
 * shopping mall scenario.
 *
 * This test validates the complete workflow from product listing creation
 * through order placement to order retrieval, ensuring buyers can access
 * complete order details including all nested relationships and calculated
 * fields.
 *
 * Workflow:
 *
 * 1. Admin creates product category for marketplace organization
 * 2. Seller registers and creates product sale listing with SKU variant
 * 3. Buyer registers and adds product to shopping cart
 * 4. Buyer creates delivery address and payment method
 * 5. Buyer completes checkout to create order
 * 6. Buyer retrieves order details and validates completeness
 */
export async function test_api_order_buyer_retrieval_complete_details(
  connection: api.IConnection,
) {
  // Step 1: Admin creates product category
  await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin",
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });

  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        display_order: typia.random<number & tags.Type<"int32">>(),
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 2: Seller registration and product creation
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: typia.random<string & tags.MinLength<8>>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.name(3),
      business_description: RandomGenerator.paragraph({ sentences: 10 }),
      store_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });

  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(12),
        shopping_mall_category_id: category.id,
        title: RandomGenerator.paragraph({ sentences: 4 }),
        description: RandomGenerator.content({ paragraphs: 3 }),
        condition: "new",
        return_policy_days: 14,
        status: "published",
      } satisfies IShoppingMallSale.ICreate,
    },
  );
  typia.assert(sale);

  const sku = await api.functional.shoppingMall.seller.sales.skus.create(
    connection,
    {
      saleCode: sale.code,
      body: {
        sku_code: RandomGenerator.alphaNumeric(8),
        variant_combination: JSON.stringify({ Color: "Black", Size: "Medium" }),
        base_price: typia.random<
          number & tags.Minimum<0>
        >() satisfies number as number,
        enabled: true,
      } satisfies IShoppingMallSaleSku.ICreate,
    },
  );
  typia.assert(sku);

  // Step 3: Buyer registration and cart operations
  const buyerEmail = typia.random<string & tags.Format<"email">>();
  const buyerPassword = typia.random<string & tags.MinLength<8>>();
  await api.functional.auth.buyer.join(connection, {
    body: {
      email: buyerEmail,
      password: buyerPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ICreate,
  });

  const cartItem =
    await api.functional.shoppingMall.buyer.buyers.me.cart.items.create(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: sku.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  // Step 4: Create delivery address and payment method
  const deliveryAddress =
    await api.functional.shoppingMall.buyer.buyers.me.addresses.create(
      connection,
      {
        body: {
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          street_address_line1: RandomGenerator.paragraph({ sentences: 3 }),
          city: RandomGenerator.name(1),
          state: RandomGenerator.name(1),
          postal_code: RandomGenerator.alphaNumeric(6),
          country: "South Korea",
          address_label: "Home",
          address_type: "residential",
          is_default: true,
        } satisfies IShoppingMallBuyerAddress.ICreate,
      },
    );
  typia.assert(deliveryAddress);

  const paymentMethod =
    await api.functional.shoppingMall.buyer.paymentMethods.create(connection, {
      body: {
        payment_type: "credit_card",
        provider: "Stripe",
        provider_token: RandomGenerator.alphaNumeric(32),
        card_brand: "visa",
        last_four_digits: RandomGenerator.alphaNumeric(4),
        expiry_month: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
        >() satisfies number as number,
        expiry_year: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<2024>
        >() satisfies number as number,
        billing_name: RandomGenerator.name(),
        billing_postal_code: RandomGenerator.alphaNumeric(5),
        is_default: true,
      } satisfies IShoppingMallPaymentMethod.ICreate,
    });
  typia.assert(paymentMethod);

  // Step 5: Create order from cart
  const createdOrder = await api.functional.shoppingMall.buyer.orders.create(
    connection,
    {
      body: {
        cart_item_ids: [cartItem.id],
        buyer_address_id: deliveryAddress.id,
        payment_method_id: paymentMethod.id,
        notes: RandomGenerator.paragraph({ sentences: 2 }),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(createdOrder);

  // Step 6: Retrieve order details and validate completeness
  const retrievedOrder = await api.functional.shoppingMall.buyer.orders.at(
    connection,
    {
      orderId: createdOrder.id,
    },
  );
  typia.assert(retrievedOrder);

  // Validate order basic information
  TestValidator.equals(
    "retrieved order ID matches created order",
    retrievedOrder.id,
    createdOrder.id,
  );
  TestValidator.equals(
    "order number is set",
    retrievedOrder.order_number,
    createdOrder.order_number,
  );
  TestValidator.predicate(
    "order status is valid",
    retrievedOrder.status.length > 0,
  );

  // Validate buyer information
  TestValidator.equals(
    "buyer ID matches",
    retrievedOrder.shopping_mall_buyer_id,
    createdOrder.shopping_mall_buyer_id,
  );
  TestValidator.predicate(
    "buyer summary is included",
    retrievedOrder.buyer !== null && retrievedOrder.buyer !== undefined,
  );
  if (retrievedOrder.buyer) {
    TestValidator.equals(
      "buyer email matches",
      retrievedOrder.buyer.email,
      buyerEmail,
    );
  }

  // Validate delivery address
  TestValidator.equals(
    "delivery address ID matches",
    retrievedOrder.shopping_mall_buyer_address_id,
    deliveryAddress.id,
  );
  TestValidator.predicate(
    "delivery address summary is included",
    retrievedOrder.deliveryAddress !== null &&
      retrievedOrder.deliveryAddress !== undefined,
  );
  if (retrievedOrder.deliveryAddress) {
    TestValidator.equals(
      "delivery address recipient matches",
      retrievedOrder.deliveryAddress.recipient_name,
      deliveryAddress.recipient_name,
    );
    TestValidator.equals(
      "delivery address city matches",
      retrievedOrder.deliveryAddress.city,
      deliveryAddress.city,
    );
  }

  // Validate order totals
  TestValidator.predicate(
    "subtotal is non-negative",
    retrievedOrder.subtotal >= 0,
  );
  TestValidator.predicate(
    "shipping total is non-negative",
    retrievedOrder.shipping_total >= 0,
  );
  TestValidator.predicate(
    "tax total is non-negative",
    retrievedOrder.tax_total >= 0,
  );
  TestValidator.predicate(
    "discount total is non-negative",
    retrievedOrder.discount_total >= 0,
  );
  TestValidator.predicate(
    "total amount is non-negative",
    retrievedOrder.total_amount >= 0,
  );

  // Validate order items array
  TestValidator.predicate(
    "order items array exists",
    Array.isArray(retrievedOrder.items),
  );
  TestValidator.predicate(
    "order has at least one item",
    retrievedOrder.items.length > 0,
  );

  // Validate first order item details
  const firstItem = retrievedOrder.items[0];
  typia.assertGuard(firstItem!);
  TestValidator.predicate(
    "order item has product name",
    firstItem.product_name.length > 0,
  );
  TestValidator.predicate(
    "order item has SKU code",
    firstItem.sku_code.length > 0,
  );
  TestValidator.predicate(
    "order item has unit price",
    firstItem.unit_price >= 0,
  );
  TestValidator.predicate("order item has quantity", firstItem.quantity > 0);
  TestValidator.predicate(
    "order item has line total",
    firstItem.line_total >= 0,
  );

  // Validate sellers array
  TestValidator.predicate(
    "sellers array exists",
    Array.isArray(retrievedOrder.sellers),
  );
  TestValidator.predicate(
    "order has at least one seller segment",
    retrievedOrder.sellers.length > 0,
  );

  // Validate first seller segment
  const firstSeller = retrievedOrder.sellers[0];
  typia.assertGuard(firstSeller!);
  TestValidator.predicate(
    "seller segment has sub-order number",
    firstSeller.sub_order_number.length > 0,
  );
  TestValidator.predicate(
    "seller segment has status",
    firstSeller.status.length > 0,
  );
  TestValidator.predicate(
    "seller segment has subtotal",
    firstSeller.subtotal >= 0,
  );
  TestValidator.predicate(
    "seller segment has shipping cost",
    firstSeller.shipping_cost >= 0,
  );

  // Validate timestamps
  TestValidator.predicate(
    "created_at timestamp exists",
    retrievedOrder.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at timestamp exists",
    retrievedOrder.updated_at.length > 0,
  );

  // Validate that retrieved order matches created order in all critical aspects
  TestValidator.equals(
    "retrieved order matches created order",
    retrievedOrder.id,
    createdOrder.id,
  );
  TestValidator.equals(
    "order totals match",
    retrievedOrder.total_amount,
    createdOrder.total_amount,
  );
  TestValidator.equals(
    "order status matches",
    retrievedOrder.status,
    createdOrder.status,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import type { IShoppingMallBuyerAddress } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyerAddress";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallOrderSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderSeller";
import type { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import type { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import type { IShoppingMallSaleSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleSku";
import type { IShoppingMallSaleVariantAttribute } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantAttribute";
import type { IShoppingMallSaleVariantValue } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleVariantValue";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates order retrieval authorization rules ensuring buyers can only access
 * their own orders.
 *
 * This test verifies that the order retrieval endpoint properly enforces
 * authorization boundaries, preventing buyers from accessing orders that belong
 * to other buyers. The test creates two separate buyer accounts, establishes a
 * complete order for Buyer A, and then validates that Buyer B cannot access
 * Buyer A's order while Buyer A can successfully retrieve their own order.
 *
 * Test workflow:
 *
 * 1. Register Buyer A and Buyer B accounts with stored passwords
 * 2. Setup product catalog (admin creates category, seller creates product and
 *    SKU)
 * 3. Buyer A completes full checkout flow (cart → address → payment → order)
 * 4. Buyer A successfully retrieves their own order (positive authorization test)
 * 5. Buyer B attempts to access Buyer A's order and is denied (negative
 *    authorization test)
 * 6. Test with non-existent order ID
 */
export async function test_api_order_buyer_retrieval_authorization(
  connection: api.IConnection,
) {
  // 1. Register Buyer A with stored password
  const buyerAEmail = typia.random<string & tags.Format<"email">>();
  const buyerAPassword = typia.random<string & tags.MinLength<8>>();
  const buyerA = await api.functional.auth.buyer.join(connection, {
    body: {
      email: buyerAEmail,
      password: buyerAPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ICreate,
  });
  typia.assert(buyerA);

  // 2. Register Buyer B with stored password (for cross-buyer authorization testing)
  const buyerBEmail = typia.random<string & tags.Format<"email">>();
  const buyerBPassword = typia.random<string & tags.MinLength<8>>();
  const buyerB = await api.functional.auth.buyer.join(connection, {
    body: {
      email: buyerBEmail,
      password: buyerBPassword,
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ICreate,
  });
  typia.assert(buyerB);

  // 3. Admin setup - Create category
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      admin_level: "super_admin" as const,
      email_verified: true,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallAdmin.ICreate,
  });
  typia.assert(admin);

  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(2),
        slug: RandomGenerator.alphaNumeric(10),
        description: RandomGenerator.paragraph(),
        display_order: typia.random<number & tags.Type<"int32">>(),
        status: "active" as const,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // 4. Seller setup - Create sale and SKU
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.MinLength<8>>(),
      full_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_name: RandomGenerator.name(3),
      business_description: RandomGenerator.paragraph(),
      store_name: RandomGenerator.name(2),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  const sale = await api.functional.shoppingMall.seller.sales.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(10),
        shopping_mall_category_id: category.id,
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        condition: "new" as const,
        return_policy_days: 30 as const,
      } satisfies IShoppingMallSale.ICreate,
    },
  );
  typia.assert(sale);

  const sku = await api.functional.shoppingMall.seller.sales.skus.create(
    connection,
    {
      saleCode: sale.code,
      body: {
        sku_code: RandomGenerator.alphaNumeric(12),
        variant_combination: JSON.stringify({ Color: "Red", Size: "M" }),
        base_price: typia.random<number & tags.Minimum<0>>(),
        enabled: true,
      } satisfies IShoppingMallSaleSku.ICreate,
    },
  );
  typia.assert(sku);

  // 5. Switch to Buyer A - Complete checkout flow
  await api.functional.auth.buyer.login(connection, {
    body: {
      email: buyerAEmail,
      password: buyerAPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ILogin,
  });

  // 6. Add product to Buyer A's cart
  const cartItem =
    await api.functional.shoppingMall.buyer.buyers.me.cart.items.create(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: sku.id,
          quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1>
          >(),
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  // 7. Create delivery address for Buyer A
  const address =
    await api.functional.shoppingMall.buyer.buyers.me.addresses.create(
      connection,
      {
        body: {
          recipient_name: RandomGenerator.name(),
          phone: RandomGenerator.mobile(),
          street_address_line1: RandomGenerator.paragraph({ sentences: 4 }),
          city: RandomGenerator.name(1),
          postal_code: typia
            .random<
              number &
                tags.Type<"int32"> &
                tags.Minimum<10000> &
                tags.Maximum<99999>
            >()
            .toString(),
          country: "United States",
          address_label: "Home",
          address_type: "residential",
          is_default: true,
        } satisfies IShoppingMallBuyerAddress.ICreate,
      },
    );
  typia.assert(address);

  // 8. Register payment method for Buyer A
  const paymentMethod =
    await api.functional.shoppingMall.buyer.paymentMethods.create(connection, {
      body: {
        payment_type: "credit_card",
        provider: "Stripe",
        provider_token: RandomGenerator.alphaNumeric(32),
        card_brand: "visa",
        last_four_digits: typia
          .random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<1000> &
              tags.Maximum<9999>
          >()
          .toString(),
        expiry_month: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
        >(),
        expiry_year: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<2024>
        >(),
        billing_name: RandomGenerator.name(),
        billing_postal_code: typia
          .random<
            number &
              tags.Type<"int32"> &
              tags.Minimum<10000> &
              tags.Maximum<99999>
          >()
          .toString(),
        is_default: true,
      } satisfies IShoppingMallPaymentMethod.ICreate,
    });
  typia.assert(paymentMethod);

  // 9. Create order for Buyer A
  const orderBuyerA = await api.functional.shoppingMall.buyer.orders.create(
    connection,
    {
      body: {
        cart_item_ids: [cartItem.id],
        buyer_address_id: address.id,
        payment_method_id: paymentMethod.id,
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(orderBuyerA);

  // 10. POSITIVE TEST: Buyer A retrieves their own order successfully
  const retrievedOrderByOwner =
    await api.functional.shoppingMall.buyer.orders.at(connection, {
      orderId: orderBuyerA.id,
    });
  typia.assert(retrievedOrderByOwner);
  TestValidator.equals(
    "buyer A can retrieve their own order ID",
    retrievedOrderByOwner.id,
    orderBuyerA.id,
  );
  TestValidator.equals(
    "order number matches",
    retrievedOrderByOwner.order_number,
    orderBuyerA.order_number,
  );
  TestValidator.equals(
    "buyer ID matches",
    retrievedOrderByOwner.shopping_mall_buyer_id,
    buyerA.id,
  );

  // 11. NEGATIVE TEST: Switch to Buyer B and attempt to access Buyer A's order
  await api.functional.auth.buyer.login(connection, {
    body: {
      email: buyerBEmail,
      password: buyerBPassword,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallBuyer.ILogin,
  });

  // Buyer B should NOT be able to access Buyer A's order - authorization denied
  await TestValidator.error(
    "buyer B cannot access buyer A's order due to authorization",
    async () => {
      await api.functional.shoppingMall.buyer.orders.at(connection, {
        orderId: orderBuyerA.id,
      });
    },
  );

  // 12. Test with non-existent order ID (still as Buyer B)
  const nonExistentOrderId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("non-existent order ID returns error", async () => {
    await api.functional.shoppingMall.buyer.orders.at(connection, {
      orderId: nonExistentOrderId,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
