      body: {
        code: `MOUSE-${RandomGenerator.alphaNumeric(8)}`,
        shopping_mall_category_id: categoryAccessories.id,
        title: "Wireless Gaming Mouse",
        description: RandomGenerator.content({ paragraphs: 2 }),
        condition: "new",
        return_policy_days: 14,
