  const wishlistItem1: IShoppingMallWishlistItem =
    await api.functional.shoppingMall.buyer.buyers.me.wishlist.items.create(
      connection,
      {
        body: {
          shopping_mall_sale_sku_id: skuLaptop.id,
        } satisfies IShoppingMallWishlistItem.ICreate,
      },
