  TestValidator.equals(
    "initial address country",
    createdAddress.country,
    "United States",
  );
  TestValidator.equals("initial address state", createdAddress.state, "NY");
  TestValidator.equals(
    "initial address postal code",
    createdAddress.postal_code,
    "10001",
  );

