  const sku2 = await api.functional.shoppingMall.seller.sales.skus.create(
    connection,
    {
      saleCode: sale.code,
      body: {
        sku_code: `${saleCode}-SKU2`,
        variant_combination: JSON.stringify({ Color: "Blue", Size: "Medium" }),
        base_price: 24.99,
        enabled: true,
