import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test the creation of root-level product categories in the marketplace
 * taxonomy.
 *
 * This test validates that administrators can create top-level categories
 * without parent relationships, which form the foundation of the product
 * classification hierarchy in the shopping mall.
 *
 * Test workflow:
 *
 * 1. Admin authenticates via join endpoint to obtain admin privileges
 * 2. Admin creates a root-level category with parent_id set to null
 * 3. Validate all category properties are correctly initialized
 * 4. Verify system-managed fields (id, timestamps, product_count) are properly set
 * 5. Confirm category is created as root-level (parent_id is null)
 */
export async function test_api_category_creation_root_level(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as admin to gain category management privileges
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: RandomGenerator.pick([
          "super_admin",
          "moderator",
          "support",
        ] as const),
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Prepare root-level category creation data
  const categoryName = RandomGenerator.paragraph({
    sentences: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<1> & tags.Maximum<3>
    >(),
    wordMin: 2,
    wordMax: 10,
  });

  const categorySlug = RandomGenerator.alphaNumeric(
    typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<10> & tags.Maximum<20>
    >(),
  );

  const categoryData = {
    parent_id: null,
    name: categoryName,
    slug: categorySlug,
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
    image_url: typia.random<string & tags.Format<"uri">>(),
    display_order: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<999>
    >(),
    status: RandomGenerator.pick(["active", "inactive"] as const),
  } satisfies IShoppingMallCategory.ICreate;

  // Step 3: Create the root-level category
  const createdCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: categoryData,
    });
  typia.assert(createdCategory);

  // Step 4: Validate category properties
  TestValidator.equals(
    "category name matches input",
    createdCategory.name,
    categoryData.name,
  );
  TestValidator.equals(
    "category slug matches input",
    createdCategory.slug,
    categoryData.slug,
  );
  TestValidator.equals(
    "parent_id is null for root-level category",
    createdCategory.parent_id,
    null,
  );
  TestValidator.equals(
    "display_order matches input",
    createdCategory.display_order,
    categoryData.display_order,
  );
  TestValidator.equals(
    "status matches input",
    createdCategory.status,
    categoryData.status,
  );
  TestValidator.equals(
    "product_count initialized to 0",
    createdCategory.product_count,
    0,
  );

  // Step 5: Verify system-managed fields are properly set
  TestValidator.predicate(
    "category ID is valid UUID",
    typia.is<string & tags.Format<"uuid">>(createdCategory.id),
  );

  TestValidator.predicate(
    "created_at is valid ISO 8601 timestamp",
    typia.is<string & tags.Format<"date-time">>(createdCategory.created_at),
  );

  TestValidator.predicate(
    "updated_at is valid ISO 8601 timestamp",
    typia.is<string & tags.Format<"date-time">>(createdCategory.updated_at),
  );

  // Step 6: Verify optional fields match input
  TestValidator.equals(
    "description matches input",
    createdCategory.description,
    categoryData.description,
  );
  TestValidator.equals(
    "image_url matches input",
    createdCategory.image_url,
    categoryData.image_url,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

/**
 * Test the creation of nested subcategories within an existing category
 * hierarchy.
 *
 * This test validates that administrators can build multi-level category trees
 * with unlimited nesting depth, ensuring proper parent-child relationships are
 * established at each level.
 *
 * Workflow steps:
 *
 * 1. Admin authenticates via join
 * 2. Admin creates parent category at root level
 * 3. Admin creates child category with parent_id referencing the root category
 * 4. Admin creates grandchild category with parent_id referencing the child
 *    category
 *
 * Validation points:
 *
 * - Verify parent category is created successfully as root-level category
 * - Confirm child category is created with valid parent_id reference
 * - Validate grandchild category establishes correct parent-child relationship
 * - Ensure hierarchical structure supports unlimited nesting depth
 */
export async function test_api_category_creation_nested_hierarchy(
  connection: api.IConnection,
) {
  // Step 1: Admin authenticates via join
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: typia.random<string & tags.Format<"password">>(),
        full_name: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        admin_level: "super_admin",
        email_verified: true,
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
      } satisfies IShoppingMallAdmin.ICreate,
    });
  typia.assert(admin);

  // Step 2: Admin creates parent category at root level
  const parentCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: "Electronics",
        slug: "electronics",
        description: "Electronic devices and accessories",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(parentCategory);

  // Validate parent category is created as root-level category
  TestValidator.equals(
    "parent category has no parent",
    parentCategory.parent_id,
    null,
  );
  TestValidator.equals(
    "parent category name",
    parentCategory.name,
    "Electronics",
  );
  TestValidator.equals(
    "parent category slug",
    parentCategory.slug,
    "electronics",
  );
  TestValidator.equals(
    "parent category status",
    parentCategory.status,
    "active",
  );

  // Step 3: Admin creates child category with parent_id referencing the root category
  const childCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: parentCategory.id,
        name: "Computers",
        slug: "computers",
        description: "Desktop and laptop computers",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(childCategory);

  // Validate child category has valid parent_id reference
  TestValidator.equals(
    "child category parent_id matches parent",
    childCategory.parent_id,
    parentCategory.id,
  );
  TestValidator.equals("child category name", childCategory.name, "Computers");
  TestValidator.equals("child category slug", childCategory.slug, "computers");
  TestValidator.equals("child category status", childCategory.status, "active");

  // Step 4: Admin creates grandchild category with parent_id referencing the child category
  const grandchildCategory: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        parent_id: childCategory.id,
        name: "Laptops",
        slug: "laptops",
        description: "Portable laptop computers",
        image_url: typia.random<string & tags.Format<"uri">>(),
        display_order: 1,
        status: "active",
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(grandchildCategory);

  // Validate grandchild category establishes correct parent-child relationship
  TestValidator.equals(
    "grandchild category parent_id matches child",
    grandchildCategory.parent_id,
    childCategory.id,
  );
  TestValidator.equals(
    "grandchild category name",
    grandchildCategory.name,
    "Laptops",
  );
  TestValidator.equals(
    "grandchild category slug",
    grandchildCategory.slug,
    "laptops",
  );
  TestValidator.equals(
    "grandchild category status",
    grandchildCategory.status,
    "active",
  );

  // Validate hierarchical structure integrity
  TestValidator.predicate(
    "parent is root level",
    parentCategory.parent_id === null,
  );
  TestValidator.predicate(
    "child has parent reference",
    childCategory.parent_id === parentCategory.id,
  );
  TestValidator.predicate(
    "grandchild has child reference",
    grandchildCategory.parent_id === childCategory.id,
  );

  // Verify unique slugs across all hierarchy levels
  const slugs = [
    parentCategory.slug,
    childCategory.slug,
    grandchildCategory.slug,
  ];
  TestValidator.equals("all slugs are unique", new Set(slugs).size, 3);

  // Validate all categories are active
  TestValidator.equals("parent is active", parentCategory.status, "active");
  TestValidator.equals("child is active", childCategory.status, "active");
  TestValidator.equals(
    "grandchild is active",
    grandchildCategory.status,
    "active",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSellerPayout } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerPayout";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerPayout } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerPayout";

/**
 * Test the seller payout list retrieval workflow where sellers query their
 * earnings settlement history.
 *
 * This test validates that sellers can successfully authenticate and access
 * their payout records through a paginated list endpoint with comprehensive
 * filtering and sorting capabilities.
 *
 * Workflow steps:
 *
 * 1. Seller authenticates via join to establish session
 * 2. Seller retrieves paginated payout list with various filters
 * 3. Validate pagination structure and metadata
 * 4. Test filtering by status, amount ranges, and date ranges
 * 5. Verify sorting functionality
 * 6. Confirm security measures for sensitive data
 */
export async function test_api_seller_payout_list_retrieval(
  connection: api.IConnection,
) {
  // Step 1: Seller authentication
  const sellerData = {
    email: typia.random<string & tags.Format<"email">>(),
    password: typia.random<string & tags.MinLength<8>>(),
    full_name: RandomGenerator.name(),
    phone_number: RandomGenerator.mobile("+82"),
    business_name: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 3,
      wordMax: 6,
    }),
    business_description: RandomGenerator.content({
      paragraphs: 1,
      sentenceMin: 5,
      sentenceMax: 8,
    }),
    store_name: RandomGenerator.paragraph({
      sentences: 2,
      wordMin: 2,
      wordMax: 4,
    }),
    href: typia.random<string & tags.Format<"uri">>(),
    referrer: typia.random<string & tags.Format<"uri">>(),
  } satisfies IShoppingMallSeller.ICreate;

  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: sellerData,
    });
  typia.assert(seller);

  // Step 2: Retrieve payout list with default pagination
  const defaultRequest = {
    page: 1,
    limit: 20,
  } satisfies IShoppingMallSellerPayout.IRequest;

  const payoutList: IPageIShoppingMallSellerPayout.ISummary =
    await api.functional.shoppingMall.seller.sellerPayouts.index(connection, {
      body: defaultRequest,
    });
  typia.assert(payoutList);

  // Step 3: Validate pagination metadata structure
  TestValidator.predicate(
    "pagination has current page",
    payoutList.pagination.current >= 1,
  );
  TestValidator.equals(
    "pagination limit matches request",
    payoutList.pagination.limit,
    defaultRequest.limit,
  );
  TestValidator.predicate(
    "pagination total records is non-negative",
    payoutList.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination total pages is non-negative",
    payoutList.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "payout data is an array",
    Array.isArray(payoutList.data),
  );

  // Step 4: Test filtering by status
  const statusValues = [
    "pending",
    "processing",
    "completed",
    "failed",
  ] as const;
  const testStatus = RandomGenerator.pick(statusValues);

  const statusFilterRequest = {
    page: 1,
    limit: 10,
    status: testStatus,
  } satisfies IShoppingMallSellerPayout.IRequest;

  const statusFilteredList: IPageIShoppingMallSellerPayout.ISummary =
    await api.functional.shoppingMall.seller.sellerPayouts.index(connection, {
      body: statusFilterRequest,
    });
  typia.assert(statusFilteredList);

  // Step 5: Test filtering by amount ranges
  const amountFilterRequest = {
    page: 1,
    limit: 10,
    min_amount: 100,
    max_amount: 10000,
  } satisfies IShoppingMallSellerPayout.IRequest;

  const amountFilteredList: IPageIShoppingMallSellerPayout.ISummary =
    await api.functional.shoppingMall.seller.sellerPayouts.index(connection, {
      body: amountFilterRequest,
    });
  typia.assert(amountFilteredList);

  // Step 6: Test filtering by date ranges
  const now = new Date();
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

  const dateFilterRequest = {
    page: 1,
    limit: 10,
    payout_date_from: thirtyDaysAgo.toISOString(),
