            status: sale.status as
              | "draft"
              | "pending_approval"
              | "published"
              | "suspended"
              | "archived",
            condition: sale.condition as "new" | "refurbished" | "used",
            brand: sale.brand === null ? undefined : sale.brand,
            short_description:
              sale.short_description === null
                ? undefined
