import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import { IPageIShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSellerSession";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminSellersSellerIdSessions(props: {
  admin: AdminPayload;
  sellerId: string & tags.Format<"uuid">;
  body: IShoppingMallSellerSession.IRequest;
}): Promise<IPageIShoppingMallSellerSession.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 100;
  const skip = (page - 1) * limit;

  const buildWhereCondition = () => {
    const conditions: Record<string, unknown> = {
      shopping_mall_seller_id: props.sellerId,
    };

    if (props.body.shopping_mall_seller_id) {
      conditions.shopping_mall_seller_id = props.body.shopping_mall_seller_id;
    }

    if (props.body.ip) {
      conditions.ip = props.body.ip;
    }

    if (props.body.href) {
      conditions.href = props.body.href;
    }

    if (props.body.referrer) {
      conditions.referrer = props.body.referrer;
    }

    if (props.body.search) {
      conditions.OR = [
        { ip: { contains: props.body.search, mode: "insensitive" } },
        { href: { contains: props.body.search, mode: "insensitive" } },
        { referrer: { contains: props.body.search, mode: "insensitive" } },
      ];
    }

    if (props.body.created_at_after || props.body.created_at_before) {
      const createdAtCondition: Record<string, unknown> = {};
      if (props.body.created_at_after) {
        createdAtCondition.gte = new Date(props.body.created_at_after);
      }
      if (props.body.created_at_before) {
        createdAtCondition.lte = new Date(props.body.created_at_before);
      }
      conditions.created_at = createdAtCondition;
    }

    if (props.body.expired_at_after || props.body.expired_at_before) {
      const expiredAtCondition: Record<string, unknown> = {};
      if (props.body.expired_at_after) {
        expiredAtCondition.gte = new Date(props.body.expired_at_after);
      }
      if (props.body.expired_at_before) {
        expiredAtCondition.lte = new Date(props.body.expired_at_before);
      }
      conditions.expired_at = expiredAtCondition;
    }

    return conditions;
  };

  const buildOrderBy = () => {
    if (!props.body.sort || props.body.sort.length === 0) {
      return undefined;
    }

    return props.body.sort.map((sortField) => {
      if (sortField.startsWith("-")) {
        const field = sortField.substring(1);
        return { [field]: "desc" };
      } else if (sortField.startsWith("+")) {
        const field = sortField.substring(1);
        return { [field]: "asc" };
      } else {
        return { [sortField]: "asc" };
      }
    });
  };

  const whereCondition = buildWhereCondition();
  const orderByCondition = buildOrderBy();

  const [sessions, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_seller_sessions.findMany({
      where: whereCondition,
      skip: skip,
      take: limit,
      orderBy: orderByCondition,
    }),
    MyGlobal.prisma.shopping_mall_seller_sessions.count({
      where: whereCondition,
    }),
  ]);

  const sellerIds = [
    ...new Set(sessions.map((s) => s.shopping_mall_seller_id)),
  ];
  const sellers = await MyGlobal.prisma.shopping_mall_sellers.findMany({
    where: {
      id: { in: sellerIds },
    },
  });

  const sellerMap = new Map(sellers.map((seller) => [seller.id, seller]));

  return {
    data: sessions.map((session) => {
      const seller = sellerMap.get(session.shopping_mall_seller_id);
      if (!seller) {
        throw new HttpException("Seller not found for session", 404);
      }
      return {
        id: session.id,
        seller: {
          id: seller.id,
          store_name: seller.store_name,
          email: seller.email,
          status: seller.status as
            | "pending"
            | "approved"
            | "rejected"
            | "suspended",
          email_verified: seller.email_verified,
        },
        ip: session.ip,
        href: session.href,
        referrer: session.referrer,
        created_at: toISOStringSafe(session.created_at),
        expired_at: session.expired_at
          ? toISOStringSafe(session.expired_at)
          : null,
      };
    }),
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallRevenueStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRevenueStatistics";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminStatisticsRevenue(props: {
  admin: AdminPayload;
  body: IShoppingMallRevenueStatistics.IRequest;
}): Promise<IShoppingMallRevenueStatistics> {
  const startDateTimeString = `${props.body.start_date}T00:00:00.000Z`;
  const endDateTimeString = `${props.body.end_date}T23:59:59.999Z`;

  let categoryOrderIds: string[] | undefined;
  if (props.body.category_id) {
    const salesInCategory = await MyGlobal.prisma.shopping_mall_sales.findMany({
      where: {
        shopping_mall_category_id: props.body.category_id,
      },
      select: { id: true },
    });
    const saleIds = salesInCategory.map((sale) => sale.id);
    const saleSkusInCategory =
      await MyGlobal.prisma.shopping_mall_sale_skus.findMany({
        where: {
          shopping_mall_sale_id: { in: saleIds },
        },
        select: { id: true },
      });
    const skuIds = saleSkusInCategory.map((sku) => sku.id);
    const orderItemsInCategory =
      await MyGlobal.prisma.shopping_mall_order_items.findMany({
        where: {
          shopping_mall_sale_sku_id: { in: skuIds },
        },
        select: { shopping_mall_order_id: true },
      });
    categoryOrderIds = [
      ...new Set(
        orderItemsInCategory.map((item) => item.shopping_mall_order_id),
      ),
    ];
  }

  const orders = await MyGlobal.prisma.shopping_mall_orders.findMany({
    where: {
      created_at: {
        gte: startDateTimeString,
        lte: endDateTimeString,
      },
      deleted_at: null,
      ...(props.body.seller_id && {
        shopping_mall_order_sellers: {
          some: {
            shopping_mall_seller_id: props.body.seller_id,
          },
        },
      }),
      ...(categoryOrderIds && {
        id: { in: categoryOrderIds },
      }),
    },
    select: {
      id: true,
      total_amount: true,
      created_at: true,
    },
  });

  const orderIds = orders.map((order) => order.id);

  const [paymentTransactions, commissions, payouts, refunds] =
    await Promise.all([
      MyGlobal.prisma.shopping_mall_payment_transactions.findMany({
        where: {
          shopping_mall_order_id: { in: orderIds },
        },
        select: {
          id: true,
        },
      }),
      MyGlobal.prisma.shopping_mall_platform_commissions.findMany({
        where: {
          shopping_mall_order_id: { in: orderIds },
        },
        select: {
          commission_amount: true,
        },
      }),
      MyGlobal.prisma.shopping_mall_seller_payouts.findMany({
        where: {
          created_at: {
            gte: startDateTimeString,
            lte: endDateTimeString,
          },
        },
        select: {
          net_payout_amount: true,
        },
      }),
      MyGlobal.prisma.shopping_mall_refund_transactions.findMany({
        where: {
          shopping_mall_order_id: { in: orderIds },
        },
        select: {
          refund_amount: true,
        },
      }),
    ]);

  const totalGrossRevenue = orders.reduce(
    (sum, order) => sum + Number(order.total_amount),
    0,
  );
  const totalRefundAmount = refunds.reduce(
    (sum, refund) => sum + Number(refund.refund_amount),
    0,
  );
  const totalNetRevenue = Math.max(0, totalGrossRevenue - totalRefundAmount);
  const totalPlatformCommission = commissions.reduce(
    (sum, commission) => sum + Number(commission.commission_amount),
    0,
  );
  const totalSellerPayouts = payouts.reduce(
    (sum, payout) => sum + Number(payout.net_payout_amount),
    0,
  );
  const totalOrderCount = orders.length;
  const totalTransactionCount = paymentTransactions.length;
  const averageOrderValue =
    totalOrderCount > 0 ? totalGrossRevenue / totalOrderCount : 0;

  const startDateMs = new Date(props.body.start_date).getTime();
  const endDateMs = new Date(props.body.end_date).getTime();
  const periodDurationMs = endDateMs - startDateMs;
  const previousPeriodStartMs = startDateMs - periodDurationMs - 86400000;
  const previousPeriodEndMs = startDateMs - 86400000;

  const previousPeriodStartString = new Date(previousPeriodStartMs)
    .toISOString()
    .split("T")[0];
  const previousPeriodEndString = new Date(previousPeriodEndMs)
    .toISOString()
    .split("T")[0];

  const previousPeriodStartDateTime = `${previousPeriodStartString}T00:00:00.000Z`;
  const previousPeriodEndDateTime = `${previousPeriodEndString}T23:59:59.999Z`;

  const previousOrders = await MyGlobal.prisma.shopping_mall_orders.findMany({
    where: {
      created_at: {
        gte: previousPeriodStartDateTime,
        lte: previousPeriodEndDateTime,
      },
      deleted_at: null,
    },
    select: {
      total_amount: true,
    },
  });

  const previousGrossRevenue = previousOrders.reduce(
    (sum, order) => sum + Number(order.total_amount),
    0,
  );
  const growthRatePercentage =
    previousGrossRevenue > 0
      ? ((totalGrossRevenue - previousGrossRevenue) / previousGrossRevenue) *
        100
      : null;

  return {
    total_gross_revenue: totalGrossRevenue,
    total_net_revenue: totalNetRevenue,
    total_platform_commission: totalPlatformCommission,
    total_seller_payouts: totalSellerPayouts,
    total_refund_amount: totalRefundAmount,
    total_order_count: totalOrderCount,
    total_transaction_count: totalTransactionCount,
    average_order_value: averageOrderValue,
    growth_rate_percentage: growthRatePercentage,
    period_start_date: startDateTimeString,
    period_end_date: endDateTimeString,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSellerEarningsStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerEarningsStatistics";
import { IShoppingMallSellerEarningsTimeSeriesDataPoint } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerEarningsTimeSeriesDataPoint";
import { IShoppingMallSellerEarningsSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerEarningsSummary";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminStatisticsSellerEarnings(props: {
  admin: AdminPayload;
  body: IShoppingMallSellerEarningsStatistics.IRequest;
}): Promise<IShoppingMallSellerEarningsStatistics> {
  const {
    start_date,
    end_date,
    seller_ids,
    payout_status,
    aggregation_level = "monthly",
    include_top_sellers = false,
    top_sellers_limit = 10,
    minimum_transaction_count,
  } = props.body;

  const buildDateFilter = () => {
    if (!start_date && !end_date) return undefined;
    return {
      ...(start_date && { gte: start_date }),
      ...(end_date && { lt: end_date }),
    };
  };

  const dateFilter = buildDateFilter();

  const [commissions, allPayouts] = await Promise.all([
    MyGlobal.prisma.shopping_mall_platform_commissions.findMany({
      where: {
        ...(dateFilter && { created_at: dateFilter }),
        ...(seller_ids &&
          seller_ids.length > 0 && {
            shopping_mall_seller_id: { in: seller_ids },
          }),
      },
    }),
    MyGlobal.prisma.shopping_mall_seller_payouts.findMany({
      where: {
        ...(dateFilter && { created_at: dateFilter }),
        ...(seller_ids &&
          seller_ids.length > 0 && {
            shopping_mall_seller_id: { in: seller_ids },
          }),
        ...(payout_status && { status: payout_status }),
      },
    }),
  ]);

  const totalPlatformCommissions = commissions.reduce(
    (sum, c) => sum + Number(c.commission_amount),
    0,
  );

  const totalGrossRevenue = commissions.reduce(
    (sum, c) => sum + Number(c.order_subtotal),
    0,
  );

  const totalNetRevenue = totalGrossRevenue - totalPlatformCommissions;

  const completedPayouts = allPayouts.filter((p) => p.status === "completed");
  const pendingPayouts = allPayouts.filter(
    (p) => p.status === "pending" || p.status === "processing",
  );

  const totalPayoutsCompleted = completedPayouts.reduce(
    (sum, p) => sum + Number(p.net_payout_amount),
    0,
  );
  const totalPayoutsPending = pendingPayouts.reduce(
    (sum, p) => sum + Number(p.net_payout_amount),
    0,
  );

  const payoutCountCompleted = completedPayouts.length;
  const payoutCountPending = pendingPayouts.length;

  const averagePayoutAmount =
    payoutCountCompleted > 0 ? totalPayoutsCompleted / payoutCountCompleted : 0;

  const averageCommissionRate =
    totalGrossRevenue > 0
      ? (totalPlatformCommissions / totalGrossRevenue) * 100
      : 0;

  const uniqueSellerIds = new Set<string>();
  commissions.forEach((c) => {
    uniqueSellerIds.add(c.shopping_mall_seller_id);
  });
  const sellerCount = uniqueSellerIds.size;

  const buildTimePeriods = (): Array<{
    period_start: string & tags.Format<"date-time">;
    period_end: string & tags.Format<"date-time">;
  }> => {
    const periods: Array<{
      period_start: string & tags.Format<"date-time">;
      period_end: string & tags.Format<"date-time">;
    }> = [];

    if (commissions.length === 0) return periods;

    const now = new Date();
    const defaultStart = new Date(now.getFullYear(), now.getMonth() - 6, 1);
    const startTimestamp = start_date
      ? new Date(start_date).getTime()
      : defaultStart.getTime();
    const endTimestamp = end_date
      ? new Date(end_date).getTime()
      : now.getTime();

    let currentStart = new Date(startTimestamp);

    while (currentStart.getTime() < endTimestamp) {
      let currentEnd: Date;

      if (aggregation_level === "daily") {
        currentEnd = new Date(currentStart);
        currentEnd.setDate(currentEnd.getDate() + 1);
      } else if (aggregation_level === "weekly") {
        currentEnd = new Date(currentStart);
        currentEnd.setDate(currentEnd.getDate() + 7);
      } else if (aggregation_level === "monthly") {
        currentEnd = new Date(currentStart);
        currentEnd.setMonth(currentEnd.getMonth() + 1);
      } else {
        currentEnd = new Date(currentStart);
        currentEnd.setFullYear(currentEnd.getFullYear() + 1);
      }

      if (currentEnd.getTime() > endTimestamp) {
        currentEnd = new Date(endTimestamp);
      }

      periods.push({
        period_start: currentStart.toISOString() as string &
          tags.Format<"date-time">,
        period_end: currentEnd.toISOString() as string &
          tags.Format<"date-time">,
      });

      currentStart = currentEnd;
    }

    return periods;
  };

  const timePeriods = buildTimePeriods();

  const timeSeriesData: IShoppingMallSellerEarningsTimeSeriesDataPoint[] =
    timePeriods.map((period) => {
      const periodStartTime = new Date(period.period_start).getTime();
      const periodEndTime = new Date(period.period_end).getTime();

      const periodCommissions = commissions.filter((c) => {
        const cTime = new Date(c.created_at).getTime();
        return cTime >= periodStartTime && cTime < periodEndTime;
      });

      const periodPayouts = allPayouts.filter((p) => {
        const pTime = new Date(p.created_at).getTime();
        return (
          pTime >= periodStartTime &&
          pTime < periodEndTime &&
          p.status === "completed"
        );
      });

      const grossEarnings = periodCommissions.reduce(
        (sum, c) => sum + Number(c.order_subtotal),
        0,
      );

      const platformCommission = periodCommissions.reduce(
        (sum, c) => sum + Number(c.commission_amount),
        0,
      );

      const netEarnings = grossEarnings - platformCommission;

      const payoutAmount = periodPayouts.reduce(
        (sum, p) => sum + Number(p.net_payout_amount),
        0,
      );

      const transactionCount = periodCommissions.length;

      const periodSellerIds = new Set<string>();
      periodCommissions.forEach((c) => {
        periodSellerIds.add(c.shopping_mall_seller_id);
      });
      const activeSellerCount = periodSellerIds.size;

      return {
        period_start: period.period_start,
        period_end: period.period_end,
        gross_earnings: grossEarnings,
        net_earnings: netEarnings,
        platform_commission: platformCommission,
        payout_amount: payoutAmount,
        transaction_count: transactionCount,
        active_seller_count: activeSellerCount,
      };
    });

  let topEarningSellers: IShoppingMallSellerEarningsSummary[] | undefined =
    undefined;

  if (include_top_sellers) {
    const sellerEarningsMap = new Map<
      string,
      {
        seller_id: string;
        gross_revenue: number;
        platform_commissions: number;
        transaction_count: number;
      }
    >();

    for (const comm of commissions) {
      const sellerId = comm.shopping_mall_seller_id;
      const existing = sellerEarningsMap.get(sellerId) || {
        seller_id: sellerId,
        gross_revenue: 0,
        platform_commissions: 0,
        transaction_count: 0,
      };
      existing.gross_revenue += Number(comm.order_subtotal);
      existing.platform_commissions += Number(comm.commission_amount);
      existing.transaction_count += 1;
      sellerEarningsMap.set(sellerId, existing);
    }

    const sellerEarningsArray = Array.from(sellerEarningsMap.values())
      .filter((s) =>
        minimum_transaction_count
          ? s.transaction_count >= minimum_transaction_count
          : true,
      )
      .sort((a, b) => b.gross_revenue - a.gross_revenue)
      .slice(0, top_sellers_limit);

    const sellerDetailsMap = new Map<string, { name: string }>();
    const sellerIdsToFetch = sellerEarningsArray.map((s) => s.seller_id);
    if (sellerIdsToFetch.length > 0) {
      const sellers = await MyGlobal.prisma.shopping_mall_sellers.findMany({
        where: { id: { in: sellerIdsToFetch } },
        select: { id: true, store_name: true },
      });
      sellers.forEach((seller) => {
        sellerDetailsMap.set(seller.id, { name: seller.store_name });
      });
    }

    topEarningSellers = sellerEarningsArray.map((s) => {
      const sellerDetails = sellerDetailsMap.get(s.seller_id);
      const netRevenue = s.gross_revenue - s.platform_commissions;
      const avgTransactionValue =
        s.transaction_count > 0 ? s.gross_revenue / s.transaction_count : 0;

      return {
        seller_id: s.seller_id as string & tags.Format<"uuid">,
        seller_name: sellerDetails?.name || "Unknown Seller",
        gross_revenue: s.gross_revenue,
        net_revenue: netRevenue,
        platform_commissions: s.platform_commissions,
        transaction_count: s.transaction_count,
        average_transaction_value: avgTransactionValue,
      };
    });
  }

  return {
    total_gross_revenue: totalGrossRevenue,
    total_net_revenue: totalNetRevenue,
    total_platform_commissions: totalPlatformCommissions,
    total_payouts_completed: totalPayoutsCompleted,
    total_payouts_pending: totalPayoutsPending,
    average_payout_amount: averagePayoutAmount,
    payout_count_completed: payoutCountCompleted,
    payout_count_pending: payoutCountPending,
    average_commission_rate: averageCommissionRate,
    seller_count: sellerCount,
    time_series_data: timeSeriesData,
    top_earning_sellers: topEarningSellers,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
