      take: limit,
      orderBy:
        sortBy === "created_at"
          ? { created_at: sortOrder }
          : sortBy === "rating"
            ? { star_rating: sortOrder }
            : sortBy === "helpfulness"
              ? { helpfulness_vote_count: sortOrder }
              : { created_at: "desc" },
      include: {
        buyer: true,
        sale: {
          include: {
            seller: true,
            category: true,
          },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_reviews.count({
      where: {
        shopping_mall_buyer_id: props.buyerId,
        ...(props.body.sale_id && {
          shopping_mall_sale_id: props.body.sale_id,
        }),
