          address_label: {
            contains: props.body.address_label,
            mode: "insensitive",
          },
        }),
        ...(props.body.is_default !== undefined && {
          is_default: props.body.is_default,
        }),
        ...(props.body.search && {
          OR: [
            {
              recipient_name: {
                contains: props.body.search,
                mode: "insensitive",
              },
            },
            {
              street_address_line1: {
                contains: props.body.search,
                mode: "insensitive",
              },
            },
            {
