      },
      skip,
      take: limit,
      include: {
        saleSku: {
          include: {
            sale: {
              include: {
                seller: true,
                category: true,
              },
            },
          },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_order_items.count({
      where: {
