import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import { IPageIShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReview";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

export async function patchShoppingMallReviews(props: {
  body: IShoppingMallReview.IRequest;
}): Promise<IPageIShoppingMallReview.ISummary> {
  const {
    page = 1,
    limit = 20,
    sale_id,
    sku_id,
    seller_id,
    buyer_id,
    status,
    min_rating,
    max_rating,
    verified_purchase_only,
    is_anonymous,
    start_date,
    end_date,
    search_text,
    sort_by = "created_at",
    sort_order = "desc",
    has_seller_response,
    has_images,
  } = props.body;

  const skip = (page - 1) * limit;

  const buildWhereCondition = () => {
    const conditions: Record<string, unknown> = {
      deleted_at: null,
      status: status ?? "approved",
    };

    if (sale_id) {
      conditions.shopping_mall_sale_id = sale_id;
    }

    if (sku_id) {
      conditions.shopping_mall_sale_sku_id = sku_id;
    }

    if (buyer_id) {
      conditions.shopping_mall_buyer_id = buyer_id;
    }

    if (seller_id) {
      conditions.sale = {
        shopping_mall_seller_id: seller_id,
      };
    }

    if (min_rating !== undefined || max_rating !== undefined) {
      const ratingCondition: Record<string, unknown> = {};
      if (min_rating !== undefined) {
        ratingCondition.gte = min_rating;
      }
      if (max_rating !== undefined) {
        ratingCondition.lte = max_rating;
      }
      conditions.star_rating = ratingCondition;
    }

    if (verified_purchase_only === true) {
      conditions.is_verified_purchase = true;
    }

    if (is_anonymous !== undefined) {
      conditions.is_anonymous = is_anonymous;
    }

    if (start_date || end_date) {
      const dateCondition: Record<string, unknown> = {};
      if (start_date) {
        dateCondition.gte = new Date(start_date);
      }
      if (end_date) {
        dateCondition.lt = new Date(end_date);
      }
      conditions.created_at = dateCondition;
    }

    if (search_text) {
      conditions.OR = [
        { review_body: { contains: search_text, mode: "insensitive" } },
        { review_title: { contains: search_text, mode: "insensitive" } },
      ];
    }

    if (has_seller_response !== undefined) {
      conditions.seller_responses = has_seller_response
        ? { some: { deleted_at: null } }
        : { none: {} };
    }

    if (has_images !== undefined) {
      conditions.review_images = has_images ? { some: {} } : { none: {} };
    }

    return conditions;
  };

  const whereCondition = buildWhereCondition();

  const orderByCondition =
    sort_by === "rating"
      ? { star_rating: sort_order }
      : sort_by === "helpfulness"
        ? { helpfulness_vote_count: sort_order }
        : { created_at: sort_order };

  const [reviews, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_reviews.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy: orderByCondition,
      include: {
        buyer: true,
        sale: {
          include: {
            seller: true,
            category: true,
          },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_reviews.count({
      where: whereCondition,
    }),
  ]);

  const saleIds = [...new Set(reviews.map((r) => r.shopping_mall_sale_id))];

  const skuData = await MyGlobal.prisma.shopping_mall_sale_skus.findMany({
    where: {
      shopping_mall_sale_id: { in: saleIds },
      enabled: true,
    },
    select: {
      shopping_mall_sale_id: true,
      base_price: true,
    },
  });

  const imageData = await MyGlobal.prisma.shopping_mall_sale_images.findMany({
    where: {
      shopping_mall_sale_id: { in: saleIds },
      shopping_mall_sale_sku_id: null,
    },
    orderBy: {
      display_order: "asc",
    },
    select: {
      shopping_mall_sale_id: true,
      url_small: true,
    },
  });

  const priceMap = new Map<string, number>();
  for (const saleId of saleIds) {
    const skusForSale = skuData.filter(
      (s) => s.shopping_mall_sale_id === saleId,
    );
    if (skusForSale.length > 0) {
      priceMap.set(saleId, Math.min(...skusForSale.map((s) => s.base_price)));
    } else {
      priceMap.set(saleId, 0);
    }
  }

  const thumbnailMap = new Map<string, string | null>();
  for (const saleId of saleIds) {
    const imagesForSale = imageData.filter(
      (i) => i.shopping_mall_sale_id === saleId,
    );
    thumbnailMap.set(
      saleId,
      imagesForSale.length > 0 ? imagesForSale[0].url_small : null,
    );
  }

  const data: IShoppingMallReview.ISummary[] = reviews.map((review) => {
    const minPrice = priceMap.get(review.shopping_mall_sale_id) ?? 0;
    const thumbnailUrl = thumbnailMap.get(review.shopping_mall_sale_id) ?? null;

    return {
      id: review.id,
      shopping_mall_buyer_id: review.shopping_mall_buyer_id,
      shopping_mall_sale_id: review.shopping_mall_sale_id,
      shopping_mall_sale_sku_id: review.shopping_mall_sale_sku_id,
      shopping_mall_order_id: review.shopping_mall_order_id,
      buyer: {
        id: review.buyer.id,
        email: review.buyer.email,
        full_name: review.buyer.full_name,
        phone_number: review.buyer.phone_number ?? null,
      },
      sale: {
        id: review.sale.id,
        code: review.sale.code,
        title: review.sale.title,
        status: typia.assert<
          "draft" | "pending_approval" | "published" | "suspended" | "archived"
        >(review.sale.status),
        condition: typia.assert<"new" | "refurbished" | "used">(
          review.sale.condition,
        ),
        brand: review.sale.brand ?? null,
        short_description: review.sale.short_description ?? null,
        price: minPrice,
        thumbnail_url: thumbnailUrl,
        return_policy_days: review.sale.return_policy_days,
        warranty_info: review.sale.warranty_info ?? null,
        created_at: toISOStringSafe(review.sale.created_at),
        updated_at: toISOStringSafe(review.sale.updated_at),
        deleted_at: review.sale.deleted_at
          ? toISOStringSafe(review.sale.deleted_at)
          : null,
        seller: {
          id: review.sale.seller.id,
          store_name: review.sale.seller.store_name,
          email: review.sale.seller.email,
          status: typia.assert<
            "pending" | "approved" | "rejected" | "suspended"
          >(review.sale.seller.status),
          email_verified: review.sale.seller.email_verified,
        },
        category: {
          id: review.sale.category.id,
          name: review.sale.category.name,
          slug: review.sale.category.slug,
          description: review.sale.category.description ?? null,
          image_url: review.sale.category.image_url ?? null,
          parent_id: review.sale.category.parent_id ?? null,
          status: review.sale.category.status,
          display_order: review.sale.category.display_order,
          product_count: review.sale.category.product_count,
          created_at: toISOStringSafe(review.sale.category.created_at),
          updated_at: toISOStringSafe(review.sale.category.updated_at),
        },
      },
      star_rating: review.star_rating,
      review_title: review.review_title ?? null,
      review_body: review.review_body ?? null,
      status: typia.assert<"pending_moderation" | "approved" | "rejected">(
        review.status,
      ),
      is_verified_purchase: review.is_verified_purchase,
      is_anonymous: review.is_anonymous,
      helpfulness_vote_count: review.helpfulness_vote_count,
      created_at: toISOStringSafe(review.created_at),
      updated_at: toISOStringSafe(review.updated_at),
      deleted_at: review.deleted_at ? toISOStringSafe(review.deleted_at) : null,
    };
  });

  const pagination: IPage.IPagination = {
    current: page,
    limit: limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  return {
    pagination,
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import { IPageIShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSale";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

export async function patchShoppingMallSales(props: {
  body: IShoppingMallSale.IRequest;
}): Promise<IPageIShoppingMallSale.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  const whereCondition: Record<string, unknown> = {
    deleted_at: null,
  };

  if (props.body.search) {
    whereCondition.title = {
      contains: props.body.search,
      mode: "insensitive",
    };
  }

  if (props.body.seller_id) {
    whereCondition.shopping_mall_seller_id = props.body.seller_id;
  }

  if (props.body.category_id) {
    whereCondition.shopping_mall_category_id = props.body.category_id;
  }

  whereCondition.status = props.body.status ?? "published";

  if (props.body.condition) {
    whereCondition.condition = props.body.condition;
  }

  if (props.body.brand) {
    whereCondition.brand = props.body.brand;
  }

  const hasComplexFiltering =
    props.body.min_price !== undefined ||
    props.body.max_price !== undefined ||
    props.body.has_stock === true ||
    props.body.sort_by === "price_asc" ||
    props.body.sort_by === "price_desc";

  const fetchLimit = hasComplexFiltering ? 1000 : limit;
  const fetchSkip = hasComplexFiltering ? 0 : skip;

  let orderBy: Record<string, unknown>;
  const sortBy = props.body.sort_by;
  if (!hasComplexFiltering) {
    if (sortBy === "title_asc") {
      orderBy = { title: Prisma.SortOrder.asc };
    } else if (sortBy === "title_desc") {
      orderBy = { title: Prisma.SortOrder.desc };
    } else {
      orderBy = { created_at: Prisma.SortOrder.desc };
    }
  } else {
    orderBy = { created_at: Prisma.SortOrder.desc };
  }

  const [sales, totalBeforeComplexFilter] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sales.findMany({
      where: whereCondition,
      skip: fetchSkip,
      take: fetchLimit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_sales.count({ where: whereCondition }),
  ]);

  if (sales.length === 0) {
    return {
      data: [],
      pagination: {
        current: page,
        limit: limit,
        records: 0,
        pages: 0,
      },
    };
  }

  const saleIds = sales.map((s) => s.id);
  const sellerIds = [...new Set(sales.map((s) => s.shopping_mall_seller_id))];
  const categoryIds = [
    ...new Set(sales.map((s) => s.shopping_mall_category_id)),
  ];

  const [sellers, categories, skus, images] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sellers.findMany({
      where: { id: { in: sellerIds } },
    }),
    MyGlobal.prisma.shopping_mall_categories.findMany({
      where: { id: { in: categoryIds } },
    }),
    MyGlobal.prisma.shopping_mall_sale_skus.findMany({
      where: {
        shopping_mall_sale_id: { in: saleIds },
        enabled: true,
      },
      select: {
        shopping_mall_sale_id: true,
        base_price: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_sale_images.findMany({
      where: {
        shopping_mall_sale_id: { in: saleIds },
        is_primary: true,
      },
      select: {
        shopping_mall_sale_id: true,
        url_small: true,
      },
    }),
  ]);

  const sellerMap = new Map(sellers.map((s) => [s.id, s]));
  const categoryMap = new Map(categories.map((c) => [c.id, c]));
  const skuPriceMap = new Map<string, number>();
  for (const sku of skus) {
    const currentMin = skuPriceMap.get(sku.shopping_mall_sale_id);
    if (currentMin === undefined || sku.base_price < currentMin) {
      skuPriceMap.set(sku.shopping_mall_sale_id, sku.base_price);
    }
  }
  const imageMap = new Map(
    images.map((img) => [img.shopping_mall_sale_id, img.url_small]),
  );

  let processedSales = sales.map((sale) => {
    const seller = sellerMap.get(sale.shopping_mall_seller_id);
    const category = categoryMap.get(sale.shopping_mall_category_id);
    const price = skuPriceMap.get(sale.id) ?? 0;
    const thumbnail = imageMap.get(sale.id) ?? null;

    return {
      sale,
      seller,
      category,
      price,
      thumbnail,
    };
  });

  if (props.body.min_price !== undefined) {
    processedSales = processedSales.filter(
      (item) => item.price >= props.body.min_price!,
    );
  }

  if (props.body.max_price !== undefined) {
    processedSales = processedSales.filter(
      (item) => item.price <= props.body.max_price!,
    );
  }

  if (props.body.has_stock === true) {
    processedSales = processedSales.filter((item) =>
      skuPriceMap.has(item.sale.id),
    );
  }

  if (sortBy === "price_asc") {
    processedSales.sort((a, b) => a.price - b.price);
  } else if (sortBy === "price_desc") {
    processedSales.sort((a, b) => b.price - a.price);
  } else if (sortBy === "title_asc") {
    processedSales.sort((a, b) => a.sale.title.localeCompare(b.sale.title));
  } else if (sortBy === "title_desc") {
    processedSales.sort((a, b) => b.sale.title.localeCompare(a.sale.title));
  }

  const totalFiltered = processedSales.length;
  const paginatedResults = processedSales.slice(skip, skip + limit);

  return {
    data: paginatedResults.map((item) => {
      if (!item.seller) {
        throw new HttpException("Seller not found", 500);
      }
      if (!item.category) {
        throw new HttpException("Category not found", 500);
      }

      return {
        id: item.sale.id,
        code: item.sale.code,
        title: item.sale.title,
        status: typia.assert<
          "draft" | "pending_approval" | "published" | "suspended" | "archived"
        >(item.sale.status),
        condition: typia.assert<"new" | "refurbished" | "used">(
          item.sale.condition,
        ),
        brand: item.sale.brand ?? null,
        short_description: item.sale.short_description ?? null,
        price: item.price,
        thumbnail_url: item.thumbnail ?? null,
        return_policy_days: item.sale.return_policy_days,
        warranty_info: item.sale.warranty_info ?? null,
        created_at: toISOStringSafe(item.sale.created_at),
        updated_at: toISOStringSafe(item.sale.updated_at),
        deleted_at: item.sale.deleted_at
          ? toISOStringSafe(item.sale.deleted_at)
          : null,
        seller: {
          id: item.seller.id,
          store_name: item.seller.store_name,
          email: item.seller.email,
          status: typia.assert<
            "pending" | "approved" | "rejected" | "suspended"
          >(item.seller.status),
          email_verified: item.seller.email_verified,
        },
        category: {
          id: item.category.id,
          name: item.category.name,
          slug: item.category.slug,
          description: item.category.description ?? null,
          image_url: item.category.image_url ?? null,
          parent_id: item.category.parent_id ?? null,
          status: item.category.status,
          display_order: item.category.display_order,
          product_count: item.category.product_count,
          created_at: toISOStringSafe(item.category.created_at),
          updated_at: toISOStringSafe(item.category.updated_at),
        },
      };
    }),
    pagination: {
      current: page,
      limit: limit,
      records: hasComplexFiltering ? totalFiltered : totalBeforeComplexFilter,
      pages: Math.ceil(
        (hasComplexFiltering ? totalFiltered : totalBeforeComplexFilter) /
          limit,
      ),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSaleSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleSku";
import { IPageIShoppingMallSaleSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSaleSku";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";

export async function patchShoppingMallSalesSaleCodeSkus(props: {
  saleCode: string;
  body: IShoppingMallSaleSku.IRequest;
}): Promise<IPageIShoppingMallSaleSku.ISummary> {
  const sale = await MyGlobal.prisma.shopping_mall_sales.findFirst({
    where: {
      code: props.saleCode,
      deleted_at: null,
    },
  });

  if (!sale) {
    throw new HttpException("Sale not found", 404);
  }

  const [seller, category] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sellers.findUnique({
      where: { id: sale.shopping_mall_seller_id },
    }),
    MyGlobal.prisma.shopping_mall_categories.findUnique({
      where: { id: sale.shopping_mall_category_id },
    }),
  ]);

  if (!seller || !category) {
    throw new HttpException("Sale data integrity error", 500);
  }

  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  const baseWhereCondition = {
    shopping_mall_sale_id: sale.id,
    ...(props.body.search && {
      OR: [
        { sku_code: { contains: props.body.search } },
        { variant_combination: { contains: props.body.search } },
      ],
    }),
    ...(props.body.variant_value_ids &&
      props.body.variant_value_ids.length > 0 && {
        shopping_mall_sale_sku_variant_values: {
          some: {
            shopping_mall_sale_variant_value_id: {
              in: props.body.variant_value_ids,
            },
          },
        },
      }),
    ...((props.body.min_price !== undefined ||
      props.body.max_price !== undefined) && {
      base_price: {
        ...(props.body.min_price !== undefined && {
          gte: props.body.min_price,
        }),
        ...(props.body.max_price !== undefined && {
          lte: props.body.max_price,
        }),
      },
    }),
    ...(props.body.is_active !== undefined && {
      enabled: props.body.is_active,
    }),
  };

  const hasStockFilter =
    props.body.min_stock !== undefined || props.body.max_stock !== undefined;

  let skus;
  let total;

  if (hasStockFilter) {
    const allSkus = await MyGlobal.prisma.shopping_mall_sale_skus.findMany({
      where: baseWhereCondition,
      include: {
        shopping_mall_inventory_stocks: true,
      },
    });

    const filteredSkus = allSkus.filter((sku) => {
      if (!sku.shopping_mall_inventory_stocks) return false;

      const meetsMinStock =
        props.body.min_stock === undefined ||
        sku.shopping_mall_inventory_stocks.available_quantity >=
          props.body.min_stock;
      const meetsMaxStock =
        props.body.max_stock === undefined ||
        sku.shopping_mall_inventory_stocks.available_quantity <=
          props.body.max_stock;

      return meetsMinStock && meetsMaxStock;
    });

    total = filteredSkus.length;

    const sortedSkus = [...filteredSkus];
    if (props.body.sort_by) {
      const sortField =
        props.body.sort_by === "price" ? "base_price" : props.body.sort_by;
      const sortOrder = props.body.sort_order ?? "asc";

      sortedSkus.sort((a, b) => {
        const aVal = a[sortField as keyof typeof a] ?? 0;
        const bVal = b[sortField as keyof typeof b] ?? 0;
        if (aVal < bVal) return sortOrder === "asc" ? -1 : 1;
        if (aVal > bVal) return sortOrder === "asc" ? 1 : -1;
        return 0;
      });
    }

    skus = sortedSkus.slice(skip, skip + limit);
  } else {
    [skus, total] = await Promise.all([
      MyGlobal.prisma.shopping_mall_sale_skus.findMany({
        where: baseWhereCondition,
        skip,
        take: limit,
        ...(props.body.sort_by && {
          orderBy: {
            [props.body.sort_by === "price"
              ? "base_price"
              : props.body.sort_by]: props.body.sort_order ?? "asc",
          },
        }),
      }),
      MyGlobal.prisma.shopping_mall_sale_skus.count({
        where: baseWhereCondition,
      }),
    ]);
  }

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: skus.map((sku) => ({
      id: sku.id,
      sku_code: sku.sku_code,
      variant_combination: sku.variant_combination,
      base_price: sku.base_price,
      price: sku.sale_price ?? sku.base_price,
      enabled: sku.enabled,
      sale: {
        id: sale.id,
        code: sale.code,
        title: sale.title,
        status: typia.assert<
          "draft" | "pending_approval" | "published" | "suspended" | "archived"
        >(sale.status),
        condition: typia.assert<"new" | "refurbished" | "used">(sale.condition),
        brand: sale.brand === null ? undefined : sale.brand,
        short_description:
          sale.short_description === null ? undefined : sale.short_description,
        price: sku.base_price,
        thumbnail_url: undefined,
        return_policy_days: sale.return_policy_days,
        warranty_info:
          sale.warranty_info === null ? undefined : sale.warranty_info,
        created_at: toISOStringSafe(sale.created_at),
        updated_at: toISOStringSafe(sale.updated_at),
        deleted_at:
          sale.deleted_at === null
            ? undefined
            : toISOStringSafe(sale.deleted_at),
        seller: {
          id: seller.id,
          store_name: seller.store_name,
          email: seller.email,
          status: typia.assert<
            "pending" | "approved" | "rejected" | "suspended"
          >(seller.status),
          email_verified: seller.email_verified,
        },
        category: {
          id: category.id,
          name: category.name,
          slug: category.slug,
          description:
            category.description === null ? undefined : category.description,
          image_url:
            category.image_url === null ? undefined : category.image_url,
          parent_id:
            category.parent_id === null ? undefined : category.parent_id,
          status: category.status,
          display_order: category.display_order,
          product_count: category.product_count,
          created_at: toISOStringSafe(category.created_at),
          updated_at: toISOStringSafe(category.updated_at),
        },
      },
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
