              },
            },
          ],
        }),
        ...(props.body.seller_id && {
          sale: {
            shopping_mall_seller_id: props.body.seller_id,
          },
        }),
      },
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
