          ? props.body.sort.map((sortItem) =>
              sortItem.startsWith("-")
                ? { [sortItem.substring(1)]: "desc" as const }
                : {
                    [sortItem.startsWith("+")
                      ? sortItem.substring(1)
                      : sortItem]: "asc" as const,
                  },
            )
          : [{ created_at: "desc" as const }],
    }),
    MyGlobal.prisma.shopping_mall_seller_sessions.count({
