  seller: SellerPayload;
  saleCode: string;
  body: IShoppingMallSaleVariantAttribute.ICreate;
}): Promise<IShoppingMallSaleVariantAttribute> {
  const sale = await MyGlobal.prisma.shopping_mall_sales.findFirst({
    where: {
      code: props.saleCode,
      deleted_at: null,
    },
