import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthAdminLogin(props: {
  body: IShoppingMallAdmin.ILogin;
}): Promise<IShoppingMallAdmin.IAuthorized> {
  const admin = await MyGlobal.prisma.shopping_mall_admins.findFirst({
    where: { email: props.body.email },
  });

  if (!admin) {
    throw new HttpException("Invalid credentials", 401);
  }

  const isValid = await PasswordUtil.verify(
    props.body.password,
    admin.password_hash,
  );

  if (!isValid) {
    throw new HttpException("Invalid credentials", 401);
  }

  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session = await MyGlobal.prisma.shopping_mall_admin_sessions.create({
    data: {
      id: v4(),
      shopping_mall_admin_id: admin.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(new Date()),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  const accessToken = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "1h",
      issuer: "autobe",
    },
  );

  const refreshToken = jwt.sign(
    {
      type: "admin",
      id: admin.id,
      session_id: session.id,
      tokenType: "refresh",
      created_at: toISOStringSafe(new Date()),
    },
    MyGlobal.env.JWT_SECRET_KEY,
    {
      expiresIn: "7d",
      issuer: "autobe",
    },
  );

  return {
    id: admin.id,
    email: admin.email,
    full_name: admin.full_name,
    phone_number: admin.phone_number,
    admin_level: typia.assert<"super_admin" | "moderator" | "support">(
      admin.admin_level,
    ),
    email_verified: admin.email_verified,
    created_at: toISOStringSafe(admin.created_at),
    updated_at: toISOStringSafe(admin.updated_at),
    deleted_at: admin.deleted_at ? toISOStringSafe(admin.deleted_at) : null,
    token: {
      access: accessToken,
      refresh: refreshToken,
      expired_at: toISOStringSafe(accessExpires),
      refreshable_until: toISOStringSafe(refreshExpires),
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";

export async function postAuthBuyerJoin(props: {
  body: IShoppingMallBuyer.ICreate;
}): Promise<IShoppingMallBuyer.IAuthorized> {
  const existing = await MyGlobal.prisma.shopping_mall_buyers.findFirst({
    where: { email: props.body.email },
  });

  if (existing) {
    throw new HttpException("Email already registered", 409);
  }

  const hashedPassword: string = await PasswordUtil.hash(props.body.password);

  const buyer = await MyGlobal.prisma.shopping_mall_buyers.create({
    data: {
      id: v4(),
      email: props.body.email,
      password_hash: hashedPassword,
      full_name: props.body.full_name,
      phone_number: props.body.phone_number ?? null,
      email_verified: false,
      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      deleted_at: null,
    },
  });

  const accessExpires: Date = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires: Date = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const session = await MyGlobal.prisma.shopping_mall_buyer_sessions.create({
    data: {
      id: v4(),
      shopping_mall_buyer_id: buyer.id,
      ip: props.body.ip ?? "",
      href: props.body.href,
      referrer: props.body.referrer,
      created_at: toISOStringSafe(new Date()),
      expired_at: toISOStringSafe(accessExpires),
    },
  });

  const token = {
    access: jwt.sign(
      {
        type: "buyer",
        id: buyer.id,
        session_id: session.id,
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "buyer",
        id: buyer.id,
        session_id: session.id,
        tokenType: "refresh",
        created_at: toISOStringSafe(new Date()),
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  return {
    id: buyer.id,
    email: buyer.email,
    full_name: buyer.full_name,
    phone_number: buyer.phone_number ?? undefined,
    email_verified: buyer.email_verified,
    created_at: toISOStringSafe(buyer.created_at),
    updated_at: toISOStringSafe(buyer.updated_at),
    deleted_at:
      buyer.deleted_at !== null && buyer.deleted_at !== undefined
        ? toISOStringSafe(buyer.deleted_at)
        : undefined,
    token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallPaymentTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentTransaction";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import { IShoppingMallPaymentMethod } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPaymentMethod";
import { BuyerPayload } from "../decorators/payload/BuyerPayload";

export async function postShoppingMallBuyerOrdersOrderIdPaymentTransactions(props: {
  buyer: BuyerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallPaymentTransaction.ICreate;
}): Promise<IShoppingMallPaymentTransaction> {
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      id: props.orderId,
      shopping_mall_buyer_id: props.buyer.id,
      deleted_at: null,
    },
  });

  if (!order) {
    throw new HttpException("Order not found or access denied", 404);
  }

  if (props.body.payment_method_id) {
    const paymentMethod =
      await MyGlobal.prisma.shopping_mall_payment_methods.findFirst({
        where: {
          id: props.body.payment_method_id,
          shopping_mall_buyer_id: props.buyer.id,
          deleted_at: null,
        },
      });

    if (!paymentMethod) {
      throw new HttpException("Payment method not found or access denied", 404);
    }

    if (!paymentMethod.is_verified) {
      throw new HttpException("Payment method is not verified", 400);
    }
  }

  if (props.body.amount !== order.total_amount) {
    throw new HttpException("Payment amount does not match order total", 400);
  }

  const created =
    await MyGlobal.prisma.shopping_mall_payment_transactions.create({
      data: {
        id: v4(),
        shopping_mall_order_id: props.orderId,
        shopping_mall_buyer_id: props.buyer.id,
        shopping_mall_payment_method_id: props.body.payment_method_id ?? null,
        transaction_type: props.body.transaction_type,
        amount: props.body.amount,
        currency: props.body.currency,
        status: props.body.status,
        provider: props.body.provider,
        provider_transaction_id: props.body.provider_transaction_id ?? null,
        provider_response: props.body.provider_response ?? null,
        failure_reason: props.body.failure_reason ?? null,
        failure_code: props.body.failure_code ?? null,
        ip_address: props.body.ip_address ?? null,
        user_agent: props.body.user_agent ?? null,
        created_at: new Date(),
      },
      include: {
        order: true,
        buyer: true,
        paymentMethod: true,
      },
    });

  return {
    id: created.id,
    shopping_mall_order_id: created.shopping_mall_order_id,
    order: created.order
      ? {
          id: created.order.id,
          order_number: created.order.order_number,
          status: created.order.status satisfies string as string,
          subtotal: created.order.subtotal,
          shipping_total: created.order.shipping_total,
          tax_total: created.order.tax_total,
          discount_total: created.order.discount_total,
          total_amount: created.order.total_amount,
          estimated_delivery_start: created.order.estimated_delivery_start
            ? toISOStringSafe(created.order.estimated_delivery_start)
            : null,
          estimated_delivery_end: created.order.estimated_delivery_end
            ? toISOStringSafe(created.order.estimated_delivery_end)
            : null,
          actual_delivery_at: created.order.actual_delivery_at
            ? toISOStringSafe(created.order.actual_delivery_at)
            : null,
          cancelled_at: created.order.cancelled_at
            ? toISOStringSafe(created.order.cancelled_at)
            : null,
          completed_at: created.order.completed_at
            ? toISOStringSafe(created.order.completed_at)
            : null,
          created_at: toISOStringSafe(created.order.created_at),
          updated_at: toISOStringSafe(created.order.updated_at),
        }
      : undefined,
    shopping_mall_buyer_id: created.shopping_mall_buyer_id,
    buyer: created.buyer
      ? {
          id: created.buyer.id,
          email: created.buyer.email,
          full_name: created.buyer.full_name,
          phone_number: created.buyer.phone_number ?? null,
        }
      : undefined,
    shopping_mall_payment_method_id:
      created.shopping_mall_payment_method_id ?? null,
    paymentMethod: created.paymentMethod
      ? {
          id: created.paymentMethod.id,
          payment_type: typia.assert<
            | "credit_card"
            | "debit_card"
            | "paypal"
            | "apple_pay"
            | "google_pay"
            | "bank_transfer"
          >(created.paymentMethod.payment_type),
          provider: typia.assert<
            "stripe" | "paypal" | "square" | "adyen" | "braintree"
          >(created.paymentMethod.provider),
          last_four_digits: created.paymentMethod.last_four_digits ?? null,
          card_brand: created.paymentMethod.card_brand ?? null,
          billing_name: created.paymentMethod.billing_name,
          billing_postal_code:
            created.paymentMethod.billing_postal_code ?? null,
          expiry_month: created.paymentMethod.expiry_month ?? null,
          expiry_year: created.paymentMethod.expiry_year ?? null,
          is_default: created.paymentMethod.is_default,
          is_verified: created.paymentMethod.is_verified,
          created_at: toISOStringSafe(created.paymentMethod.created_at),
          updated_at: toISOStringSafe(created.paymentMethod.updated_at),
        }
      : null,
    transaction_type: created.transaction_type satisfies string as string,
    amount: created.amount,
    currency: created.currency satisfies string as string,
    status: created.status satisfies string as string,
    provider: created.provider satisfies string as string,
    provider_transaction_id: created.provider_transaction_id ?? null,
    provider_response: created.provider_response ?? null,
    failure_reason: created.failure_reason ?? null,
    failure_code: created.failure_code ?? null,
    ip_address: created.ip_address ?? null,
    user_agent: created.user_agent ?? null,
    created_at: toISOStringSafe(created.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSellerPayout } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerPayout";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function getShoppingMallSellerSellerPayoutsPayoutId(props: {
  seller: SellerPayload;
  payoutId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallSellerPayout> {
  const payout = await MyGlobal.prisma.shopping_mall_seller_payouts.findUnique({
    where: {
      id: props.payoutId,
    },
  });

  if (!payout) {
    throw new HttpException("Payout not found", 404);
  }

  if (payout.shopping_mall_seller_id !== props.seller.id) {
    throw new HttpException("Forbidden", 403);
  }

  const seller = await MyGlobal.prisma.shopping_mall_sellers.findUnique({
    where: {
      id: payout.shopping_mall_seller_id,
    },
  });

  if (!seller) {
    throw new HttpException("Seller not found", 404);
  }

  return {
    id: payout.id as string & tags.Format<"uuid">,
    shopping_mall_seller_id: payout.shopping_mall_seller_id as string &
      tags.Format<"uuid">,
    seller: {
      id: seller.id as string & tags.Format<"uuid">,
      store_name: seller.store_name,
      email: seller.email as string & tags.Format<"email">,
      status: seller.status as
        | "pending"
        | "approved"
        | "rejected"
        | "suspended",
      email_verified: seller.email_verified,
    },
    payout_period_start: toISOStringSafe(payout.payout_period_start),
    payout_period_end: toISOStringSafe(payout.payout_period_end),
    gross_amount: payout.gross_amount,
    commission_amount: payout.commission_amount,
    refund_amount: payout.refund_amount,
    adjustment_amount: payout.adjustment_amount,
    net_payout_amount: payout.net_payout_amount,
    currency: payout.currency,
    status: typia.assert<"pending" | "processing" | "completed" | "failed">(
      payout.status,
    ),
    bank_account_last_four:
      payout.bank_account_last_four === null
        ? undefined
        : payout.bank_account_last_four,
    bank_name: payout.bank_name === null ? undefined : payout.bank_name,
    transfer_reference:
      payout.transfer_reference === null
        ? undefined
        : payout.transfer_reference,
    failure_reason:
      payout.failure_reason === null ? undefined : payout.failure_reason,
    notes: payout.notes === null ? undefined : payout.notes,
    initiated_at: payout.initiated_at
      ? toISOStringSafe(payout.initiated_at)
      : undefined,
    completed_at: payout.completed_at
      ? toISOStringSafe(payout.completed_at)
      : undefined,
    created_at: toISOStringSafe(payout.created_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import { IPageIShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallReview";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallBuyer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallBuyer";
import { IShoppingMallSale } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSale";
import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminBuyersBuyerIdReviews(props: {
  admin: AdminPayload;
  buyerId: string & tags.Format<"uuid">;
  body: IShoppingMallReview.IRequest;
}): Promise<IPageIShoppingMallReview.ISummary> {
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;

  const buildWhereCondition = () => {
    const conditions: Record<string, unknown> = {
      shopping_mall_buyer_id: props.buyerId,
    };

    if (props.body.sale_id) {
      conditions.shopping_mall_sale_id = props.body.sale_id;
    }

    if (props.body.sku_id) {
      conditions.shopping_mall_sale_sku_id = props.body.sku_id;
    }

    if (props.body.seller_id) {
      conditions.sale = {
        shopping_mall_seller_id: props.body.seller_id,
      };
    }

    if (props.body.status) {
      conditions.status = props.body.status;
    }

    if (
      props.body.min_rating !== undefined ||
      props.body.max_rating !== undefined
    ) {
      const ratingFilter: Record<string, unknown> = {};
      if (props.body.min_rating !== undefined) {
        ratingFilter.gte = props.body.min_rating;
      }
      if (props.body.max_rating !== undefined) {
        ratingFilter.lte = props.body.max_rating;
      }
      conditions.star_rating = ratingFilter;
    }

    if (props.body.verified_purchase_only !== undefined) {
      conditions.is_verified_purchase = props.body.verified_purchase_only;
    }

    if (props.body.is_anonymous !== undefined) {
      conditions.is_anonymous = props.body.is_anonymous;
    }

    if (props.body.start_date || props.body.end_date) {
      const dateFilter: Record<string, unknown> = {};
      if (props.body.start_date) {
        dateFilter.gte = new Date(props.body.start_date);
      }
      if (props.body.end_date) {
        dateFilter.lt = new Date(props.body.end_date);
      }
      conditions.created_at = dateFilter;
    }

    if (props.body.search_text) {
      conditions.OR = [
        { review_title: { contains: props.body.search_text } },
        { review_body: { contains: props.body.search_text } },
      ];
    }

    if (props.body.has_seller_response !== undefined) {
      if (props.body.has_seller_response) {
        conditions.shopping_mall_review_seller_responses = { some: {} };
      } else {
        conditions.shopping_mall_review_seller_responses = { none: {} };
      }
    }

    if (props.body.has_images !== undefined) {
      if (props.body.has_images) {
        conditions.shopping_mall_review_images = { some: {} };
      } else {
        conditions.shopping_mall_review_images = { none: {} };
      }
    }

    return conditions;
  };

  const whereCondition = buildWhereCondition();

  const sortBy = props.body.sort_by ?? "created_at";
  const sortOrder = props.body.sort_order ?? "desc";
  const orderByField =
    sortBy === "helpfulness" ? "helpfulness_vote_count" : sortBy;
  const orderBy = { [orderByField]: sortOrder };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_reviews.findMany({
      where: whereCondition,
      skip,
      take: limit,
      orderBy,
      include: {
        buyer: true,
        sale: {
          include: {
            seller: true,
            category: true,
          },
        },
      },
    }),
    MyGlobal.prisma.shopping_mall_reviews.count({
      where: whereCondition,
    }),
  ]);

  const saleIds = [
    ...new Set(data.map((review) => review.shopping_mall_sale_id)),
  ];
  const skuPrices = await MyGlobal.prisma.shopping_mall_sale_skus.groupBy({
    by: ["shopping_mall_sale_id"],
    where: {
      shopping_mall_sale_id: { in: saleIds },
      enabled: true,
    },
    _min: {
      base_price: true,
    },
  });

  const priceMap = new Map(
    skuPrices.map((item) => [
      item.shopping_mall_sale_id,
      item._min.base_price ?? 0,
    ]),
  );

  return {
    data: data.map((review) => ({
      id: review.id,
      shopping_mall_buyer_id: review.shopping_mall_buyer_id,
      shopping_mall_sale_id: review.shopping_mall_sale_id,
      shopping_mall_sale_sku_id: review.shopping_mall_sale_sku_id,
      shopping_mall_order_id: review.shopping_mall_order_id,
      buyer: {
        id: review.buyer.id,
        email: review.buyer.email,
        full_name: review.buyer.full_name,
        phone_number: review.buyer.phone_number ?? null,
      },
      sale: {
        id: review.sale.id,
        code: review.sale.code,
        title: review.sale.title,
        status: typia.assert<
          "suspended" | "draft" | "pending_approval" | "published" | "archived"
        >(review.sale.status),
        condition: typia.assert<"new" | "refurbished" | "used">(
          review.sale.condition,
        ),
        brand: review.sale.brand ?? null,
        short_description: review.sale.short_description ?? null,
        price: priceMap.get(review.shopping_mall_sale_id) ?? 0,
        thumbnail_url: null,
        return_policy_days: review.sale.return_policy_days,
        warranty_info: review.sale.warranty_info ?? null,
        created_at: toISOStringSafe(review.sale.created_at),
        updated_at: toISOStringSafe(review.sale.updated_at),
        deleted_at: review.sale.deleted_at
          ? toISOStringSafe(review.sale.deleted_at)
          : null,
        seller: {
          id: review.sale.seller.id,
          store_name: review.sale.seller.store_name,
          email: review.sale.seller.email,
          status: review.sale.seller.status as
            | "pending"
            | "approved"
            | "rejected"
            | "suspended",
          email_verified: review.sale.seller.email_verified,
        },
        category: {
          id: review.sale.category.id,
          name: review.sale.category.name,
          slug: review.sale.category.slug,
          description: review.sale.category.description ?? null,
          image_url: review.sale.category.image_url ?? null,
          parent_id: review.sale.category.parent_id ?? null,
          status: typia.assert<"active" | "inactive">(
            review.sale.category.status,
          ),
          display_order: review.sale.category.display_order,
          product_count: review.sale.category.product_count,
          created_at: toISOStringSafe(review.sale.category.created_at),
          updated_at: toISOStringSafe(review.sale.category.updated_at),
        },
      },
      star_rating: review.star_rating,
      review_title: review.review_title ?? null,
      review_body: review.review_body ?? null,
      status: typia.assert<"pending_moderation" | "approved" | "rejected">(
        review.status,
      ),
      is_verified_purchase: review.is_verified_purchase,
      is_anonymous: review.is_anonymous,
      helpfulness_vote_count: review.helpfulness_vote_count,
      created_at: toISOStringSafe(review.created_at),
      updated_at: toISOStringSafe(review.updated_at),
      deleted_at: review.deleted_at ? toISOStringSafe(review.deleted_at) : null,
    })),
    pagination: {
      current: page,
      limit,
