      is_default: shouldBeDefault,
      created_at: now,
      updated_at: now,
    },
  });

  return {
    id: created.id as string & tags.Format<"uuid">,
    shopping_mall_buyer_id: created.shopping_mall_buyer_id as string &
      tags.Format<"uuid">,
