  const paymentMethodId = v4();
  const now = new Date();

  if (props.body.is_default === true) {
    await MyGlobal.prisma.shopping_mall_payment_methods.updateMany({
      where: {
        shopping_mall_buyer_id: props.buyer.id,
        is_default: true,
        deleted_at: null,
      },
      data: {
        is_default: false,
        updated_at: now,
      },
