export async function deleteShoppingMallBuyerReviewsReviewIdHelpfulnessVotesVoteId(props: {
  buyer: BuyerPayload;
  reviewId: string & tags.Format<"uuid">;
  voteId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallReviewHelpfulnessVote> {
